def get_tools_definition(
    collection_names: list[str], *, exclude_chat_only: bool = False
) -> list[dict[str, Any]]:
    """
    Get the tools definition based on available collections and MCP servers.

    Args:
        collection_names: List of available collection names
        exclude_chat_only: If True, exclude tools that only work in chat context

    Returns:
        List of tool definitions including built-in and MCP tools
    """
    CHAT_ONLY_TOOLS = {"transcript_search", "direct_response"}
    from server.database.config.manager import config_manager

    built_in_tools = _get_built_in_tools(collection_names)

    # Filter out disabled tools based on user settings
    user_settings = config_manager.get_user_settings()
    disabled_tools = set(user_settings.get("disabled_tools", ["pubmed_search", "wiki_search"]))

    enabled_tools = [
        tool for tool in built_in_tools if tool["function"]["name"] not in disabled_tools
    ]

    if disabled_tools:
        logger.info(f"Filtered out disabled tools: {disabled_tools}")

    # Hide the literature/RAG tool when the knowledge base has no collections.
    if not collection_names:
        enabled_tools = [
            tool for tool in enabled_tools if tool["function"]["name"] != "get_relevant_literature"
        ]
        logger.info("Knowledge base empty; hid 'get_relevant_literature' tool.")

    # Filter out chat-only tools if requested
    if exclude_chat_only:
        enabled_tools = [
            tool for tool in enabled_tools if tool["function"]["name"] not in CHAT_ONLY_TOOLS
        ]
        logger.info(f"Filtered out chat-only tools: {CHAT_ONLY_TOOLS}")

    # Add MCP tools if available
    try:
        from server.mcp.client import get_mcp_tools_sync

        mcp_tools = get_mcp_tools_sync()
        if mcp_tools:
            # Return the tool definitions (without internal metadata)
            for tool in mcp_tools:
                enabled_tools.append(
                    {
                        "type": tool["type"],
                        "function": tool["function"],
                    }
                )
            logger.info(f"Loaded {len(mcp_tools)} tools from MCP servers")
    except ImportError:
        # MCP not installed, skip
        pass
    except Exception as e:
        logger.error(f"Failed to load MCP tools: {e}")

    return enabled_tools

"""
Search patients by primary condition tool.
"""

import logging
from collections.abc import AsyncGenerator
from typing import Any

from server.chat.streaming.response import (
    end_message,
    status_message,
    tool_response_message,
)
from server.chat.tools._helpers import parse_tool_args
from server.database.repositories.patient_search import search_patients_by_condition

logger = logging.getLogger(__name__)


def format_condition_results(patients: list[dict], query: str) -> str:
    """Format a cohort result as a readable string for the LLM."""
    if not patients:
        return f"No patients found with a primary condition matching '{query}'."

    lines = [f"Found {len(patients)} patient(s) with condition matching '{query}':"]
    for p in patients:
        parts = [f"\n• {p.get('name', 'Unknown')}"]
        if p.get("ur_number"):
            parts.append(f"(UR: {p['ur_number']})")
        if p.get("primary_condition"):
            parts.append(f"[{p['primary_condition']}]")
        if p.get("dob"):
            parts.append(f"DOB: {p['dob']}")
        if p.get("last_encounter_date"):
            parts.append(f"Last seen: {p['last_encounter_date']}")
        if p.get("encounter_count"):
            parts.append(f"({p['encounter_count']} encounter(s))")
        lines.append(" ".join(parts))
        if p.get("encounter_summary"):
            lines.append(f"  Summary: {p['encounter_summary']}")
    return "\n".join(lines)


async def execute(
    tool_call: dict[str, Any],
    _llm_client,
    _config: dict[str, Any],
    message_list: list,
    _context_question_options: dict[str, Any],
) -> AsyncGenerator[dict[str, Any], None]:
    """Execute the search_patients_by_condition tool."""
    logger.info("Executing search_patients_by_condition tool...")
    yield status_message("Searching patients by condition...")

    function_arguments = parse_tool_args(tool_call)

    condition = function_arguments.get("condition")
    limit = function_arguments.get("limit", 20)

    if not condition or not str(condition).strip():
        result_content = "Error: Please provide a condition to search for."
        message_list.append(
            tool_response_message(
                tool_call_id=tool_call.get("id", ""),
                content=result_content,
            )
        )
    else:
        try:
            patients = search_patients_by_condition(condition, limit)
            result_content = format_condition_results(patients, condition)
            message_list.append(
                tool_response_message(
                    tool_call_id=tool_call.get("id", ""),
                    content=result_content,
                )
            )
        except Exception as e:
            logger.error(f"Search patients by condition error: {e}")
            result_content = f"Error searching for patients by condition: {e}"
            message_list.append(
                tool_response_message(
                    tool_call_id=tool_call.get("id", ""),
                    content=result_content,
                )
            )

    yield end_message(function_response={"content": result_content, "citations": []})

