                                                {block.isPartial ? "..." : ""}
                                            </Text>
                                            <IconButton
                                                aria-label={
                                                    isExpanded
                                                        ? "Collapse thinking"
                                                        : "Expand thinking"
                                                }
                                                variant="ghost"
                                                size="xs"
                                                className="chat-disclosure-icon">{isExpanded ? (
                                                    <ChevronUpIcon />
                                                ) : (
                                                    <ChevronDownIcon />
