                                                    </Text>
                                                </Box>
                                            </Collapsible.Content>
                                        </Collapsible.Root>
                                    </Box>
                                );
                            }

                            return null;
                        })}
                    </Box>
                </Collapsible.Content>
            </Collapsible.Root>
        </Box>
    );
};

