import React, { useEffect, useRef, useState } from "react";
import { useColorMode } from "../ui/color-mode";
import { Box } from "@chakra-ui/react";
import { colors } from "../../theme/colors";

/**
 * Shared floating panel wrapper with consistent positioning and optional speech bubble arrow.
 * Used by all floating panels (Chat, Letter, Document, etc.)
 *
 * @param {boolean} isOpen - Whether the panel is visible
 * @param {string} position - "left-of-fab" (right side) or "bottom-center" (above ScribePillBox)
 * @param {boolean} showArrow - Whether to show speech bubble arrow pointing to trigger
 * @param {string} triggerId - ID of the element that triggered the panel, used to align the arrow
 * @param {string} width - Panel width
 * @param {string} height - Panel height
 * @param {string} maxWidth - Maximum panel width
 * @param {string} maxHeight - Maximum panel height
 * @param {string|number} zIndex - Z-index for stacking
 */
const FloatingPanel = ({
    children,
    isOpen,
    position = "left-of-fab",
    showArrow = true,
    triggerId,
    width,
    height,
    maxWidth,
    maxHeight,
    zIndex = "1060",
}) => {
    const { colorMode } = useColorMode();
    const panelRef = useRef(null);
    const [arrowTop, setArrowTop] = useState("50%");
    const [arrowLeft, setArrowLeft] = useState("50%");
    const [minPanelHeight, setMinPanelHeight] = useState("auto");

    useEffect(() => {
        if (!isOpen || !showArrow || !triggerId) {
            setArrowTop("50%");
            setArrowLeft("50%");
            setMinPanelHeight("auto");
            return;
        }

        const updateArrowPosition = () => {
            const triggerEl = document.getElementById(triggerId);
            if (!triggerEl || !panelRef.current) return;
            const triggerRect = triggerEl.getBoundingClientRect();
            const panelRect = panelRef.current.getBoundingClientRect();

            if (
                position === "left-of-fab" ||
                position === "left-of-fab-grow-down"
            ) {
                const menuEl = triggerEl.closest(".floating-action-menu");
                if (menuEl) {
                    setMinPanelHeight(
                        `${menuEl.getBoundingClientRect().height}px`,
                    );
                }
                setArrowTop(
                    `${triggerRect.top + triggerRect.height / 2 - panelRect.top}px`,
                );
            } else if (
                position === "bottom-center" ||
                position === "above-transcript-button"
            ) {
                setArrowLeft(
                    `${triggerRect.left + triggerRect.width / 2 - panelRect.left}px`,
                );
            }
        };

        const frameId = requestAnimationFrame(updateArrowPosition);
        window.addEventListener("resize", updateArrowPosition);
        let resizeObserver;
        if (panelRef.current && typeof ResizeObserver !== "undefined") {
            resizeObserver = new ResizeObserver(() => updateArrowPosition());
            resizeObserver.observe(panelRef.current);
        }

        return () => {
            cancelAnimationFrame(frameId);
            window.removeEventListener("resize", updateArrowPosition);
            resizeObserver?.disconnect();
        };
    }, [isOpen, showArrow, triggerId, position, height, width]);

    if (!isOpen) return null;

    const getPositionStyles = () => {
        switch (position) {
            case "left-of-fab":
                return {
                    right: "110px",
                    top: "50%",
                    transform: "translateY(-50%)",
                };
            case "left-of-fab-grow-down":
                return {
                    right: "110px",
                    top: "calc(50% - 110px)",
                };
            case "above-transcript-button":
                return {
                    bottom: "85px",
                    right: "calc(50% - 90px)",
                };
            case "bottom-center":
            default:
                return {
                    bottom: "100px",
                    left: "50%",
                    transform: "translateX(-50%)",
                };
        }
    };

    const positionStyles = getPositionStyles();

    // Get colors for the arrow to match the panel
    const bgColor =
        colorMode === "light" ? colors.light.secondary : colors.dark.secondary;
    const borderColor =
        colorMode === "light" ? colors.light.surface : colors.dark.surface;

    return (
        <Box
            ref={panelRef}
            position="fixed"
            {...positionStyles}
            width={width}
            height={height}
            minHeight={minPanelHeight}
            maxWidth={maxWidth}
            maxHeight={maxHeight}
            zIndex={zIndex}
            pointerEvents="auto"
            display="flex"
            flexDirection="column"
        >
            <Box
                className="anim-emerge-spring"
                width="100%"
                height="100%"
                flex="1"
                maxWidth={maxWidth}
                maxHeight={maxHeight}
                position="relative"
            >
                <Box
                    width="100%"
                    height="100%"
                    className="floating-panel"
                    overflow="hidden"
                >
                    {children}
                </Box>

                {/* Isthmus / Arrow */}
                {showArrow &&
                    (position === "left-of-fab" ||
                        position === "left-of-fab-grow-down") && (
                    <Box
                        position="absolute"
                        right="-12px"
                        top={arrowTop}
                        transform="translateY(-50%)"
                        width="13px"
                        height="24px"
                        viewBox="4 0 6 24"
                        zIndex="1"
                        asChild
                    >
                        <svg>
                            <path
                                d="M 0 0.5 Q 7 8 14 0.5 L 14 23.5 Q 7 16 0 23.5 Z"
                                fill={bgColor}
                            />
                            <path
                                d="M 0 0.5 Q 7 8 14 0.5"
                                fill="none"
                                stroke={borderColor}
                                strokeWidth="1"
                            />
                            <path
                                d="M 0 23.5 Q 7 16 14 23.5"
                                fill="none"
                                stroke={borderColor}
                                strokeWidth="1"
                            />
                        </svg>
                    </Box>
                )}
                {showArrow &&
                    (position === "bottom-center" ||
                        position === "above-transcript-button") && (
                        <Box
                            position="absolute"
                            bottom="-15px"
                            left={arrowLeft}
                            transform="translateX(-50%)"
                            width="24px"
                            height="16px"
                            viewBox="0 0 24 16"
                            zIndex="1"
                            asChild
                        >
                            <svg>
                                <path
                                    d="M 0.5 0 Q 8 8 0.5 16 L 23.5 16 Q 16 8 23.5 0 Z"
                                    fill={bgColor}
                                />
                                <path
                                    d="M 0.5 0 Q 8 8 0.5 16"
                                    fill="none"
                                    stroke={borderColor}
                                    strokeWidth="1"
                                />
                                <path
                                    d="M 23.5 0 Q 16 8 23.5 16"
                                    fill="none"
                                    stroke={borderColor}
                                    strokeWidth="1"
                                />
                            </svg>
                        </Box>
                    )}
            </Box>
        </Box>
    );
};

export default FloatingPanel;

import React from "react";
import ReactMarkdown from "react-markdown";
import { Box, Text, Link, Popover } from "@chakra-ui/react";
import remarkGfm from "remark-gfm";
import { FaTimes, FaWikipediaW, FaBookMedical, FaDatabase, FaGlobe } from "react-icons/fa";
import { expandCitationNumbers } from "@/utils/chat/messageParser";

/**
 * Remark plugin: turn ``[N]`` and grouped ``[N, M]`` tokens in text into
 * citation link nodes (``#citation-N``) consumed by the ``a`` handler below.
 * Manual mdast walk — no extra dependency on unist-util-visit.
 */
const remarkInlineCitations = () => (tree) => {
    const GROUP_RE = /\[(\d+(?:\s*[-,]\s*\d+)*)\]/g;
    const walk = (node) => {
        if (!node.children) return;
        const next = [];
        for (const child of node.children) {
            if (child.type === "text" && child.value.includes("[")) {
                let last = 0;
                let m;
                GROUP_RE.lastIndex = 0;
                let matchedAny = false;
                while ((m = GROUP_RE.exec(child.value)) !== null) {
                    matchedAny = true;
                    if (m.index > last) {
                        next.push({ type: "text", value: child.value.slice(last, m.index) });
                    }
                    // Expand ranges (1-3) and lists (1,2) into one pill per number.
                    for (const num of expandCitationNumbers(m[1])) {
                        next.push({
                            type: "link",
                            url: `#citation-${num}`,
                            children: [{ type: "text", value: String(num) }],
                        });
                    }
                    last = m.index + m[0].length;
                }
                if (matchedAny && last < child.value.length) {
                    next.push({ type: "text", value: child.value.slice(last) });
                }
                if (!matchedAny) next.push(child);
            } else {
                next.push(child);
                walk(child);
            }
        }
        node.children = next;
    };
    walk(tree);
};

const normalizeCitation = (c) => {
    if (c == null) return null;
    if (typeof c === "string") return { type: "string", label: c };
    return c;
};

const TYPE_ICONS = {
    wiki: FaWikipediaW,
    pubmed: FaBookMedical,
    literature: FaDatabase,
    other: FaGlobe,
};

const iconFor = (c) => {
    if (c?.type && TYPE_ICONS[c.type]) return TYPE_ICONS[c.type];
    const label = (c?.label || "").toLowerCase();
    if (label.includes("wikipedia") || label.includes("wiki:"))
        return FaWikipediaW;
    if (label.includes("pubmed")) return FaBookMedical;
    if (label.includes("clinical guidelines") || label.includes("according to"))
        return FaDatabase;
    return FaGlobe;
};

const pillVisual = (Icon, index, { as = "span", ...rest } = {}) => (
    <Text
        as={as}
        type={as === "button" ? "button" : undefined}
        display="inline-flex"
        alignItems="center"
        gap="3px"
        verticalAlign="middle"
        ml="2px"
        mr="2px"
        bg="surfaceMuted"
        border="1px solid"
        borderColor="accent"
        borderRadius="full"
        px="7px"
        h="22px"
        cursor="pointer"
        fontSize="11px"
        fontWeight="bold"
        lineHeight={1}
        color="primaryButton"
        _dark={{
            bg: "surfaceMuted",
            borderColor: "accent",
            color: "primaryButton",
        }}
        _hover={{
            bg: "surfaceMuted",
            _dark: { bg: "surfaceMuted" },
        }}
        {...rest}
    >
        <Icon style={{ fontSize: "11px", flexShrink: 0 }} />
        {index}
    </Text>
);

const CitationTag = ({ index, citation, displayLabel }) => {
    const c = normalizeCitation(citation);
    const url = c?.url;
    const title = c?.title || c?.source || c?.label || `Source ${index}`;
    const snippet = c?.snippet;
    const icon = iconFor(c);
    const [open, setOpen] = React.useState(false);
    const label = displayLabel ?? index;

    if (!c) {
        return (
            <Text
                as="sup"
                ml="1px"
                color="primaryButton"
                fontSize="xs"
                fontWeight="bold"
                verticalAlign="super"
            >
                {index}
            </Text>
        );
    }

    const isInternal = url && url.startsWith("/");
    const footerLabel = isInternal
        ? "⬇ Download PDF"
        : url
          ? "Open source ↗"
          : null;

    const openUrl = (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (!url) return;
        if (isInternal) {
            const a = document.createElement("a");
            a.href = url;
            a.download = "";
            document.body.appendChild(a);
            a.click();
            a.remove();
        } else {
            window.open(url, "_blank", "noopener");
        }
    };

    return (
        <Popover.Root
            open={open}
            onOpenChange={(details) => setOpen(details.open)}
