                            border="none"
                            cursor="pointer"
                            padding="2px"
                            color="textSecondary"
                            opacity={0.6}
                            _hover={{ opacity: 1 }}
                            aria-label="Close"
                            flexShrink={0}
                            display="flex"
                            alignItems="center"
