    {isFetchingTemplates ? (
      <Flex align="center" justify="center" py={8}>
        <Spinner size="lg" color="primaryButton" />
        <Text ml={4} color="textSecondary">Loading templates...</Text>
      </Flex>
    ) : (
      <SimpleGrid columns={{ base: 1, md: 2 }} gap={3} w="100%">
        {availableTemplates.map((template, index) => {
          const isSelected = selectedTemplate === template.template_key;
          const accent = TEMPLATE_COLORS[index % TEMPLATE_COLORS.length];

          return (
            <Box
              key={template.template_key}
              position="relative"
              overflow="hidden"
              cursor="pointer"
              onClick={() => setSelectedTemplate(template.template_key)}
              p={3}
              pl={4}
              borderRadius="xl"
              borderWidth="1px"
              borderColor={isSelected ? accent : "border"}
              bg={isSelected ? "primaryButtonFaint" : "secondary"}
              _hover={{
                borderColor: accent,
                shadow: "sm",
              }}
              transition="all 0.2s ease"
            >
              {/* Colored accent strip */}
              <Box
                position="absolute"
                left={0}
                top={0}
                bottom={0}
                width="4px"
                bg={accent}
                opacity={isSelected ? 1 : 0.5}
                transition="opacity 0.2s ease"
              />

              <HStack justify="space-between" mb={1}>
                <Text fontSize="sm" fontWeight="bold" color="textPrimary">
                  {template.template_name}
                </Text>
                {isSelected && (
                  <Icon color={accent} boxSize={4} asChild>
                    <FaCheckCircle />
                  </Icon>
                )}
              </HStack>
              <Text fontSize="xs" color="textSecondary" lineHeight="1.4">
                {TEMPLATE_DESCRIPTIONS[template.template_key] ||
                  "A custom template for clinical documentation."}
              </Text>
            </Box>
          );
        })}
      </SimpleGrid>
    )}
  </VStack>
);

import React, { useState, useEffect, useRef } from "react";
import { Box, Flex, VStack, Text, Button } from "@chakra-ui/react";
import { InfoIcon, SearchIcon, QuestionIcon } from "../common/icons";
import { useChat } from "../../utils/hooks/useChat";
import DashboardChatInput from "./DashboardChatInput";
import DashboardTodoPanel from "./DashboardTodoPanel";
import DashboardMessageList from "./DashboardMessageList";
import { chatApi } from "../../utils/api/chatApi";
import { settingsApi } from "../../utils/api/settingsApi";
import { SPECIALTY_SUGGESTIONS } from "../../utils/constants";
import { useDashboardTodos } from "../../utils/hooks/useDashboardTodos";
import {
    convertFileToDataUrl,
    extractPdfTextOrRenderForVision,
    isPdfFile,
} from "../../utils/helpers/pdfVisionHelpers";

const normalizeProcessingMode = (value) => {
    const mode = String(value || "")
        .trim()
        .toLowerCase();
    if (mode === "vision" || mode === "ocr" || mode === "auto") return mode;
    return "auto";
};

const pickSuggestions = (specialty) => {
    const pool =
        SPECIALTY_SUGGESTIONS[String(specialty || "").trim().toLowerCase()] ||
        SPECIALTY_SUGGESTIONS["general practice"];
    return [...pool].sort(() => Math.random() - 0.5).slice(0, 3);
};

const DashboardChat = () => {
    const {
        messages,
        setMessages,
        userInput,
        setUserInput,
        showSuggestions,
        setShowSuggestions,
        loading: chatLoading,
        sendMessage,
    } = useChat({ mode: "rag" });

    const messagesEndRef = useRef(null);
    const scrollContainerRef = useRef(null);
    const userIsNearBottomRef = useRef(true);
    const [ragSuggestions, setRagSuggestions] = useState([]);
    const [pendingImage, setPendingImage] = useState(null);
    const [isProcessingImage, setIsProcessingImage] = useState(false);
    const [isIntroFading, setIsIntroFading] = useState(false);
    const [documentImageMode, setDocumentImageMode] = useState("auto");
    const [visionCapable, setVisionCapable] = useState(false);

    const {
        todos,
        visibleTodos,
        newTodo,
        setNewTodo,
        showAllTodos,
        setShowAllTodos,
        isCollapsed: isTodoPanelCollapsed,
        toggleCollapsed: toggleTodoPanelCollapsed,
        isLoading: isTodosLoading,
        isSaving: isTodosSaving,
        addTodo,
        toggleTodo,
        deleteTodo,
        handleTodoKeyDown,
    } = useDashboardTodos({
        initialShowAll: false,
        initialCollapsed: true,
    });

    // Filter out system messages for rendering while preserving original index
    const visibleMessages = messages
        .map((message, messageIndex) => ({ message, messageIndex }))
        .filter(({ message }) => message.role !== "system");

    // Determine if chat has started
    const hasMessages = visibleMessages.length > 0;

    // Scroll to bottom when messages change (only if user is near bottom)
    useEffect(() => {
        if (messagesEndRef.current && hasMessages && userIsNearBottomRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: "smooth" });
        }
    }, [messages, hasMessages]);

    // Fetch suggestions on mount
    useEffect(() => {
        const fetchInitialChatSettings = async () => {
            try {
                const [userSettings, globalConfig] = await Promise.all([
                    settingsApi.fetchUserSettings(),
                    settingsApi.fetchConfig(),
                ]);

                if (userSettings.specialty) {
                    setRagSuggestions(pickSuggestions(userSettings.specialty));
                }

                if (globalConfig) {
                    setDocumentImageMode(
                        normalizeProcessingMode(
                            globalConfig?.DOCUMENT_IMAGE_PROCESSING_MODE,
                        ),
                    );

                    try {
                        const capability =
                            await chatApi.getCurrentVisionCapability();
                        setVisionCapable(Boolean(capability?.vision_capable));
                    } catch (capabilityError) {
                        console.warn(
                            "Failed to load cached vision capability, falling back to legacy flag:",
                            capabilityError,
                        );
                        setVisionCapable(
                            Boolean(globalConfig?.VISION_MODEL_CAPABLE),
                        );
                    }
                }
            } catch (error) {
                console.error("Error fetching initial chat settings:", error);
            }
        };
        fetchInitialChatSettings();
    }, []);

    const handleImageSelect = (file) => {
        setPendingImage(file);
    };

    const handleImageRemove = () => {
        setPendingImage(null);
    };

    const handleSendMessage = async (message) => {
        const text = message || userInput;
        if (!text?.trim()) return;

        if (!hasMessages && !isIntroFading) {
            setIsIntroFading(true);
            await new Promise((resolve) => setTimeout(resolve, 240));
        }

        sendMessage(text);
        setShowSuggestions(false);
    };

    const handleUserInputSend = async () => {
        const hasText = userInput.trim();
        const hasImage = pendingImage;

        if (!hasText && !hasImage) return;

        // If there's an image/document, process it first
        if (hasImage) {
            setIsProcessingImage(true);
            try {
                const messageText = userInput.trim();
                let extractedText = "";
                let filename = pendingImage.name || "uploaded file";
                let fileType =
                    pendingImage.type ||
                    (isPdfFile(pendingImage) ? "application/pdf" : "image/*");

                if (isPdfFile(pendingImage)) {
                    // Frontend-first PDF strategy:
                    // 1) Try direct text extraction
                    // 2) If insufficient text, render pages to images and ask visual backend
                    const pdfResult =
                        await extractPdfTextOrRenderForVision(pendingImage);

                    if (pdfResult.strategy === "text") {
                        extractedText = pdfResult.textResult.text || "";
                    } else {
                        try {
                            const visualResult =
                                await chatApi.analyzeVisualDocument({
                                    filename,
                                    content_type: "application/pdf",
                                    strategy: "vision",
                                    pages: (
                                        pdfResult.imageResult?.images || []
                                    ).map((img) => ({
                                        page_number: img.pageNumber,
                                        data_url: img.dataUrl,
                                        mime_type: img.mimeType,
                                        width: img.width,
                                        height: img.height,
                                    })),
                                    fallback_text:
                                        pdfResult.textResult?.text || "",
                                    extraction_info: {
                                        reason:
                                            pdfResult.textResult?.quality
                                                ?.reason ||
                                            "No usable embedded PDF text",
                                        stats:
                                            pdfResult.textResult?.quality
                                                ?.stats || {},
                                        page_count:
                                            pdfResult.textResult?.pageCount ||
                                            0,
                                        processed_pages:
                                            pdfResult.textResult
                                                ?.processedPages || 0,
                                        rendered_pages:
                                            pdfResult.imageResult
                                                ?.renderedPages || 0,
                                    },
                                });

                            extractedText = visualResult.text || "";
                        } catch (visionError) {
                            console.warn(
                                "Visual PDF analysis unavailable, falling back to OCR endpoint:",
                                visionError,
                            );
                            const result =
                                await chatApi.uploadImage(pendingImage);
                            extractedText = result.text || "";
                            filename = result.filename || filename;
                            fileType = result.content_type || fileType;
                        }
                    }
                } else {
                    // Non-PDF image flow with mode controls:
                    // - vision: direct visual chat response only
                    // - auto: direct visual response if endpoint/model is marked vision-capable, else OCR fallback
                    // - ocr: legacy OCR upload endpoint
                    const mode = normalizeProcessingMode(documentImageMode);
                    let effectiveVisionCapable = visionCapable;

                    if (mode === "auto" || mode === "vision") {
                        try {
                            const capability =
                                await chatApi.getCurrentVisionCapability();
                            effectiveVisionCapable = Boolean(
                                capability?.vision_capable,
                            );
                            setVisionCapable(effectiveVisionCapable);
                        } catch (capabilityError) {
                            console.warn(
                                "Failed to refresh cached vision capability for chat image flow:",
                                capabilityError,
                            );
                        }
                    }

                    const useVisionDirectly =
                        mode === "vision" ||
                        (mode === "auto" && effectiveVisionCapable);
                    const allowOcrFallback = mode !== "vision";

                    if (useVisionDirectly) {
                        try {
                            const imageDataUrl =
                                await convertFileToDataUrl(pendingImage);

                            const visualPrompt =
                                messageText || "Please analyze this image.";
                            const visualResponse = await chatApi.respondVisual({
                                prompt: visualPrompt,
                                filename,
                                content_type: fileType,
                                pages: [
                                    {
                                        page_number: 1,
                                        data_url: imageDataUrl,
                                        mime_type: fileType || "image/png",
                                    },
                                ],
                            });

                            const userVisibleText =
                                messageText || "Analyze attached image";

                            setPendingImage(null);
                            setUserInput("");
                            setIsProcessingImage(false);

                            setMessages((prev) => [
                                ...prev,
                                {
                                    role: "user",
                                    content: userVisibleText,
                                    attachments: [
                                        {
                                            filename,
                                            type: fileType,
                                            extractedText: "",
                                        },
                                    ],
                                },
                                {
                                    role: "assistant",
                                    content:
                                        visualResponse.answer ||
                                        "I couldn't analyze that image.",
                                },
                            ]);
                            return;
                        } catch (visionError) {
                            if (!allowOcrFallback) {
                                throw visionError;
                            }
                            console.warn(
                                "Direct visual chat failed, falling back to OCR endpoint:",
                                visionError,
                            );
                        }
                    }

                    // OCR fallback (auto/ocr modes)
                    const result = await chatApi.uploadImage(pendingImage);
                    extractedText = result.text || "";
                    filename = result.filename || filename;
                    fileType = result.content_type || fileType;
                }

                // Build attachment object for UI display
                const attachment = {
                    filename,
                    type: fileType,
                    extractedText,
                };

                // Clear the pending image and input
                setPendingImage(null);
                setUserInput("");
                setIsProcessingImage(false);

                // Send message with attachment (extracted text handled by useChat)
                sendMessage(messageText, null, null, null, [attachment]);
            } catch (error) {
                console.error("Error processing image/document:", error);
                setIsProcessingImage(false);
                // Still send the text message if there is one
                if (hasText) {
                    sendMessage(userInput);
                    setUserInput("");
                    setPendingImage(null);
                }
            }
        } else {
            // Just text, send normally
            await handleSendMessage(userInput);
            setUserInput("");
        }
    };

    // Empty state - centered input
    if (!hasMessages) {
        return (
            <Flex
                className="dashboard-chat-container"
                direction="column"
                align="center"
                justify="center"
                px="20px"
                opacity={isIntroFading && !isProcessingImage ? 0 : 1}
                transition="opacity 0.35s ease"
                pointerEvents={
                    isIntroFading && !isProcessingImage ? "none" : "auto"
                }
            >
                <VStack gap={8} w="100%" maxW="800px">
                    {/* Greeting */}
                    <VStack gap={2}>
                        <Text
                            fontSize="2xl"
                            fontWeight="bold"
                            fontFamily="heading"
                            className="dashboard-chat-greeting"
                        >
                            How can I help you today?
                        </Text>
                        <Text fontSize="md" color="overlay0">
                            Ask about patients, evidence, or outstanding jobs
                        </Text>
                    </VStack>

                    {/* Suggestions */}
                    {showSuggestions && ragSuggestions.length > 0 && (
                        <Flex
                            wrap="wrap"
                            justify="center"
                            gap={3}
                            className="anim-stagger"
                        >
                            {ragSuggestions.map((suggestion, index) => (
                                <Button
                                    key={index}
                                    onClick={() =>
                                        handleSendMessage(suggestion)
                                    }
                                    className="dashboard-chat-suggestions"
                                    size="sm">{
                                        index === 0 ? (
                                            <InfoIcon />
                                        ) : index === 1 ? (
                                            <SearchIcon />
                                        ) : (
                                            <QuestionIcon />
                                        )
                                    }{suggestion}</Button>
                            ))}
                        </Flex>
                    )}

                    {/* Centered Input + overlay todo panel (does not affect intro layout flow) */}
                    <Box w="100%" maxW="800px" position="relative">
                        <DashboardChatInput
                            value={userInput}
                            onChange={(e) => {
                                setUserInput(e.target.value);
                                if (showSuggestions) setShowSuggestions(false);
                            }}
                            onSend={handleUserInputSend}
                            isLoading={chatLoading}
                            position="centered"
                            pendingImage={pendingImage}
                            onImageSelect={handleImageSelect}
                            onImageRemove={handleImageRemove}
                            isProcessingImage={isProcessingImage}
                        />

                        <Box
                            position="absolute"
                            top="calc(100% + 8px)"
                            left="0"
                            right="0"
                            zIndex={2}
                            pointerEvents="none"
                        >
                            <Box pointerEvents="auto">
                                <DashboardTodoPanel
                                    todos={todos}
                                    visibleTodos={visibleTodos}
                                    newTodo={newTodo}
                                    setNewTodo={setNewTodo}
                                    showAllTodos={showAllTodos}
                                    setShowAllTodos={setShowAllTodos}
                                    isCollapsed={isTodoPanelCollapsed}
                                    toggleCollapsed={toggleTodoPanelCollapsed}
                                    isLoading={isTodosLoading}
                                    isSaving={isTodosSaving}
                                    addTodo={addTodo}
                                    toggleTodo={toggleTodo}
                                    deleteTodo={deleteTodo}
                                    handleTodoKeyDown={handleTodoKeyDown}
                                />
                            </Box>
                        </Box>
                    </Box>
                </VStack>
            </Flex>
        );
    }

    // Active chat state - messages at top, input at bottom
    return (
        <Box
            className="dashboard-chat-container"
            display="flex"
            flexDirection="column"
            h="100%"
            position="relative"
            pt="60px"
        >
            {/* Messages Area - scrollable middle */}
            <Box
                ref={scrollContainerRef}
                className="dashboard-chat-messages"
                flex="1"
                overflowY="auto"
                px="0"
                onScroll={() => {
                    const el = scrollContainerRef.current;
                    if (el) {
                        userIsNearBottomRef.current =
                            el.scrollHeight - el.scrollTop - el.clientHeight < 60;
                    }
                }}
            >
                <DashboardMessageList
                    visibleMessages={visibleMessages}
                    setMessages={setMessages}
                    messagesEndRef={messagesEndRef}
                />
            </Box>

            {/* Bottom Input */}
            <DashboardChatInput
                value={userInput}
                onChange={(e) => setUserInput(e.target.value)}
                onSend={handleUserInputSend}
                isLoading={chatLoading}
                position="bottom"
                showDisclaimer={true}
                pendingImage={pendingImage}
                onImageSelect={handleImageSelect}
                onImageRemove={handleImageRemove}
                isProcessingImage={isProcessingImage}
            />
        </Box>
    );
};

export default DashboardChat;

import React, { useState, useRef, useEffect } from "react";
import {
    Box,
    Flex,
    Textarea,
    IconButton,
    Text,
    Image,
    HStack,
    Spinner,
    Input,
    Icon,
} from "@chakra-ui/react";
import { ArrowUpIcon, AttachmentIcon, CloseIcon } from "../common/icons";
import { FaFilePdf } from "react-icons/fa";

const VALID_IMAGE_TYPES = [
    "image/png",
    "image/jpeg",
    "image/jpg",
    "image/gif",
    "application/pdf",
];

const MIN_TEXTAREA_HEIGHT = 32;
const MAX_TEXTAREA_HEIGHT = 72; // ~3 lines, then scroll

const DashboardChatInput = ({
    value,
    onChange,
    onSend,
    isLoading,
    placeholder = "Message Phlox...",
    position = "centered", // "centered" | "bottom"
    showDisclaimer = true,
    pendingImage,
    onImageSelect,
    onImageRemove,
    isProcessingImage,
}) => {
    const [isDragOver, setIsDragOver] = useState(false);

    const fileInputRef = useRef(null);
    const textareaRef = useRef(null);

    const isBottom = position === "bottom";
    const inputValue = value || "";

    const resizeTextarea = () => {
        const textarea = textareaRef.current;
        if (!textarea) return;

        textarea.style.height = "auto";
        const nextHeight = Math.min(textarea.scrollHeight, MAX_TEXTAREA_HEIGHT);
        textarea.style.height = `${Math.max(nextHeight, MIN_TEXTAREA_HEIGHT)}px`;
        textarea.style.overflowY =
            textarea.scrollHeight > MAX_TEXTAREA_HEIGHT ? "auto" : "hidden";
    };

    useEffect(() => {
        resizeTextarea();
    }, [inputValue]);

    const handleKeyDown = (e) => {
        if (e.key === "Enter" && !e.shiftKey) {
            e.preventDefault();
            if (!isProcessingImage) {
                onSend();
            }
        }
    };

    const handleTextChange = (e) => {
        if (onChange) onChange(e);
        resizeTextarea();
    };

    const handleDragOver = (e) => {
        e.preventDefault();
        setIsDragOver(true);
    };

    const handleDragLeave = (e) => {
        e.preventDefault();
        setIsDragOver(false);
    };

    const handleDrop = (e) => {
        e.preventDefault();
        setIsDragOver(false);

        const files = e.dataTransfer?.files;
        if (!files || files.length === 0) return;

        const file = files[0];
        if (
            VALID_IMAGE_TYPES.includes(file.type) ||
            file.name.match(/\.(png|jpe?g|gif|pdf)$/i)
        ) {
            if (onImageSelect) {
                onImageSelect(file);
            }
        }
    };

    const handleFileSelect = (e) => {
        const file = e.target.files?.[0];
        if (file && onImageSelect) {
            onImageSelect(file);
        }

        if (fileInputRef.current) {
            fileInputRef.current.value = "";
        }
    };

    const canSend =
        (inputValue.trim() || pendingImage) && !isLoading && !isProcessingImage;

    return (
        <Flex
            position="relative"
            direction="column"
            align="center"
            w="100%"
            maxW="800px"
            mx="auto"
            px="20px"
            pt={isBottom ? "2" : "0"}
            pb={isBottom ? "0" : "0"}
            flex="0 0 auto"
        >
            {isDragOver && (
                <Flex
                    position="absolute"
                    top={0}
                    left={0}
                    right={0}
                    bottom={0}
                    align="center"
                    justify="center"
                    bg="primaryButtonFaint"
                    borderWidth="2px"
                    borderStyle="dashed"
                    borderColor="accent"
                    borderRadius="lg"
                    zIndex={20}
                    pointerEvents="none"
                >
                    <Text fontWeight="bold" color="primaryButton">
                        Drop image or PDF here
                    </Text>
                </Flex>
            )}
            <Box
                className="dashboard-chat-input-container"
                w="100%"
                transition="all 0.3s ease"
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
                position="relative"
            >
                {pendingImage && (
                    <HStack
                        gap={2}
                        mb={2}
                        px={2}
                        py={1.5}
                        borderRadius="md"
                        bg="surfaceMuted"
                        maxW="33%"
                    >
                        {pendingImage.type.startsWith("image/") ? (
                            <Image
                                src={URL.createObjectURL(pendingImage)}
                                alt="Preview"
                                boxSize="20px"
                                borderRadius="sm"
                                objectFit="cover"
                                flexShrink={0}
                            />
                        ) : (
                            <Icon
                                boxSize={3.5}
                                color="dangerButton"
                                flexShrink={0}
                                asChild
                            >
                                <FaFilePdf />
                            </Icon>
                        )}
                        <Text fontSize="xs" flex="1" isTruncated>
                            {pendingImage.name}
                        </Text>
                        {isProcessingImage && (
                            <Spinner size="xs" flexShrink={0} />
                        )}
                        <IconButton
                            size="xs"
                            variant="ghost"
                            aria-label="Remove file"
                            onClick={onImageRemove}
                            disabled={isProcessingImage}
                            flexShrink={0}
                            minW="auto"
                            h="auto"
                            p={0.5}
                        >
                            <CloseIcon />
                        </IconButton>
                    </HStack>
                )}

                <Textarea
                    ref={textareaRef}
                    value={inputValue}
                    onChange={handleTextChange}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholder}
                    rows={1}
                    resize="none"
                    variant="unstyled"
                    w="100%"
                    minH={`${MIN_TEXTAREA_HEIGHT}px`}
                    maxH={`${MAX_TEXTAREA_HEIGHT}px`}
                    py="1.5"
                    px="3"
                    lineHeight="1.35"
                    color="textPrimary"
                    _placeholder={{
                        color: "textQuaternary",
                    }}
                    fontSize="md"
                    disabled={isLoading || isProcessingImage}
                    _focusVisible={{ boxShadow: "none" }}
                />

                <Flex align="center" justify="space-between" mt={1}>
                    <HStack gap={1}>
                        <IconButton
                            onClick={() => fileInputRef.current?.click()}
                            disabled={isLoading || isProcessingImage}
                            aria-label="Attach image or PDF"
                            size="sm"
                            variant="ghost"
                            color="textQuaternary"
                            _hover={{
                                bg: "hoverOverlay",
                            }}
                        >
                            <AttachmentIcon />
                        </IconButton>
                        <Input
                            type="file"
                            ref={fileInputRef}
                            onChange={handleFileSelect}
                            display="none"
                            accept="image/png,image/jpeg,image/jpg,image/gif,.png,.jpg,.jpeg,.gif,.pdf"
                        />
                    </HStack>

                    <IconButton
                        onClick={onSend}
                        disabled={!canSend}
                        loading={isLoading}
                        aria-label="Send message"
                        size="sm"
                        alignSelf="center"
                        borderRadius="full"
                        bg={canSend ? "sendButton" : "sendButtonDisabled"}
                        color={canSend ? "sendButtonText" : "sendButtonTextDisabled"}
                        _hover={{
                            bg: canSend
                                ? "sendButtonHover"
                                : "sendButtonHoverDisabled",
                            transform: "scale(1.05)",
                        }}
                        transition="all 0.2s ease"
                    >
                        <ArrowUpIcon />
                    </IconButton>
                </Flex>
            </Box>
            {showDisclaimer && (
                <Text
                    textAlign="center"
                    fontSize="xs"
                    color="overlay0"
                    mt={2}
                    opacity={0.8}
                >
                    Phlox may make mistakes. Always verify critical information.
                </Text>
            )}
        </Flex>
    );
};

export default DashboardChatInput;

import React, { useState } from "react";
import { useColorMode } from "../ui/color-mode";
import { Box, Flex, VStack, HStack, Text, Spinner, Badge, Icon, Image } from "@chakra-ui/react";
import { AttachmentIcon } from "../common/icons";
import { FaFilePdf, FaFileImage } from "react-icons/fa";
import MarkdownRenderer from "../common/MarkdownRenderer";
import ArtifactCard from "../common/ArtifactCard";
import {
    parseMessageContent,
    buildCitationRemap,
} from "../../utils/chat/messageParser";
import { groupActivityTrace } from "../../utils/chat/activityTrace";
import ActivityTraceBlock from "../common/ActivityTraceBlock";
import { CitationList } from "../panels/reasoning/components/CitationList";

const DashboardMessageList = ({
    visibleMessages = [],
    setMessages,
    messagesEndRef,
}) => {
    const [expandedToolBlocks, setExpandedToolBlocks] = useState({});
    const { colorMode } = useColorMode();

    const getThinkingBlockState = (message, blockIndex = 0) => {
        if (!message) return false;
        const expandedMap = message.thinkingExpandedBlocks || {};
        return Boolean(expandedMap[blockIndex]);
    };

    const toggleThinkingVisibility = (messageIndex, blockIndex = 0) => {
        if (!setMessages) return;

        setMessages((prevMessages) =>
            prevMessages.map((msg, idx) => {
                if (idx !== messageIndex) return msg;

                const currentMap = msg.thinkingExpandedBlocks || {};
                const nextExpanded = !currentMap[blockIndex];

                return {
                    ...msg,
                    thinkingExpandedBlocks: {
                        ...currentMap,
                        [blockIndex]: nextExpanded,
                    },
                    isThinkingExpanded:
                        blockIndex === 0
                            ? nextExpanded
                            : msg.isThinkingExpanded,
                };
            }),
        );
    };

    const toggleToolExpanded = (messageIndex, blockIndex) => {
        const key = `${messageIndex}:${blockIndex}`;
        setExpandedToolBlocks((prev) => ({
            ...prev,
            [key]: !prev[key],
        }));
    };

    return (
        <VStack
            gap={2}
            align="stretch"
            w="100%"
            maxW="800px"
            mx="auto"
            px="20px"
        >
            {visibleMessages.map(({ message, messageIndex }) => {
                const parsed = parseMessageContent(message.content || "");
                const rawBlocks =
                    parsed?.blocks && parsed.blocks.length > 0
                        ? parsed.blocks
                        : [{ type: "text", content: message.content || "" }];

                const blocks = groupActivityTrace(rawBlocks);

                const allCitations = Object.values(
                    message.context || {},
                ).filter(Boolean);
                const { remap, citedOriginals } = buildCitationRemap(
                    parsed?.visibleText || "",
                );
                const footerOriginals =
                    citedOriginals.length > 0 ? citedOriginals : null;

                return (
                    <Flex
                        key={`message-${messageIndex}`}
                        justify={
                            message.role === "assistant"
                                ? "flex-start"
                                : "flex-end"
                        }
                    >
                        <Box
                            className={`message-box ${message.role}`}
                            maxWidth={message.role === "assistant" ? "92%" : "80%"}
                            px={message.role === "assistant" ? 0 : 3}
                            py={message.role === "assistant" ? 0 : 2}
                            bg={message.role === "assistant" ? "transparent" : undefined}
                            borderWidth={message.role === "assistant" ? "0" : undefined}
                            boxShadow={message.role === "assistant" ? "none" : undefined}
                            position="relative"
                        >
                            {message.loading ? (
                                <Spinner size="sm" />
                            ) : (
                                <VStack align="start" gap={0.5} width="100%">
                                    {message.role === "assistant" && (
                                        <HStack gap={2} mb={0.5}>
                                            <Image
                                                src="/logo.webp"
                                                alt="Phlox Logo"
                                                h="16px"
                                                w="auto"
                                                objectFit="contain"
                                            />
                                            <Text
                                                fontSize="xs"
                                                fontWeight="semibold"
                                                color="overlay0"
                                            >
                                                Phlox Assistant
                                            </Text>
                                        </HStack>
                                    )}

                                    {message.role === "user" &&
                                        message.attachments?.length > 0 && (
                                            <HStack gap={1} mb={1} flexWrap="wrap">
                                                {message.attachments.map((att, i) => {
                                                    const isPdf =
                                                        att.type === "application/pdf";
                                                    const isImage =
                                                        att.type?.startsWith("image/");

                                                    return (
                                                        <Badge
                                                            key={i}
                                                            size="sm"
                                                            variant="subtle"
                                                            colorPalette={
                                                                isPdf
                                                                    ? "red"
                                                                    : isImage
                                                                      ? "blue"
                                                                      : "gray"
                                                            }
                                                            borderRadius="md"
                                                            px={2}
                                                            py={1}
                                                        >
                                                            <Icon
                                                                as={
                                                                    isPdf
                                                                        ? FaFilePdf
                                                                        : isImage
                                                                          ? FaFileImage
                                                                          : AttachmentIcon
                                                                }
                                                                mr={1}
                                                            />
                                                            {att.filename}
                                                        </Badge>
                                                    );
                                                })}
                                            </HStack>
                                        )}

                                    {blocks.map((block, blockIndex) => {
                                        if (block.type === "activity-trace") {
                                            return (
                                                <ActivityTraceBlock
                                                    key={`trace-${messageIndex}-${blockIndex}`}
                                                    traceBlocks={block.traceBlocks}
                                                    currentActivity={block.currentActivity}
                                                    messageIndex={messageIndex}
                                                    message={message}
                                                    getThinkingBlockState={getThinkingBlockState}
                                                    toggleThinkingVisibility={toggleThinkingVisibility}
                                                    expandedToolBlocks={expandedToolBlocks}
                                                    toggleToolExpanded={toggleToolExpanded}
                                                />
                                            );
                                        }

                                        if (!block.content) return null;

                                        return (
                                            <Box
                                                fontSize="sm"
                                                key={`text-${messageIndex}-${blockIndex}`}
                                                width="100%"
                                            >
                                                <MarkdownRenderer
                                                    citations={allCitations}
                                                    citationRemap={remap}
                                                >
                                                    {block.content}
                                                </MarkdownRenderer>
                                            </Box>
                                        );
                                    })}

                                    {message.role === "assistant" &&
                                        message.context && (
                                            <CitationList
                                                citations={allCitations}
                                                citedOriginals={footerOriginals}
                                                colorMode={colorMode}
                                                inline
                                            />
                                        )}

                                    {message.role === "assistant" &&
                                        message.artifacts &&
                                        message.artifacts.length > 0 && (
                                            <VStack
                                                align="start"
                                                gap={1}
                                                mt={1}
                                                width="100%"
                                            >
                                                {message.artifacts.map(
                                                    (artifact, idx) => (
                                                        <ArtifactCard
                                                            key={`artifact-${messageIndex}-${idx}`}
                                                            artifact={artifact}
                                                        />
                                                    ),
                                                )}
                                            </VStack>
                                        )}
                                </VStack>
                            )}
                        </Box>
                    </Flex>
                );
            })}
            <div ref={messagesEndRef} />
        </VStack>
    );
};

export default DashboardMessageList;

import React from "react";
import {
    Box,
    Flex,
    VStack,
    HStack,
    Text,
    Input,
    IconButton,
    Button,
    Checkbox,
    Collapsible,
    Spinner,
} from "@chakra-ui/react";
import {
    AddIcon,
    DeleteIcon,
    ChevronDownIcon,
    ChevronUpIcon,
} from "../common/icons";

const DashboardTodoPanel = ({
    todos = [],
    visibleTodos = [],
    newTodo = "",
    setNewTodo,
    showAllTodos = false,
    setShowAllTodos,
    isCollapsed = true,
    toggleCollapsed,
    isLoading = false,
    isSaving = false,
    addTodo,
    toggleTodo,
    deleteTodo,
    handleTodoKeyDown,
}) => {
    const completedCount = todos.filter((todo) => todo.completed).length;
    const activeCount = Math.max(todos.length - completedCount, 0);

    return (
        <Box w="100%" maxW="760px" px={1} py={1}>
            <VStack align="stretch" gap={2}>
                <HStack justify="space-between" align="center">
                    <Button
                        onClick={toggleCollapsed}
                        variant='plain'
                        color="overlay0"
                        fontWeight="medium"
                        fontSize="sm"
                        textDecoration="none"
                        _hover={{ color: "textPrimary", textDecoration: "none" }}>Todo list
                                            {
                            isCollapsed ? (
                                <ChevronDownIcon />
                            ) : (
                                <ChevronUpIcon />
                            )
                        }</Button>
                    <Text fontSize="xs" color="overlay0">
                        {activeCount} active
                    </Text>
                </HStack>

                <Collapsible.Root open={!isCollapsed}>
                    <Collapsible.Content>
                        <VStack align="stretch" gap={2} pt={1}>
                            <Flex align="center" justify="space-between">
                                <Text fontSize="xs" color="overlay0">
                                    Optional workspace tasks
                                </Text>
                                <Button
                                    size="xs"
                                    variant='plain'
                                    onClick={() =>
                                        setShowAllTodos?.((prev) => !prev)
                                    }
                                    color="overlay0"
                                    _hover={{
                                        color: "textPrimary",
                                        textDecoration: "none",
                                    }}
                                >
                                    {showAllTodos ? "Show active" : "Show all"}
                                </Button>
                            </Flex>

                            <HStack gap={1}>
                                <Input
                                    value={newTodo}
                                    onChange={(e) => setNewTodo?.(e.target.value)}
                                    onKeyDown={handleTodoKeyDown}
                                    placeholder="Add a task..."
                                    size="sm"
                                    variant="flushed"
                                    disabled={isSaving}
                                />
                                <IconButton
                                    onClick={addTodo}
                                    size="xs"
                                    aria-label="Add todo"
                                    variant="ghost"
                                    disabled={isSaving}>{isSaving ? (
                                        <Spinner size="xs" />
                                    ) : (
                                        <AddIcon />
                                    )}</IconButton>
                            </HStack>

                            <VStack
                                align="stretch"
                                gap={1}
                                maxH="180px"
                                overflowY="auto"
                                pt={0.5}
                            >
                                {isLoading ? (
                                    <Flex align="center" justify="center" py={3}>
                                        <Spinner size="sm" />
                                    </Flex>
                                ) : visibleTodos.length > 0 ? (
                                    visibleTodos.map((todo) => (
                                        <HStack
                                            key={todo.id}
                                            align="center"
                                            justify="space-between"
                                            py={1}
                                        >
                                            <Checkbox.Root
                                                onCheckedChange={() =>
                                                    toggleTodo?.(todo.id)
                                                }
                                                size="sm"
                                                disabled={isSaving}
                                                checked={todo.completed}
                                            ><Checkbox.HiddenInput /><Checkbox.Control><Checkbox.Indicator /></Checkbox.Control><Checkbox.Label>
                                                <Text
                                                    fontSize="sm"
                                                    as={
                                                        todo.completed
                                                            ? "s"
                                                            : "span"
                                                    }
                                                    color={
                                                        todo.completed
                                                            ? "overlay0"
                                                            : "textTertiary"
                                                    }
                                                >
                                                    {todo.task}
                                                </Text>
                                            </Checkbox.Label></Checkbox.Root>

                                            <IconButton
                                                onClick={() =>
                                                    deleteTodo?.(todo.id)
                                                }
                                                size="xs"
                                                variant="ghost"
                                                aria-label="Delete todo"
                                                disabled={isSaving}
                                                color="overlay0"
                                                _hover={{
                                                    color: "dangerButton",
                                                    bg: "transparent",
                                                }}><DeleteIcon /></IconButton>
                                        </HStack>
                                    ))
                                ) : (
                                    <Text fontSize="sm" color="overlay0" px={1}>
                                        No tasks yet.
                                    </Text>
                                )}
                            </VStack>

                            {completedCount > 0 && (
                                <Text fontSize="xs" color="overlay0" pt={1}>
                                    {completedCount} completed
                                </Text>
                            )}
                        </VStack>
                    </Collapsible.Content>
                </Collapsible.Root>
            </VStack>
        </Box>
    );
};

export default DashboardTodoPanel;

