    Portal,
} from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import { FaUserPlus, FaSearch, FaArrowLeft } from "react-icons/fa";
import { DEFAULT_TOAST_CONFIG } from "../../utils/constants";
import { CandidateRow, PathHalf } from "../patient/NewNoteStartCard";
import UrSearchField from "../patient/UrSearchField";
import DemographicsForm from "../patient/DemographicsForm";

const btnSx = {
    fontFamily: '"Space Grotesk", sans-serif',
    fontWeight: "600",
};

const NewNoteModal = ({
    isOpen,
    onClose,
    _patient,
    setPatient,
    createNewPatient,
    findPatients,
    loadSelectedPatient,
    selectedDate,
    onComplete,
}) => {

    const [view, setView] = useState("choose");
    const [query, setQuery] = useState("");
    const [results, setResults] = useState([]);
    const [isSearchLoading, setIsSearchLoading] = useState(false);
    const [confirmingId, setConfirmingId] = useState(null);
    const [draftPatient, setDraftPatient] = useState({});

    const handleFind = (e) => {
        if (e && e.preventDefault) e.preventDefault();
        const q = (query || "").trim();
        if (!q) {
            toaster.create({
                title: "Enter a UR number or name",
                description:
                    "Type a UR number or patient name, then click search.",
                type: "warning",
                ...DEFAULT_TOAST_CONFIG,
            });
            return;
        }
        setIsSearchLoading(true);
        findPatients(q)
            .then((list) => {
                if (list && list.length > 0) {
                    setResults(list);
                    setView("results");
                } else {
                    toaster.create({
                        title: "No patient found",
                        description: `No patient matches "${q}". Fill in their details to create a new record.`,
                        type: "info",
                        ...DEFAULT_TOAST_CONFIG,
                    });
                }
            })
            .catch(() => {
                toaster.create({
                    title: "Search failed",
                    description: "Couldn't search patients. Please try again.",
                    type: "error",
                    duration: 3000,
                });
            })
            .finally(() => setIsSearchLoading(false));
    };

    const handleConfirm = (candidate) => {
        setConfirmingId(candidate.ur_number || candidate.id);
        loadSelectedPatient(candidate, selectedDate)
            .then(() => onComplete({ cameFromSearch: true }))
            .catch(() => {
                toaster.create({
                    title: "Couldn't load patient",
                    description: "Please try again.",
                    type: "error",
                    duration: 3000,
                });
            })
            .finally(() => setConfirmingId(null));
    };

    const handleNewPatient = () => {
        setDraftPatient({});
        setView("new-patient");
    };

    const commitNewPatient = (updated) => {
        createNewPatient()
            .then((base) => {
                setPatient({ ...base, ...updated, isNewEncounter: true });
                onComplete({ cameFromSearch: false });
            })
            .catch(() => {
                toaster.create({
                    title: "Couldn't start new patient",
                    description: "Please try again.",
                    type: "error",
                    duration: 3000,
                });
            });
    };

    const subtitle =
        view === "search"
            ? "Enter a UR number or name to find an existing patient."
            : view === "results"
              ? "Confirm the patient to start a new visit."
              : view === "new-patient"
                ? "Enter the patient's details to create a new record."
                : "Find an existing patient to start a new visit, or create a new patient record.";

    return (
        <Dialog.Root
            open={isOpen}
            size="lg"
            onOpenChange={(e) => {
                if (!e.open) {
                    onClose();
                }
            }}
        >
            <Portal>
                <Dialog.Backdrop />
                <Dialog.Positioner>
                    <Dialog.Content className="modal-style">
                        <Dialog.Header>
                            <Heading
                                as="h3"
                                size="xl"
                                color="textPrimary"
                                css={{
                                    fontFamily: '"Space Grotesk", sans-serif',
                                }}
                            >
                                New encounter
                            </Heading>
                        </Dialog.Header>
                        <Dialog.CloseTrigger />
                        <Dialog.Body
                            maxH="70vh"
                            overflowY="auto"
                            className="custom-scrollbar"
                        >
                            <Text
                                fontSize="sm"
                                color="textSecondary"
                                mb={4}
                                lineHeight={1.5}
                            >
                                {subtitle}
                            </Text>

                            <Box key={view}>
                                {view === "choose" ? (
                                    <Flex gap={3} mb={2}>
                                        <PathHalf
                                            icon={FaUserPlus}
                                            title="New patient"
                                            subtitle="Create a new record"
                                            accent="primaryButton"
                                            tileBg="tile"
                                            onClick={handleNewPatient}
                                        />
                                        <PathHalf
                                            icon={FaSearch}
                                            title="Search"
                                            subtitle="Existing patient"
                                            accent="secondaryButton"
                                            tileBg="tile"
                                            onClick={() => setView("search")}
                                        />
                                    </Flex>
                                ) : view === "search" ? (
                                    <Box>
                                        <Flex alignItems="center" asChild>
                                            <form onSubmit={handleFind}>
                                                <UrSearchField
                                                    value={query}
                                                    onChange={(e) =>
                                                        setQuery(e.target.value)
                                                    }
                                                    onSearch={handleFind}
                                                    isLoading={isSearchLoading}
                                                    autoFocus
                                                    placeholder="UR number or name"
                                                />
                                            </form>
                                        </Flex>
                                        <Button
                                            type="button"
                                            variant="outline"
                                            size="md"
                                            mt={3}
                                            borderRadius="2xl"
                                            className="switch-mode"
                                            css={btnSx}
                                            onClick={() => setView("choose")}
                                        >
                                            <FaArrowLeft />
                                            Back
                                        </Button>
                                    </Box>
                                ) : view === "results" ? (
                                    <Box>
                                        <VStack gap={3} align="stretch">
                                            {results.map((cand) => (
                                                <CandidateRow
                                                    key={
                                                        cand.ur_number ||
                                                        cand.id
                                                    }
                                                    candidate={cand}
                                                    onConfirm={handleConfirm}
                                                    confirming={
                                                        confirmingId ===
                                                        (cand.ur_number ||
                                                            cand.id)
                                                    }
                                                    disabled={
                                                        confirmingId !== null
                                                    }
                                                />
                                            ))}
                                        </VStack>
                                        <Button
                                            type="button"
                                            variant="outline"
                                            size="md"
                                            mt={3}
                                            borderRadius="2xl"
                                            className="switch-mode"
                                            css={btnSx}
                                            onClick={() => setView("search")}
                                        >
                                            <FaArrowLeft />
                                            Back
                                        </Button>
                                    </Box>
                                ) : (
                                    <DemographicsForm
                                        key={draftPatient?.id || "empty"}
                                        patient={draftPatient}
                                        setPatient={setDraftPatient}
                                        onSaved={commitNewPatient}
                                        onCancel={() => setView("choose")}
                                        cancelLabel="Back"
                                        cancelIcon={<FaArrowLeft />}
                                    />
                                )}
                            </Box>
                        </Dialog.Body>
                    </Dialog.Content>
                </Dialog.Positioner>
            </Portal>
        </Dialog.Root>
    );
};

export default NewNoteModal;

import { Button, HStack, Heading, Text, Dialog, Portal } from "@chakra-ui/react";

const formatDate = (iso) => {
    if (!iso) return "";
    const d = new Date(iso);
    return Number.isNaN(d.getTime()) ? iso : d.toLocaleDateString();
};

const ScribeConsentModal = ({
    isOpen,
    onClose,
    onConsent,
    onDecline,
    hasDeclined = false,
    declinedDate = null,
    patientName = "",
}) => {
    const name = patientName || "This patient";
    return (
        <Dialog.Root
            open={isOpen}
            size='md'
            closeOnInteractOutside={false}
            onOpenChange={e => {
                if (!e.open) {
                    onClose();
                }
            }}
        >
            <Portal>

                <Dialog.Backdrop />
                <Dialog.Positioner>
                    <Dialog.Content className="modal-style">
                        <Dialog.Header>
                            <Heading as="h2" size="md" fontFamily="heading">
                                {hasDeclined
                                    ? "Previously declined"
                                    : "Ambient scribe consent"}
                            </Heading>
                        </Dialog.Header>
                        <Dialog.CloseTrigger />
                        <Dialog.Body>
                            {hasDeclined ? (
                                <Text>
                                    {name} previously declined consent for ambient
                                    scribing
                                    {declinedDate
                                        ? ` on ${formatDate(declinedDate)}`
                                        : ""}
                                    . Would you like to re-request consent before
                                    recording?
                                </Text>
                            ) : (
                                <Text>
                                    {name} hasn&apos;t yet consented to ambient
                                    scribing. Ambient mode records the consultation
                                    &mdash; please confirm the patient has consented
                                    before recording.
                                </Text>
                            )}
                        </Dialog.Body>
                        <Dialog.Footer>
                            <HStack justify="flex-end" width="100%">
                                {hasDeclined ? (
                                    <Button
                                        className="red-button"
                                        mr={3}
                                        onClick={onClose}
