                                                >
                                                    <Checkbox.HiddenInput />
                                                    <Checkbox.Control>
                                                        <Checkbox.Indicator />
                                                    </Checkbox.Control>
                                                </Checkbox.Root>
                                                <Input
                                                    value={item.text}
                                                    onChange={(e) =>
                                                        editItemText(
                                                            idx,
                                                            e.target.value,
