                                                    }
                                                    variant="unstyled"
                                                    size="sm"
                                                    flex="1"
                                                    color={
                                                        "textPrimary"
                                                    }
                                                    css={{
                                                        padding: 0,
                                                        height: "auto",
                                                        lineHeight: "1.4",
                                                    }}
                                                />
                                                <IconButton
                                                    aria-label="Remove task"
                                                    size="xs"
                                                    variant="ghost"
                                                    onClick={() =>
