                                            className="input-style"
                                        />
                                        <IconButton
                                            aria-label="Add task"
                                            size="sm"
                                            onClick={addTask}
                                        >
                                            <FaPlus />
                                        </IconButton>
                                    </HStack>
                                </Section>

                                {excluded.length > 0 && (
                                    <Box>
                                        <Text
                                            fontSize="sm"
                                            fontWeight="600"
                                            color={"textPrimary"}
                                            cursor="pointer"
                                            userSelect="none"
                                            onClick={() =>
                                                setShowExcluded((s) => !s)
                                            }
                                        >
                                            {showExcluded ? "▾" : "▸"} Not tasks
                                            (review/follow-up) —{" "}
                                            {excluded.length}
                                        </Text>
                                        <Collapsible.Root open={showExcluded}>
                                            <Collapsible.Content>
                                                <VStack
                                                    align="stretch"
                                                    gap={1}
                                                    mt={2}
                                                    pl={2}
                                                >
                                                    {excluded.map(
                                                        (item, idx) => (
                                                            <HStack
                                                                key={idx}
                                                                justify="space-between"
                                                            >
                                                                <Text
                                                                    fontSize="sm"
                                                                    color={
                                                                        "textSecondary"
                                                                    }
                                                                >
                                                                    {item.text}
                                                                </Text>
                                                                <IconButton
                                                                    aria-label="Promote to task"
                                                                    size="xs"
                                                                    variant="ghost"
                                                                    onClick={() =>
                                                                        promoteExcluded(
                                                                            idx,
                                                                        )
                                                                    }
                                                                >
                                                                    <FaPlus />
                                                                </IconButton>
                                                            </HStack>
                                                        ),
                                                    )}
                                                </VStack>
                                            </Collapsible.Content>
                                        </Collapsible.Root>
                                    </Box>
                                )}

                                {fallback === "empty" && (
                                    <Alert.Root status="info" borderRadius="md">
                                        <Alert.Indicator />
                                        No plan text to extract tasks from. Add
                                        any tasks above.
                                    </Alert.Root>
                                )}
                                {fallback === "heuristic" && (
                                    <Alert.Root
                                        status="warning"
                                        borderRadius="md"
                                    >
                                        <Alert.Indicator />
                                        Smart extraction unavailable — showing
                                        basic tasks. Edit freely.
                                    </Alert.Root>
                                )}

                                {/* TODO: billing suggestions section */}
                            </VStack>
                        </Dialog.Body>
                        <Dialog.Footer>
                            <HStack justify="flex-end" width="100%">
                                <Button
                                    onClick={onClose}
                                    size="md"
                                    borderRadius="2xl"
                                    className="switch-mode"
                                    css={{
                                        fontFamily:
                                            '"Space Grotesk", sans-serif',
                                        fontWeight: "600",
                                    }}
                                    mr={3}
                                    disabled={submitting}
                                >
                                    Cancel
                                </Button>
                                <GreenButton
                                    onClick={handleConfirm}
                                    loading={submitting}
                                    loadingText="Saving"
                                    disabled={!canConfirm}
                                >
                                    Confirm &amp; Finish
                                </GreenButton>
                            </HStack>
                        </Dialog.Footer>
                    </Dialog.Content>
                </Dialog.Positioner>
            </Portal>
        </Dialog.Root>
    );
};

