import React, { useMemo, useState } from "react";
import { useColorMode } from "../../ui/color-mode";
import { Flex, Box, Text, HStack, VStack, Spinner, Image } from "@chakra-ui/react";
import {
    parseMessageContent,
    buildCitationRemap,
} from "../../../utils/chat/messageParser";
import { groupActivityTrace } from "../../../utils/chat/activityTrace";
import ActivityTraceBlock from "../../common/ActivityTraceBlock";
import MarkdownRenderer from "../../common/MarkdownRenderer";
import ArtifactCard from "../../common/ArtifactCard";
import FormFillArtifact from "../../pdf-forms/FormFillArtifact";
import { CitationList } from "../reasoning/components/CitationList";

const ChatMessages = ({
    messages,
    toggleThinkingVisibility,
    getThinkingBlockState,
}) => {
    const [expandedToolBlocks, setExpandedToolBlocks] = useState({});
    const { colorMode } = useColorMode();

    const filteredMessages = useMemo(
        () =>
            messages
                .map((message, messageIndex) => ({ message, messageIndex }))
                .filter(({ message }) => message.role !== "system"),
        [messages],
    );

    const toggleToolExpanded = (messageIndex, blockIndex) => {
        const key = `${messageIndex}:${blockIndex}`;
        setExpandedToolBlocks((prev) => ({
            ...prev,
            [key]: !prev[key],
        }));
    };

    if (filteredMessages.length === 0) {
        return null;
    }

    return (
        <>
            {filteredMessages.map(({ message, messageIndex }) => {
                if (message.role === "system") return null;

                const parsed = parseMessageContent(message.content || "");
                const rawBlocks =
                    parsed?.blocks && parsed.blocks.length > 0
                        ? parsed.blocks
                        : [{ type: "text", content: message.content || "" }];

                const blocks = groupActivityTrace(rawBlocks);

                const allCitations = Object.values(
                    message.context || {},
                ).filter(Boolean);
                const { remap, citedOriginals } = buildCitationRemap(
                    parsed?.visibleText || "",
                );
                const footerOriginals =
                    citedOriginals.length > 0 ? citedOriginals : null;

                return (
                    <Flex
                        key={messageIndex}
                        justify={
                            message.role === "assistant"
                                ? "flex-start"
                                : "flex-end"
                        }
                        mb="2"
                    >
                        <Box
                            className={`message-box ${message.role}`}
                            px={message.role === "assistant" ? "1" : "3"}
                            py={message.role === "assistant" ? "1" : "2"}
                            maxWidth={
                                message.role === "assistant" ? "92%" : "85%"
                            }
                            bg={
                                message.role === "assistant"
                                    ? "transparent"
                                    : undefined
                            }
                            borderWidth={
                                message.role === "assistant" ? "0" : undefined
                            }
                            boxShadow={
                                message.role === "assistant"
                                    ? "none"
                                    : undefined
                            }
                            fontSize="sm"
                            position="relative"
                        >
                            {message.loading ? (
                                <Spinner size="sm" mt="1" />
                            ) : (
                                <VStack
                                    align="start"
                                    gap={0.25}
                                    width="100%"
                                >
                                    {message.role === "assistant" && (
                                        <HStack gap={1.5} mb={0.5}>
                                            <Image
                                                src="/logo.webp"
                                                alt="Phlox Assistant"
                                                boxSize="14px"
                                                objectFit="contain"
                                            />
                                            <Text
                                                fontSize="xs"
                                                fontWeight="semibold"
                                                color="overlay0"
                                                lineHeight="1"
                                            >
                                                Phlox Assistant
                                            </Text>
                                        </HStack>
                                    )}

                                    {blocks.map((block, blockIndex) => {
                                        if (
                                            block.type === "activity-trace"
                                        ) {
                                            return (
                                                <ActivityTraceBlock
                                                    key={`trace-${messageIndex}-${blockIndex}`}
                                                    traceBlocks={
                                                        block.traceBlocks
                                                    }
                                                    currentActivity={
                                                        block.currentActivity
                                                    }
                                                    messageIndex={
                                                        messageIndex
                                                    }
                                                    message={message}
                                                    getThinkingBlockState={
                                                        getThinkingBlockState
                                                    }
                                                    toggleThinkingVisibility={
                                                        toggleThinkingVisibility
                                                    }
                                                    expandedToolBlocks={
                                                        expandedToolBlocks
                                                    }
                                                    toggleToolExpanded={
                                                        toggleToolExpanded
                                                    }
                                                />
                                            );
                                        }

                                        // text block
                                        if (!block.content) return null;
                                        return (
                                            <Box
                                                fontSize="sm"
                                                key={`text-${messageIndex}-${blockIndex}`}
                                                width="100%"
                                            >
                                                <MarkdownRenderer
                                                    citations={allCitations}
                                                    citationRemap={remap}
                                                >
                                                    {block.content}
                                                </MarkdownRenderer>
                                            </Box>
                                        );
                                    })}

                                    {message.role === "assistant" &&
                                        message.context && (
                                            <CitationList
                                                citations={allCitations}
                                                citedOriginals={footerOriginals}
                                                colorMode={colorMode}
                                                inline
                                            />
                                        )}

                                    {message.role === "assistant" &&
                                        message.artifacts &&
                                        message.artifacts.length > 0 && (
                                            <VStack
                                                align="start"
                                                gap={1}
                                                mt={1}
                                                width="100%"
                                            >
                                                {message.artifacts.map(
                                                    (artifact, idx) =>
                                                        artifact.type === "form_fill" ? (
                                                            <FormFillArtifact
                                                                key={`artifact-${messageIndex}-${idx}`}
                                                                artifact={artifact}
                                                            />
                                                        ) : (
                                                            <ArtifactCard
                                                                key={`artifact-${messageIndex}-${idx}`}
                                                                artifact={artifact}
                                                            />
                                                        ),
                                                )}
                                            </VStack>
                                        )}
                                </VStack>
                            )}
                        </Box>
                    </Flex>
                );
            })}
        </>
    );
};

export default ChatMessages;

import React, { useEffect, useRef, useState } from "react";
import { Box, Text } from "@chakra-ui/react";
import ChatHeader from "./ChatHeader";
import ChatMessages from "./ChatMessages";
import ChatInput from "./ChatInput";
import ChatSuggestions from "./ChatSuggestions";
import QuickChatButtons from "./QuickChatButtons";
import { settingsApi } from "../../../utils/api/settingsApi";

const ChatPanel = ({
    dimensions,
    resizerRef,
    handleMouseDown,
    onClose,
    chatLoading,
    messages,
    setMessages,
    userInput,
    setUserInput,
    handleChat,
    showSuggestions,
    setShowSuggestions,
    rawTranscription,
    currentTemplate,
    patientData,
}) => {
    const [userSettings, setUserSettings] = useState(null);
    const messagesEndRef = useRef(null);
    const scrollContainerRef = useRef(null);
    const userIsNearBottomRef = useRef(true);
    const filteredMessages = messages.filter((m) => m.role !== "system");

    const getThinkingBlockState = (message, blockIndex = 0) => {
        if (!message) return false;
        const expandedMap = message.thinkingExpandedBlocks || {};
        return Boolean(expandedMap[blockIndex]);
    };

    const toggleThinkingVisibility = (messageIndex, blockIndex = 0) => {
        setMessages((prev) =>
            prev.map((msg, i) => {
                if (i !== messageIndex) return msg;

                const currentMap = msg.thinkingExpandedBlocks || {};
                const nextExpanded = !currentMap[blockIndex];

                return {
                    ...msg,
                    thinkingExpandedBlocks: {
                        ...currentMap,
                        [blockIndex]: nextExpanded,
                    },
                    // Keep legacy field in sync for first thinking block compatibility
                    isThinkingExpanded:
                        blockIndex === 0
                            ? nextExpanded
                            : msg.isThinkingExpanded,
                };
            }),
        );
    };

    useEffect(() => {
        const fetchUserSettings = async () => {
            try {
                const data = await settingsApi.fetchUserSettings();
                setUserSettings(data);
            } catch (error) {
                console.error(error);
            }
        };
        fetchUserSettings();
    }, []);

    useEffect(() => {
        if (messagesEndRef.current && userIsNearBottomRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: "smooth" });
        }
    }, [messages]);

    const handleSendMessage = (text) => {
        if (!text.trim()) return;
        handleChat(
            text,
            messages,
            patientData,
            currentTemplate,
            rawTranscription,
        );
        setUserInput("");
        setShowSuggestions(false);
    };

    const shouldShowQuickChatButtons =
        filteredMessages.length > 0 && userSettings;

    return (
        <Box
            width={`${dimensions.width}px`}
            height={`${dimensions.height - 24}px`}
            overflow="hidden"
            display="flex"
            flexDirection="column"
        >
            <ChatHeader onClose={onClose} />

            <Box
                ref={scrollContainerRef}
                flex="1"
                overflowY="auto"
                p="4"
                className="floating-main sidebar-scroll-overlay"
                onScroll={() => {
                    const el = scrollContainerRef.current;
                    if (el) {
                        userIsNearBottomRef.current =
                            el.scrollHeight - el.scrollTop - el.clientHeight < 60;
                    }
                }}
            >
                <ChatMessages
                    messages={messages}
                    toggleThinkingVisibility={toggleThinkingVisibility}
                    getThinkingBlockState={getThinkingBlockState}
                />

                {showSuggestions &&
                    filteredMessages.length === 0 &&
                    userSettings && (
                        <ChatSuggestions
                            handleSendMessage={handleSendMessage}
                            userSettings={userSettings}
                        />
                    )}

                <div ref={messagesEndRef} />
            </Box>

            <Box p="3" className="floating-main">
                {shouldShowQuickChatButtons && (
                    <QuickChatButtons
                        userSettings={userSettings}
                        handleSendMessage={handleSendMessage}
                    />
                )}

                <ChatInput
                    userInput={userInput}
                    setUserInput={setUserInput}
                    handleSendMessage={handleSendMessage}
                    chatLoading={chatLoading}
                />

                <Text textAlign="center" fontSize="xs" color="overlay0">
                    Phlox may make mistakes. Always verify critical information.
                </Text>
            </Box>

            <Box
                ref={resizerRef}
                position="absolute"
                top="0"
                left="0"
                width="15px"
                height="15px"
                cursor="nwse-resize"
                onMouseDown={handleMouseDown}
                zIndex={1}
            />
        </Box>
    );
};

