      setProcessingError(null);
    }
  };

  const handleUpload = async () => {
    if (!file) {
      toaster.create({
        title: "No file selected",
        description: "Please select a file to upload",
        type: "error",
        duration: 3000,
      });
      return;
    }

    setIsProcessing(true);
    setProcessingError(null);

    try {
      const result = await processDocument(
        file,
        { name, dob, gender, templateKey: template?.template_key },
        {
          handleComplete: (data) => {
            handleDocumentComplete(data);
            setIsProcessing(false);
          },
          handleError: (error) => {
            setProcessingError({
              message: error.message || "Failed to process document",
            });
            setIsProcessing(false);
          },
        },
      );
      return result;
    } catch (error) {
      console.error("Error processing document:", error);
      setProcessingError({
        message:
          error.message ||
          "An unexpected error occurred while processing the document",
      });
      setIsProcessing(false);
    }
  };

  const retryProcessing = async () => {
    if (!file) {
      setProcessingError({
        message: "No document available to retry. Please upload a file again.",
      });
      return;
    }

    setIsProcessing(true);
    setProcessingError(null);
    resetDocumentState();

    try {
      await handleUpload();
    } catch (error) {
      console.error("Error retrying document processing:", error);
      setProcessingError({
        message:
          "Processing retry failed. The server might be experiencing issues.",
      });
      setIsProcessing(false);
    }
  };

  const startNewUpload = () => {
    setFile(null);
    setDocFileName("");
    setProcessingError(null);
    resetDocumentState();
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragOver(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setIsDragOver(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragOver(false);

    const files = e.dataTransfer?.files;
    if (!files || files.length === 0) return;

    const droppedFile = files[0];
    const validTypes = [
      "application/pdf",
      "application/msword",
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      "text/plain",
    ];

    if (
      !validTypes.includes(droppedFile.type) &&
      !droppedFile.name.match(/\.(pdf|doc|docx|txt)$/i)
    ) {
      toaster.create({
        title: "Invalid file type",
        description: "Please upload a PDF, Word document, or text file.",
        type: "error",
        duration: 3000,
      });
      return;
    }

    setFile(droppedFile);
    setDocFileName(droppedFile.name);
    setProcessingError(null);
  };

  return (
    <FloatingPanel
      isOpen={isOpen}
      className="floating-panel"
      position="left-of-fab"
      showArrow={true}
      triggerId="fab-document"
      width="90%"
      maxWidth="600px"
    >
      {/* Drag overlay */}
      {isDragOver && (
        <Flex
          position="absolute"
          top={0}
          left={0}
          right={0}
          bottom={0}
          align="center"
          justify="center"
          bg="rgba(255,107,53,0.1)"
          zIndex={10}
          borderRadius="lg"
          pointerEvents="none"
        >
          <Text fontWeight="bold" color="primaryButton">
            Drop document here
          </Text>
        </Flex>
      )}
      {/* Header */}
      <Flex
        align="center"
        justify="space-between"
        p="3"
        className="panel-header"
        flexShrink={0}
      >
        <Flex align="center">
          <FaFileUpload size="1em" style={{ marginRight: "8px" }} />
          <Text fontWeight="bold">Document Upload</Text>
        </Flex>
      </Flex>
      {/* Content */}
      <Box
        p={4}
        maxH="400px"
        overflowY="auto"
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        {/* Processing error state */}
        {processingError ? (
          <Alert.Root
            status="error"
            variant="subtle"
            flexDirection="column"
            alignItems="center"
            justifyContent="center"
            textAlign="center"
            borderRadius="sm"
          >
            <Flex mb={2}>
              <Alert.Indicator mr={2} asChild><FaExclamationTriangle /></Alert.Indicator>
              <Alert.Title>Processing Error</Alert.Title>
            </Flex>
            <Alert.Description maxWidth="lg">
              {processingError.message}
            </Alert.Description>
            <ButtonGroup mt={4} gap={3}>
              <Button
                onClick={retryProcessing}
                className="green-button"
                disabled={isProcessing}
                size="sm"><FaRedoAlt />{isProcessing ? <Spinner size="sm" mr={2} /> : null}
                Resend
              </Button>
              <Button onClick={startNewUpload} className="orange-button" size="sm"><FaRedo />New Document
                              </Button>
            </ButtonGroup>
          </Alert.Root>
        ) : isProcessing || isTranscribing ? (
          <Flex justify="center" align="center" py={8} direction="column">
            <Spinner size="xl" mb={4} />
            <Text>Processing document...</Text>
          </Flex>
        ) : !extractedDocData ? (
          // Upload UI
          (<VStack gap={4} width="full" align="stretch">
            <Text textAlign="center" fontSize="sm">
              Upload a referral letter or other document to extract information.
            </Text>
            <VStack width="full" align="center">
              <Input
                type="file"
                onChange={handleFileChange}
                display="none"
                id="doc-file-upload"
                accept=".pdf,.doc,.docx,.txt"
              />
              <GreyButton
                px="6"
                leftIcon={<FaFileUpload />}
                onClick={() =>
                  document.getElementById("doc-file-upload").click()
                }
                size="sm"
              >
                Choose Document
              </GreyButton>
              {docFileName && <Text fontSize="sm">{docFileName}</Text>}
            </VStack>
            {file && (
              <Flex justifyContent="center">
                <Button
                  onClick={handleUpload}
                  disabled={!file}
                  className="green-button"
                  size="sm"
                >
                  Process Document
                </Button>
              </Flex>
            )}
          </VStack>)
        ) : (
          // Document processed UI with toggle buttons
          (<>
            <Flex justify="space-between" align="center" mb={3}>
              <Text fontWeight="bold" fontSize="sm">
                {docFileName}
              </Text>
              <Button onClick={startNewUpload} size="xs" className="orange-button"><FaFileUpload />New
                              </Button>
            </Flex>
            <Separator my={2} />
            <Text fontStyle="italic" fontSize="xs" mb={2}>
              Click buttons to toggle document content
            </Text>
            <SimpleGrid columns={[1, 2]} gap={2}>
              {template?.fields?.map((field) => {
                const fieldKey = field.field_key;
                const hasContent = Boolean(
                  extractedDocData?.fields[fieldKey]?.trim(),
                );
                const isReplaced = replacedFields[fieldKey];

                return (
                  <Box
                    key={fieldKey}
                    p={2}
                    borderWidth="1px"
                    borderRadius="sm"
                    borderColor="border"
                  >
                    <Flex justify="space-between" align="center">
                      <Text
                        fontWeight="medium"
                        fontSize="xs"
                        isTruncated
                        maxWidth="50%"
                        title={field.field_name}
                      >
                        {field.field_name}
                      </Text>
                      {!hasContent ? (
                        <Badge colorPalette="yellow" fontSize="xs">
                          Empty
                        </Badge>
                      ) : (
                        <Button
                          size="xs"
                          onClick={() => toggleDocumentField(fieldKey)}
                          disabled={!hasContent}
                          className={
                            isReplaced ? "green-button" : "grey-button"
                          }
                          variant={isReplaced ? "solid" : "outline"}
                          height="20px"
                          minWidth="70px"
                          fontSize="xs">{
                            isReplaced ? <CheckIcon boxSize="2" /> : null
                          }{isReplaced ? "Using" : "Use"}</Button>
                      )}
                    </Flex>
                  </Box>
                );
              })}
            </SimpleGrid>
          </>)
        )}
      </Box>
    </FloatingPanel>
  );
};

