const WaveformVisualizer = React.memo(({ isRecording, isPaused, timer }) => {
  const barCount = 8; // Smaller for widget

  const [bars] = useState(() =>
    [...Array(barCount)].map(() => ({
      frequency: 1 + Math.random(),
      delay: Math.random() * -2,
    })),
  );

  if (!isRecording && !isPaused) return null;

  // Format the timer
  const minutes = Math.floor(timer / 60);
  const seconds = String(timer % 60).padStart(2, "0");
  const formattedTime = `${minutes}:${seconds}`;

  return (
    <Flex
      h="40px"
      align="center"
      justify="center"
      position="absolute"
      top="50%"
      left="50%"
      transform="translate(-50%, -50%)"
      zIndex="2"
      bg="rgba(255, 255, 255, 0.9)"
      borderRadius="md"
      px={4}
      py={2}
      boxShadow="md"
    >
      {bars.map((bar, i) => (
        <Box
          key={i}
          zIndex="1"
          w="3px"
          mx="1.5px"
          borderRadius="full"
          bg={
            colors.light.primaryButton
          }
          opacity={isPaused ? "0.5" : "1"}
          animation={
            isRecording && !isPaused
              ? `barAnimation ${bar.frequency}s infinite ease-in-out`
              : "none"
          }
          css={{
            '& @keyframes barAnimation': {
              "0%, 100%": { height: "8px" },
              "50%": { height: "24px" },
            }
          }}
          style={{
            animationDelay: `${bar.delay}s`,
            height: isPaused ? "8px" : undefined,
            transition: "all 0.3s ease-out",
            animationPlayState: isPaused ? "paused" : "running",
          }}
        />
      ))}
      <Text
        ml={3}
        fontSize="md"
        fontWeight="bold"
        color={
          colors.light.primaryButton
        }
      >
        {formattedTime}
      </Text>
    </Flex>
  );
});

const DictationWidget = ({
  patient,
  setFinalCorrespondence,
  letterTemplates,
  _setIsRefining,
  setLoading,
  isDisabled,
}) => {
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [timer, setTimer] = useState(0);
  const audioRecorderRef = useRef(null);
  const timerIntervalRef = useRef(null);

  useEffect(() => {
    return () => {
      if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
      if (audioRecorderRef.current) {
        audioRecorderRef.current.stop().catch(() => {});
      }
    };
  }, []);

  const startRecording = async () => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      toaster.create({
        title: "Error",
        description: "Audio recording is not supported in this browser.",
        type: "error",
        duration: 3000,
      });
      return;
    }

    try {
      const recorder = new AudioRecorder();
      await recorder.start();
      audioRecorderRef.current = recorder;
      setIsRecording(true);
      setTimer(0);

      timerIntervalRef.current = setInterval(() => {
        setTimer((prev) => prev + 1);
      }, 1000);
    } catch (error) {
      console.error("Error starting recording:", error);
      toaster.create({
        title: "Error",
        description:
          "Failed to start recording. Please check microphone permissions.",
        type: "error",
        duration: 3000,
      });
    }
  };

  const stopRecording = async () => {
    if (audioRecorderRef.current && isRecording) {
      const recorder = audioRecorderRef.current;
      audioRecorderRef.current = null;
      setIsRecording(false);
      clearInterval(timerIntervalRef.current);
      const wavBlob = await recorder.stop();
      await processRecording(wavBlob);
    }
  };

  const processRecording = async (wavBlob) => {
    setIsProcessing(true);
    if (setLoading) setLoading(true);

    try {
      // 1. Transcribe
      const formData = new FormData();
      formData.append("file", wavBlob, "dictation.wav");

      const transcribeData =
          await transcriptionApi.transcribeDictation(formData);
      const transcription = transcribeData.transcription;

      if (!transcription) {
        throw new Error("No transcription received");
      }

      // 2. Find Dictation Template
      const dictationTemplate = letterTemplates?.find(
        (t) => t.name === "Dictation",
      );
      const instructions =
        dictationTemplate?.instructions ||
        "I'm going to dictate the rough outline of a letter to you. I would like you to keep the essence of the structure of the dictated letter, but adjust the punctuation and wording where required to make it a polished letter.";

      // 3. Generate Letter
      // We pass the transcription as part of template_data so it appears in the clinic note
      const templateData = {
        ...(patient?.template_data || {}), // Include existing data
        Dictation: transcription,
      };

      const letterResponse = await letterApi.generateLetter({
        patientName: patient?.name || "Unknown",
        gender: patient?.gender || "Unknown",
        dob: patient?.dob || "Unknown",
        template_data: templateData,
        additional_instruction: instructions,
        context: [], // Add any other context if needed
      });

      if (letterResponse && letterResponse.letter) {
        setFinalCorrespondence(letterResponse.letter);
        toaster.create({
          title: "Success",
          description: "Letter generated from dictation",
          type: "success",
          duration: 3000,
        });
      } else {
        throw new Error("Failed to generate letter content");
      }
    } catch (error) {
      console.error("Error processing dictation:", error);
      toaster.create({
        title: "Error",
        description: "Failed to process dictation",
        type: "error",
        duration: 3000,
      });
    } finally {
      setIsProcessing(false);
      if (setLoading) setLoading(false);
    }
  };

  return (
    <>
      <WaveformVisualizer
        isRecording={isRecording}
        isPaused={false}
        timer={timer}
      />
      <Tooltip
        content={isRecording ? "Stop Dictation" : "Start Dictation"}
        disabled={isDisabled || isProcessing}
        positioning={{
          placement: "left"
        }}
      >
        <IconButton
          onClick={isRecording ? stopRecording : startRecording}
          disabled={isDisabled || isProcessing}
          colorPalette={isRecording ? "red" : "gray"}
          aria-label="Dictate"
          position="absolute"
          bottom={4}
          // Positioned to the left of the refinement button (which is at right: 4 = 16px)
          right="60px"
          width="40px"
          height="40px"
          borderRadius="full"
          zIndex={2}
          className="dictation-fab"
          css={{
            transition: "transform 0.2s",

            "&:hover": !isDisabled &&
              !isProcessing && {
                transform: "scale(1.1)",
              }
          }}>{isProcessing ? (
            <Spinner size="sm" />
          ) : isRecording ? (
            <FaStop />
          ) : (
            <FaMicrophone />
          )}</IconButton>
      </Tooltip>
    </>
  );
};

export default DictationWidget;

import { useRef, forwardRef, useImperativeHandle, useState, useEffect } from "react";
import { useClipboard } from "../../../utils/hooks/useClipboard";

import LetterPanel from "./LetterPanel";
import { useLetterTemplates } from "../../../utils/hooks/useLetterTemplates";
import FloatingPanel from "../../common/FloatingPanel";

const Letter = forwardRef(
  (
    {
      isOpen,
      onClose,
      finalCorrespondence,
      setFinalCorrespondence,
      handleSaveLetter,
      loading,
      handleGenerateLetterClick,
      handleRefineLetter,
      setIsModified,

      patient,
      setLoading: setGeneralLoading,
    },
    ref,
  ) => {
    // State
    const [isRefining, setIsRefining] = useState(false);
    const [refinementInput, setRefinementInput] = useState("");
    const [recentlyCopied, setRecentlyCopied] = useState(false);
    const [saveState, setSaveState] = useState("idle");
    const [dimensions, setDimensions] = useState({
      width: 650,
      height: 550,
    });

    // Refs
    const textareasRefs = useRef({});
    const saveTimerRef = useRef(null);
    const resizerRef = useRef(null);

    // Hooks
    const {
      letterTemplates,
      selectedTemplate,
      additionalInstructions,
      setAdditionalInstructions,
      selectTemplate,
      getInstructions,
    } = useLetterTemplates(patient?.id);

    // Clear the save timer on unmount
    useEffect(() => {
      return () => {
        if (saveTimerRef.current) {
          clearTimeout(saveTimerRef.current);
        }
      };
    }, []);

    // Functions
    const autoResizeTextarea = () => {
      const textarea = textareasRefs.current.letter;
      if (textarea) {
        textarea.style.height = "auto";
        textarea.style.height = textarea.scrollHeight + "px";
      }
    };

    // Auto-resize when letter opens or content changes
    useEffect(() => {
      if (isOpen) {
        setTimeout(() => {
          autoResizeTextarea();
        }, 100);
      }
    }, [isOpen, finalCorrespondence]);

    const textToCopy = finalCorrespondence || "No letter attached to encounter";
    const { onCopy } = useClipboard(textToCopy, { format: "text/plain" });

    const handleCopy = () => {
      onCopy();
      setRecentlyCopied(true);
      setTimeout(() => setRecentlyCopied(false), 2000);
    };

    const handleSave = async () => {
      setSaveState("saving");
      try {
        await handleSaveLetter();
        setSaveState("saved");
        saveTimerRef.current = setTimeout(() => setSaveState("idle"), 2000);
      } catch (error) {
        console.error("Error saving letter:", error);
        setSaveState("idle");
      }
    };

    const handleRefinement = async () => {
      if (!patient || !refinementInput.trim()) return;

      await handleRefineLetter({
        patient,
        additionalInstructions: getInstructions(),
        refinementInput,
        onSuccess: () => {
          setRefinementInput("");
          setIsRefining(false);
        },
      });
    };

    // Resize functionality
    const handleMouseDown = (e) => {
      e.preventDefault();
      window.addEventListener("mousemove", handleMouseMove);
      window.addEventListener("mouseup", handleMouseUp);
    };

    const handleMouseMove = (e) => {
      setDimensions((prev) => ({
        width: Math.max(
          400,
          prev.width -
            (e.clientX - resizerRef.current.getBoundingClientRect().left),
        ),
        height: Math.max(
          300,
          prev.height -
            (e.clientY - resizerRef.current.getBoundingClientRect().top),
        ),
      }));
    };

    const handleMouseUp = () => {
      window.removeEventListener("mousemove", handleMouseMove);
      window.removeEventListener("mouseup", handleMouseUp);
    };

    const handleClose = () => {
      if (onClose) {
        onClose();
      }
    };

    // Imperative handle for parent components to call methods
    useImperativeHandle(ref, () => ({
      autoResizeTextarea,
    }));

    return (
      <FloatingPanel
        isOpen={isOpen}
        position="left-of-fab"
        showArrow={true}
        triggerId="fab-letter"
        width={`${dimensions.width}px`}
        height={`${dimensions.height}px`}
        zIndex="1060"
      >
        <LetterPanel
          patient={patient}
          dimensions={dimensions}
          resizerRef={resizerRef}
          handleMouseDown={handleMouseDown}
          onClose={handleClose}
          finalCorrespondence={finalCorrespondence}
          setFinalCorrespondence={setFinalCorrespondence}
          letterLoading={loading}
          setLoading={setGeneralLoading}
          handleGenerateLetterClick={handleGenerateLetterClick}
          handleSaveLetter={handleSave}
          setIsModified={setIsModified}
          letterTemplates={letterTemplates}
          selectedTemplate={selectedTemplate}
          selectTemplate={selectTemplate}
          additionalInstructions={additionalInstructions}
          setAdditionalInstructions={setAdditionalInstructions}
          refinementInput={refinementInput}
          setRefinementInput={setRefinementInput}
          handleRefinement={handleRefinement}
          isRefining={isRefining}
          setIsRefining={setIsRefining}
          textareaRef={(el) => (textareasRefs.current.letter = el)}
          recentlyCopied={recentlyCopied}
          saveState={saveState}
          handleCopy={handleCopy}
        />
      </FloatingPanel>
    );
  },
);

export default Letter;

