const TranscriptionPanel = ({
  isOpen,
  _onClose,
  rawTranscription,
  transcriptionDuration,
  processDuration,
  isTranscribing: _parentIsTranscribing,
  onReprocess,
  isAmbient,
  name,
  gender,
  dob,
  templateKey,
  noteId,
}) => {
  const [showSuccess, setShowSuccess] = useState(false);
  const { reprocessTranscription, isTranscribing } = useTranscription(onReprocess, () => {});

  const handleReprocess = async () => {
    if (!rawTranscription) return;
    try {
      await reprocessTranscription(
        rawTranscription,
        { name, gender, dob, templateKey, noteId },
        transcriptionDuration,
        isAmbient,
      );
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 1500);
    } catch (error) {
      console.error("Failed to reprocess transcription:", error);
    }
  };

  return (
    <FloatingPanel
      isOpen={isOpen}
      position="bottom-center"
      showArrow={false}
      width="280px"
      maxHeight="280px"
    >
      <Box
        p={3}
        maxHeight="280px"
        backdropFilter="blur(12px)"
        borderRadius="xl"
        position="relative"
        css={{
          "&::-webkit-scrollbar": { width: "4px" },
          "&::-webkit-scrollbar-track": { background: "transparent" },
