        {/* Success overlay */}
        {showSuccess && (
          <Flex
            position="absolute"
            top={0}
            left={0}
            right={0}
            bottom={0}
            bg="rgba(72, 187, 120, 0.2)"
            borderRadius="xl"
            justify="center"
            align="center"
            zIndex={10}
            animation="fadeOut 1.5s ease-out forwards"
            css={{
              '& @keyframes fadeOut': {
                "0%": { opacity: 1 },
                "70%": { opacity: 1 },
                "100%": { opacity: 0 },
              }
            }}
          >
            <Box size="32px" color="#48BB78" opacity={0.8} asChild><FaCheck /></Box>
          </Flex>
        )}

        {rawTranscription ? (
          <>
            {/* Transcription text - scrollable */}
            <Box
              maxHeight="180px"
              overflowY="auto"
              mb={2}
              css={{
                "&::-webkit-scrollbar": { width: "4px" },
                "&::-webkit-scrollbar-track": { background: "transparent" },
                "&::-webkit-scrollbar-thumb": {
                  background: "var(--chakra-colors-scrollbar-thumb)",
                  borderRadius: "24px",
                },
              }}
            >
              <Text whiteSpace="pre-wrap" fontSize="xs" lineHeight="1.5">
                {rawTranscription}
              </Text>
            </Box>

            {/* Footer: Reprocess button and stats */}
            <Flex justify="space-between" align="center">
              {/* Stats */}
              {transcriptionDuration && (
                <HStack fontSize="10px" color="overlay0" gap={2}>
                  <Tooltip content="Transcription time" showArrow positioning={{
                    placement: "top"
                  }}>
                    <HStack gap={1}>
                      <Box size="8px" asChild><FaClock /></Box>
                      <Text>{transcriptionDuration}s</Text>
