const DemographicsForm = ({
    patient,
    setPatient,
    onSave,
    onSaved,
    onCancel,
    saveLabel = "Save",
    cancelLabel = "Cancel",
    cancelIcon = null,
}) => {
    const [form, setForm] = useState(() => patient
        ? {
            first_name: patient.first_name || "",
            last_name: patient.last_name || "",
            dob: patient.dob || "",
            gender: patient.gender || "",
            ur_number: patient.ur_number || "",
            address: patient.address || "",
            phone: patient.phone || "",
        }
        : {});
    const [isDragOver, setIsDragOver] = useState(false);
    const [isExtracting, setIsExtracting] = useState(false);
    const [extractError, setExtractError] = useState(null);
    const [isSaving, setIsSaving] = useState(false);
    const fileInputRef = useRef(null);

    const set = (key, value) => setForm((prev) => ({ ...prev, [key]: value }));

    const handleFile = async (file) => {
        if (!file) return;
        setIsExtracting(true);
        setExtractError(null);
        try {
            const data = await extractFromFile(
                file,
                {
                    fromText: transcriptionApi.extractDemographicsFromText,
                    visual: transcriptionApi.extractDemographicsVisual,
                    legacyFile: (formData) =>
                        transcriptionApi.extractDemographics(formData),
                },
                {},
            );
            // Merge only the fields the model returned (others left untouched).
            if (data && typeof data === "object") {
                setForm((prev) => ({ ...prev, ...data }));
            }
        } catch (error) {
            setExtractError(
                error?.message ||
                    "Couldn't read demographics from that document.",
            );
        } finally {
            setIsExtracting(false);
            if (fileInputRef.current) fileInputRef.current.value = "";
        }
    };

    const handleDragOver = (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.dataTransfer.types.includes("Files")) setIsDragOver(true);
    };
    const handleDragLeave = (e) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragOver(false);
    };
    const handleDrop = (e) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragOver(false);
        const file = e.dataTransfer.files?.[0];
        if (file) handleFile(file);
    };

    const requiredMet = areRequiredDemographicsMet(form);

    const handleSave = async () => {
        const first = (form.first_name || "").trim();
        const last = (form.last_name || "").trim();
        const name = last && first ? `${last}, ${first}` : last || first;
        const updated = {
            ...patient,
            first_name: first,
            last_name: last,
            name,
            dob: form.dob || "",
            gender: form.gender || "",
            ur_number: form.ur_number || "",
            address: form.address || "",
            phone: form.phone || "",
        };
        setPatient(updated);
        if (onSave) {
            setIsSaving(true);
            try {
                await onSave(updated);
            } catch {
                toaster.create({
                    title: "Couldn't save demographics",
                    description: "Please try again.",
                    type: "error",
                    duration: 3000,
                });
                setIsSaving(false);
                return;
            }
            setIsSaving(false);
        }
        if (onSaved) onSaved(updated);
    };

    const btnSx = {
        fontFamily: '"Space Grotesk", sans-serif',
        fontWeight: "600",
    };

    return (
        <VStack gap={4} align="stretch">
            {/* Document drop zone — auto-fills fields from a referral/ID/etc. */}
            <Box
                position="relative"
                borderRadius="md"
                border="2px dashed"
                borderColor={isDragOver ? "accent" : "surface"}
                bg={isDragOver ? "rgba(66, 153, 225, 0.15)" : "transparent"}
                p={3}
                textAlign="center"
                cursor="pointer"
                transition="all 0.15s"
                onClick={() => fileInputRef.current?.click()}
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
            >
                <Input
                    type="file"
                    ref={fileInputRef}
                    accept=".pdf,.txt,image/*"
                    onChange={(e) => handleFile(e.target.files?.[0])}
                    display="none"
                />
                <HStack
                    gap={2}
                    justify="center"
                    color={"textSecondary"}
                    fontSize="sm"
                >
                    <Icon asChild><FaFileUpload /></Icon>
                    <Text>
                        {isExtracting
                            ? "Reading document…"
                            : "Drop a document to auto-fill, or click to browse"}
                    </Text>
                    {isExtracting && <Spinner size="xs" />}
                </HStack>
                {extractError && (
                    <Text fontSize="xs" color="dangerButton" mt={1}>
                        {extractError}
                    </Text>
                )}
            </Box>
            <HStack gap={3} align="flex-start">
                <Field label="First name" required>
                    <Input
                        className="input-style"
                        size="sm"
                        placeholder="First name"
                        autoFocus
                        value={form.first_name || ""}
                        onChange={(e) => set("first_name", e.target.value)}
                    />
                </Field>
                <Field label="Last name" required>
                    <Input
                        className="input-style"
                        size="sm"
                        placeholder="Last name"
                        value={form.last_name || ""}
                        onChange={(e) => set("last_name", e.target.value)}
                    />
                </Field>
            </HStack>
            <HStack gap={3} align="flex-start">
                <Field label="Date of birth" required>
                    <Input
                        type="date"
                        className="input-style"
                        size="sm"
                        value={form.dob || ""}
                        onChange={(e) => set("dob", e.target.value)}
                    />
                </Field>
                <Field label="Gender">
                    <NativeSelect.Root>
                        <NativeSelect.Field
                            className="input-style"
                            size="sm"
                            value={form.gender || ""}
                            onChange={(e) => set("gender", e.target.value)}>
                            <option value="">M/F</option>
                            <option value="M">M</option>
                            <option value="F">F</option>
                        </NativeSelect.Field>
                        <NativeSelect.Indicator />
                    </NativeSelect.Root>
                </Field>
            </HStack>
            <HStack gap={3} align="flex-start">
                <Field label="UR number" required>
                    <Input
                        className="input-style"
                        size="sm"
                        placeholder="UR number"
                        value={form.ur_number || ""}
                        onChange={(e) => set("ur_number", e.target.value)}
                    />
                </Field>
                <Field label="Phone">
                    <Input
                        className="input-style"
                        size="sm"
                        placeholder="Phone"
                        value={form.phone || ""}
                        onChange={(e) => set("phone", e.target.value)}
                    />
                </Field>
            </HStack>
            <Field label="Address">
                <Input
                    className="input-style"
                    size="sm"
                    placeholder="Address"
                    value={form.address || ""}
                    onChange={(e) => set("address", e.target.value)}
                />
            </Field>
            <HStack justify="space-between" width="100%" mt={2}>
                {onCancel && (
                    <Button
                        onClick={onCancel}
                        size="md"
                        borderRadius="2xl"
                        className="switch-mode"
                        css={btnSx}>{cancelIcon || undefined}{cancelLabel}</Button>
                )}
                <Button
                    onClick={handleSave}
                    disabled={!requiredMet}
                    loading={isSaving}
                    size="md"
                    borderRadius="2xl"
                    className="green-button"
                    css={btnSx}
                >
                    {saveLabel}
                </Button>
            </HStack>
        </VStack>
    );
};

export default DemographicsForm;

