import {
    Box,
    Text,
    Table,
    HStack,
    Icon,
    Button,
    IconButton,
    Checkbox,
    VStack,
    Grid,
    Wrap,
    WrapItem,
} from "@chakra-ui/react";
import { Tooltip } from "@/components/ui/tooltip";
import { useRef, useEffect } from "react";
import { FaUser, FaCalendarAlt, FaIdBadge } from "react-icons/fa";
import {
    FaFileAlt,
    FaSitemap,
    FaVial,
    FaBrain,
    FaArrowRight,
} from "react-icons/fa";
import { RepeatIcon } from "../common/icons";
import { useColorMode } from "../ui/color-mode";
import { colors } from "../../theme/colors";
import {
    resetJobsItems,
    debouncedUpdateJobsList,
    flushPendingJobsUpdate,
} from "../../utils/patient/patientHandlers";

const PatientTable = ({
    patients,
    handleSelectPatient,
    setPatients,
    refreshSidebar,
    title,
    groupByDate = false,
    summaryOnly = false,
}) => {
    const pendingJobsUpdates = useRef(new Map());
    const { colorMode } = useColorMode();

    useEffect(() => {
        return () => {
            // eslint-disable-next-line react-hooks/exhaustive-deps -- unmount cleanup: must read ref at cleanup time to flush latest pending jobs
            pendingJobsUpdates.current.forEach((_, noteId) => {
                flushPendingJobsUpdate(noteId);
            });
        };
    }, []);

    const formatName = (name) => {
        const nameParts = name.split(", ");
        const firstNameInitial = nameParts[1] ? nameParts[1][0] : "";
        const lastName = nameParts[0];
        return `${firstNameInitial}. ${lastName}`;
    };

    const getRowBackgroundColor = (index) =>
        index % 2 === 0 ? "secondary" : "crust";

    const PatientDetails = ({ patient }) => (
        <Box>
            <HStack gap="2">
                <Icon asChild>
                    <FaUser />
                </Icon>
                <Text fontWeight="bold">{formatName(patient.name)}</Text>
            </HStack>
            <HStack gap="2">
                <Icon asChild>
                    <FaCalendarAlt />
                </Icon>
                <Text>{patient.dob}</Text>
            </HStack>
            <HStack gap="2">
                <Icon asChild>
                    <FaIdBadge />
                </Icon>
                <Text>{patient.ur_number}</Text>
            </HStack>
        </Box>
    );

    const getTagStyle = (section) => {
        const token =
            section === "differentials"
                ? "primaryButton"
                : section === "investigations"
                  ? "successButton"
                  : section === "considerations"
                    ? "secondaryButton"
                    : section === "thinking"
                      ? "neutralButton"
                      : null;
        if (!token) return { bg: "surface", color: "textPrimary" };
        const hex = colors[colorMode]?.[token] ?? colors.dark.surface2;
        return {
            bg: `${hex}1f`,
            color: hex,
            border: "1px solid",
            borderColor: `${hex}40`,
        };
    };

    const sfxVolume = 0.3;
    const SFX = {
        tick: "/sfx/tick.mp3",
        complete: "/sfx/complete.mp3",
        reset: "/sfx/reset.mp3",
    };
    const play = (url) => {
        try {
            const a = new Audio(url);
            a.volume = sfxVolume;
            a.play().catch(() => {});
        } catch {}
    };

    const renderPatientRow = (patient, index) => (
        <Table.Row
            key={patient.id}
            backgroundColor={getRowBackgroundColor(index)}
            transition="background-color 0.15s ease"
            _hover={{ backgroundColor: "surfaceQuartile" }}
            opacity={
                summaryOnly &&
                (patient.jobs_list?.length || 0) > 0 &&
                patient.jobs_list.every((j) => j.completed)
                    ? 0.5
                    : 1
            }
        >
            <Table.Cell width="25%" verticalAlign="top">
                {summaryOnly ? (
                    <Box>
                        <HStack gap="2">
                            <Icon asChild>
                                <FaUser />
                            </Icon>
                            <Text fontWeight="bold">
                                {formatName(patient.name)}
                            </Text>
                            <Tooltip
                                content="Go to Encounter"
                                showArrow
                                positioning={{
                                    placement: "right",
                                }}
                            >
                                <IconButton
                                    size="xs"
                                    variant="ghost"
                                    aria-label="Go to Encounter"
                                    onClick={() => handleSelectPatient(patient)}
                                >
                                    <Icon asChild>
                                        <FaArrowRight />
                                    </Icon>
                                </IconButton>
                            </Tooltip>
                        </HStack>
                        <HStack gap="2">
                            <Icon asChild>
                                <FaCalendarAlt />
                            </Icon>
                            <Text>{patient.dob}</Text>
                        </HStack>
                        <HStack gap="2">
                            <Icon asChild>
                                <FaIdBadge />
                            </Icon>
                            <Text>{patient.ur_number}</Text>
                        </HStack>
                    </Box>
                ) : (
                    <VStack align="stretch" gap={2}>
                        <Tooltip
                            content={`${patient.name}, DOB: ${patient.dob}, UR Number: ${patient.ur_number}`}
                            aria-label="Patient Details"
                        >
                            <PatientDetails patient={patient} />
                        </Tooltip>
                        <Button
                            className="grey-button"
                            size="sm"
                            onClick={() => handleSelectPatient(patient)}
                            maxW="150px"
                        >
                            Go to Encounter
                        </Button>
                    </VStack>
                )}
            </Table.Cell>

            <Table.Cell width="45%" position="relative" verticalAlign="top">
                {summaryOnly ? (
                    <Box
                        p={2}
                        borderRadius="lg"
                        bg="surface"
                    >
                        <Text fontSize="sm">
                            {patient.reasoning?.summary ??
                                patient.encounter_summary}
                        </Text>
                    </Box>
                ) : (
                    <Box>
                        <Grid templateColumns="40px 1fr" gap={0} h="120px">
                            <VStack align="flex-start" gap={0} w="30px">
                                {[
                                    {
                                        section: "summary",
                                        icon: FaFileAlt,
                                        tooltip: "Summary",
                                    },
                                    {
                                        section: "differentials",
                                        icon: FaSitemap,
                                        tooltip: "Differentials",
                                    },
                                    {
                                        section: "investigations",
                                        icon: FaVial,
                                        tooltip: "Investigations",
                                    },
                                    {
                                        section: "considerations",
                                        icon: FaBrain,
                                        tooltip: "Clinical Considerations",
                                    },
                                ].map(({ section, icon: ReasonIcon, tooltip }) => (
                                    <Tooltip
                                        key={section}
                                        content={tooltip}
                                        showArrow
                                        positioning={{
                                            placement: "right",
                                        }}
                                    >
                                        <Button
                                            key={section}
                                            className={`reason-button ${
                                                (!patient.reasoning &&
                                                    section === "summary") ||
                                                patient.activeSection ===
                                                    section
                                                    ? "reason-button-active-patient-table"
                                                    : ""
                                            }`}
                                            onClick={() => {
                                                if (
                                                    patient.reasoning ||
                                                    section === "summary"
                                                ) {
                                                    const updatedPatients =
                                                        patients.map((p) =>
                                                            p.id === patient.id
                                                                ? {
                                                                      ...p,
                                                                      activeSection:
                                                                          section,
                                                                  }
                                                                : p,
                                                        );
                                                    setPatients(
                                                        updatedPatients,
                                                    );
                                                }
                                            }}
                                            justifyContent="center"
                                            width="100%"
                                            height="28px"
                                            fontSize="xs"
                                            disabled={
                                                !patient.reasoning &&
                                                section !== "summary"
                                            }
                                            opacity={
                                                !patient.reasoning &&
                                                section !== "summary"
                                                    ? 0.5
                                                    : 1
                                            }
                                            p={1}
                                        >
                                            <Icon asChild>
                                                <ReasonIcon />
                                            </Icon>
                                        </Button>
                                    </Tooltip>
                                ))}
                            </VStack>

                            <Box
                            overflowY="auto"
                            className="scroll-container"
                            p={3}
                            bg="surface"
                                borderRadius="lg"
                                h="100%"
                                position="relative"
                            >
                                <Box
                                    key={
                                        patient.reasoning
                                            ? patient.activeSection
                                            : "summary"
                                    }
                                    className="anim-fade-slide-up"
                                    css={{ animationDuration: "0.15s" }}
                                >
                                        {patient.reasoning ? (
                                            <>
                                                {patient.activeSection ===
                                                    "summary" && (
                                                    <Text fontSize="sm">
                                                        {
                                                            patient.reasoning
                                                                .summary
                                                        }
                                                    </Text>
                                                )}
                                                {(patient.activeSection ===
                                                    "differentials" ||
                                                    patient.activeSection ===
                                                        "investigations" ||
                                                    patient.activeSection ===
                                                        "considerations") && (
                                                    <Wrap gap={1}>
                                                        {patient.reasoning[
                                                            patient.activeSection ===
                                                            "considerations"
                                                                ? "clinical_considerations"
                                                                : patient.activeSection
                                                        ]?.map((item, i) => (
                                                            <WrapItem key={i}>
                                                                <Box
                                                                    px={2}
                                                                    py={0.5}
                                                                    borderRadius="full"
                                                                    fontSize="sm"
                                                                    {...getTagStyle(
                                                                        patient.activeSection,
                                                                    )}
                                                                >
                                                                    {typeof item ===
                                                                    "string"
                                                                        ? item
                                                                        : item.suggestion}
                                                                </Box>
                                                            </WrapItem>
                                                        ))}
                                                    </Wrap>
                                                )}
                                            </>
                                        ) : (
                                            <Text fontSize="sm">
                                                {patient.encounter_summary}
                                            </Text>
                                        )}
                                    </Box>
                            </Box>
                        </Grid>
                    </Box>
                )}
            </Table.Cell>

            <Table.Cell width="30%" verticalAlign="top">
                <HStack gap={2} alignItems="flex-start">
                    <Tooltip content="Reset jobs" aria-label="Reset jobs">
                        <IconButton
                            size="sm"
                            variant="ghost"
                            onClick={() => {
                                play(SFX.reset);
                                resetJobsItems(
                                    patient.id,
                                    patients,
                                    setPatients,
                                    refreshSidebar,
                                );
                            }}
                        >
                            <RepeatIcon />
                        </IconButton>
                    </Tooltip>
                    <VStack align="start" gap={1}>
                        {patient.jobs_list?.length ? (
                            patient.jobs_list.map((item, index) => (
                                <Checkbox.Root
                                    key={index}
                                    className="checkbox task-checkbox"
                                    onCheckedChange={(e) => {
                                        const nextChecked = e.checked;

                                        if (nextChecked) {
                                            play(SFX.tick); // Always play tick on check

                                            const willBeCompletedList = (
                                                patient.jobs_list || []
                                            ).map((it, i) =>
                                                i === index
                                                    ? true
                                                    : !!it.completed,
                                            );
                                            const allCompleteAfter =
                                                willBeCompletedList.length >
                                                    0 &&
                                                willBeCompletedList.every(
                                                    Boolean,
                                                );

                                            if (allCompleteAfter) {
                                                setTimeout(() => {
                                                    play(SFX.complete);
                                                }, 300); // Delay before playing 'complete' sound
                                            }
                                        }

                                        const updatedJobsList =
                                            patient.jobs_list.map((j, i) =>
                                                i === index
                                                    ? {
                                                          ...j,
                                                          completed:
                                                              nextChecked,
                                                      }
                                                    : j,
                                            );

                                        setPatients((prevPatients) =>
                                            prevPatients.map((p) =>
                                                p.id === patient.id
                                                    ? {
                                                          ...p,
                                                          jobs_list:
                                                              updatedJobsList,
                                                      }
                                                    : p,
                                            ),
                                        );

                                        pendingJobsUpdates.current.set(
                                            patient.id,
                                            updatedJobsList,
                                        );

                                        debouncedUpdateJobsList(
                                            patient.id,
                                            updatedJobsList,
                                            refreshSidebar,
                                        );
                                    }}
                                    alignItems="flex-start"
                                    css={{
                                        "& .chakra-checkbox__label": {
                                            display: "block",
                                            whiteSpace: "normal",
                                            paddingTop: 0,
                                            ...(item.completed
                                                ? {
                                                      textDecoration:
                                                          "line-through",
                                                      opacity: 0.5,
                                                  }
                                                : {}),
                                        },

                                        "& .chakra-checkbox__control": {
                                            marginTop: "3px",
                                        },
                                    }}
                                    checked={item.completed}
                                >
                                    <Checkbox.HiddenInput />
                                    <Checkbox.Control>
                                        <Checkbox.Indicator />
                                    </Checkbox.Control>
                                    <Checkbox.Label>{item.job}</Checkbox.Label>
                                </Checkbox.Root>
                            ))
                        ) : (
                            <Text
                                fontSize="sm"
                                fontStyle="italic"
                                opacity={0.6}
                            >
                                No tasks
                            </Text>
                        )}
                    </VStack>
                </HStack>
            </Table.Cell>
        </Table.Row>
    );

    return (
        <Box p="5" borderRadius="xl" w="100%">
            <Text as="h2">{title}</Text>
            {groupByDate ? (
                Object.entries(
                    patients.reduce((acc, patient) => {
                        const date = patient.encounter_date;
                        if (!acc[date]) acc[date] = [];
                        acc[date].push(patient);
                        return acc;
                    }, {}),
                )
                    .sort((a, b) => new Date(b[0]) - new Date(a[0]))
                    .map(([date, patients]) => (
                        <Box key={date} mb={8}>
                            <Text as="h3" mb={2}>
                                {new Date(date).toLocaleDateString()}
                            </Text>
                            <Box
                                overflowX="auto"
                                border="1px solid"
                                borderColor="surface"
                                borderRadius="xl"
                            >
                                <Table.Root
                                    variant="simple"
                                    borderRadius="lg"
                                    overflow="hidden"
                                    css={{
                                        borderCollapse: "separate",
                                        borderSpacing: 0,
                                    }}
                                >
                                    <Table.Header
                                        bg="surface"
                                    >
                                        <Table.Row>
                                            <Table.ColumnHeader width="25%">
                                                Patient Details
                                            </Table.ColumnHeader>
                                            <Table.ColumnHeader width="45%">
                                                Reasoning / Encounter Summary
                                            </Table.ColumnHeader>
                                            <Table.ColumnHeader width="30%">
                                                Jobs
                                            </Table.ColumnHeader>
                                        </Table.Row>
                                    </Table.Header>
                                    <Table.Body>
                                        {patients
                                            .sort((a, b) => a.id - b.id)
                                            .map((patient, index) =>
                                                renderPatientRow(
                                                    patient,
                                                    index,
                                                ),
                                            )}
                                    </Table.Body>
                                </Table.Root>
                            </Box>
                        </Box>
                    ))
            ) : (
                <Box
                    overflowX="auto"
                    border="1px solid"
                    borderColor="surface"
                    borderRadius="xl"
                >
                    <Table.Root
                        variant="simple"
                        borderRadius="lg"
                        overflow="hidden"
                        css={{
                            borderCollapse: "separate",
                            borderSpacing: 0,
                        }}
                    >
                        <Table.Header
                            bg="surface"
                        >
                            <Table.Row>
                                <Table.ColumnHeader width="25%">
                                    Patient Details
                                </Table.ColumnHeader>
                                <Table.ColumnHeader width="45%">
                                    Reasoning / Encounter Summary
                                </Table.ColumnHeader>
                                <Table.ColumnHeader width="30%">
                                    Jobs
                                </Table.ColumnHeader>
                            </Table.Row>
                        </Table.Header>
                        <Table.Body>
                            {patients
                                .slice()
                                .sort((a, b) => a.id - b.id)
                                .map((patient, index) =>
                                    renderPatientRow(patient, index),
                                )}
                        </Table.Body>
                    </Table.Root>
                </Box>
            )}
        </Box>
    );
};

export default PatientTable;

import { useEffect, useState, useRef, useCallback } from "react";
import { useTranscription } from "../../utils/hooks/useTranscription";
import { settingsService } from "../../utils/settings/settingsUtils";
import { settingsApi } from "../../utils/api/settingsApi";
import { AudioRecorder } from "../../utils/audioRecorder";

// Hook to manage scribe state and logic
// This can be used by ScribePillBox to control recording
export const useScribe = ({
    name,
    dob,
    gender,
    template,
    noteId,
    handleTranscriptionComplete,
    setLoading,
    onSendStart,
}) => {
    const [isAmbient, setIsAmbient] = useState(true);
    const [requireConsent, setRequireConsent] = useState(false);
    const [isRecording, setIsRecording] = useState(false);
    const [isPaused, setIsPaused] = useState(false);
    const [timer, setTimer] = useState(0);
    const audioRecorderRef = useRef(null);
    const timerIntervalRef = useRef(null);

    const [sendError, setSendError] = useState(null); // null = ok, else { message }
    const lastFailedRef = useRef({ blob: null, meta: null, isAmbient: null });

    // Transcription API
    const { transcribeAudio, isTranscribing } = useTranscription((data) => {
        if (data?.error) return;
        handleTranscriptionComplete({
            fields: data.fields,
            rawTranscription: data.rawTranscription,
            transcriptionDuration: data.transcriptionDuration,
            processDuration: data.processDuration,
        });
    }, setLoading);

    // Fetch user settings on mount
    useEffect(() => {
        const fetchSettings = async () => {
            try {
                const data = await settingsApi.fetchUserSettings();
                if (data && typeof data.scribe_is_ambient === "boolean") {
                    setIsAmbient(data.scribe_is_ambient);
                }
                setRequireConsent(
                    Boolean(data?.advanced_options?.require_scribe_consent),
                );
            } catch (error) {
                console.error("Error fetching user settings:", error);
            }
        };
        fetchSettings();
    }, []);

    // Timer effect
    useEffect(() => {
        if (isRecording && !isPaused) {
            timerIntervalRef.current = setInterval(() => {
                setTimer((prev) => prev + 1);
            }, 1000);
        } else {
            clearInterval(timerIntervalRef.current);
        }
        return () => clearInterval(timerIntervalRef.current);
    }, [isRecording, isPaused]);

    const resetRecordingState = useCallback(() => {
        setIsRecording(false);
        setIsPaused(false);
        setTimer(0);
        setSendError(null);
        lastFailedRef.current = { blob: null, meta: null, isAmbient: null };
        if (audioRecorderRef.current) {
            audioRecorderRef.current.stop().catch(() => {});
        }
        audioRecorderRef.current = null;
    }, []);

    // Reset when patient changes
    useEffect(() => {
        resetRecordingState();
    }, [name, dob, gender, resetRecordingState]);

    const clearLastFailed = useCallback(() => {
        lastFailedRef.current = { blob: null, meta: null, isAmbient: null };
        setSendError(null);
    }, []);

    const sendForTranscription = useCallback(
        async (blob, meta) => {
            try {
                await transcribeAudio(blob, meta, isAmbient);
                clearLastFailed();
                return true;
            } catch (error) {
                console.error("Transcription failed:", error);
                lastFailedRef.current = { blob, meta: { ...meta }, isAmbient };
                const message = error?.message || "Transcription failed";
                setSendError({ message });
                return false;
            }
        },
        [transcribeAudio, isAmbient, clearLastFailed],
    );

    const retrySend = useCallback(async () => {
        const { blob, meta, isAmbient: ambient } = lastFailedRef.current;
        if (!blob) return false;
        try {
            await transcribeAudio(blob, meta, ambient);
            clearLastFailed();
            return true;
        } catch (error) {
            console.error("Transcription retry failed:", error);
            const message = error?.message || "Transcription failed";
            setSendError({ message });
            return false;
        }
    }, [transcribeAudio, clearLastFailed]);

    const downloadLastRecording = useCallback(() => {
        const { blob } = lastFailedRef.current;
        if (!blob) return;
        const ext = blob.type.includes("wav")
            ? "wav"
            : blob.type.includes("webm")
              ? "webm"
              : "audio";
        const stamp = new Date()
            .toISOString()
            .replace(/[:.]/g, "-")
            .slice(0, 19);
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `recording_${stamp}.${ext}`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }, []);

    const dismissSendError = useCallback(() => {
        clearLastFailed();
    }, [clearLastFailed]);

    const startRecording = useCallback(async () => {
        try {
            const recorder = new AudioRecorder();
            await recorder.start();
            audioRecorderRef.current = recorder;
            setIsRecording(true);
            setTimer(0);
        } catch (error) {
            console.error("Error starting recording:", error);
            alert("Could not access microphone. Please check your permissions.");
        }
    }, []);

    const pauseRecording = useCallback(() => {
        audioRecorderRef.current?.pause();
        setIsPaused(true);
    }, []);

    const resumeRecording = useCallback(() => {
        audioRecorderRef.current?.resume();
        setIsPaused(false);
    }, []);

    const stopAndSendRecording = useCallback(async () => {
        // Collapse any open panels when sending
        if (onSendStart) {
            onSendStart();
        }
        if (!isRecording || !audioRecorderRef.current) {
            return null;
        }
        const recorder = audioRecorderRef.current;
        audioRecorderRef.current = null;
        setIsRecording(false);
        setIsPaused(false);
        const blob = await recorder.stop();
        await sendForTranscription(blob, {
            name,
            gender,
            dob,
            templateKey: template?.template_key,
            noteId,
        });
        return blob;
    }, [
        isRecording,
        sendForTranscription,
        name,
        gender,
        dob,
        template,
        noteId,
        onSendStart,
    ]);

    const resetRecording = useCallback(() => {
        if (isRecording && audioRecorderRef.current) {
            audioRecorderRef.current.stop().catch(() => {});
            audioRecorderRef.current = null;
        }
        resetRecordingState();
    }, [isRecording, resetRecordingState]);

    const toggleAmbientMode = useCallback(async () => {
        const newValue = !isAmbient;
        setIsAmbient(newValue);
        try {
            await settingsService.saveAmbientMode(newValue);
        } catch (error) {
            console.error("Failed to save ambient mode setting:", error);
        }
    }, [isAmbient]);

    // Handle audio file drop
    const handleAudioDrop = useCallback(
        async (file) => {
            if (!file.type.startsWith("audio/")) {
                return false;
            }

            return sendForTranscription(file, {
                name,
                gender,
                dob,
                templateKey: template?.template_key,
                noteId,
            });
        },
        [sendForTranscription, name, gender, dob, template, noteId],
    );

    return {
        // State
        isAmbient,
        requireConsent,
        isRecording,
        isPaused,
        timer,
        isLoading: isTranscribing,
        sendError,

        // Actions
        startRecording,
        pauseRecording,
        resumeRecording,
        stopAndSendRecording,
        resetRecording,
        toggleAmbientMode,
        handleAudioDrop,
        retrySend,
        downloadLastRecording,
        dismissSendError,
    };
};

// The actual UI is in ScribePillBox and the panels
const Scribe = ({ children }) => {
    return children || null;
};

export default Scribe;

import { useState, useCallback } from "react";
import { Box } from "@chakra-ui/react";
import PillBox from "../common/PillBox";
import { LoadingOrb } from "./scribeVisuals";
import {
    RecordButton,
    ModeResetButton,
    TranscriptSendButton,
    TranscriptionFailurePill,
} from "./scribeButtons";

const ScribePillBox = ({
    // Recording state
    isRecording,
    isPaused,
    onStart,
    onPause,
    onResume,
    onSend,
    onReset,
    isLoading,
    // Mode toggle
    isAmbient,
    onModeToggle,
    // Panel handlers
    onOpenTranscription,
    // Panel states
    isTranscriptionOpen,
    // Other
    hasRawTranscription,
    // Audio file drop
    onAudioDrop,
    // Recording gate
    canRecord = true,
    onBlockedRecord,
    // Transcription failure recovery
    sendError,
    onRetry,
    onDownload,
    onDismiss,
}) => {
    const [isDragOver, setIsDragOver] = useState(false);

    const handleDragOver = useCallback((e) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.dataTransfer.types.includes("Files")) {
            setIsDragOver(true);
        }
    }, []);

    const handleDragLeave = useCallback((e) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragOver(false);
    }, []);

    const handleDrop = useCallback(
        async (e) => {
            e.preventDefault();
            e.stopPropagation();
            setIsDragOver(false);

            if (!canRecord) {
                onBlockedRecord?.();
                return;
            }

            if (!onAudioDrop) return;

            const file = e.dataTransfer.files[0];
            if (file && file.type.startsWith("audio/")) {
                await onAudioDrop(file);
            }
        },
        [canRecord, onBlockedRecord, onAudioDrop],
    );

    if (isLoading) {
        return (
            <PillBox
                bottom="20px"
                left="50%"
                transform="translateX(-50%)"
                className="pill-box-scribe"
                px={2}
                py={2}
                gap={0}
            >
                <LoadingOrb size={46} />
            </PillBox>
        );
    }

    if (sendError) {
        return (
            <TranscriptionFailurePill
                sendError={sendError}
                onRetry={onRetry}
                onDownload={onDownload}
                onDismiss={onDismiss}
            />
        );
    }

    return (
        <PillBox
            bottom="20px"
            className="pill-box-scribe"
            left="50%"
            transform="translateX(-50%)"
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
        >
            {/* Drop zone overlay */}
            {isDragOver && (
                <Box
                    position="absolute"
                    top="-8px"
                    left="-8px"
                    right="-8px"
                    bottom="-8px"
                    borderRadius="full"
                    border="2px dashed"
                    borderColor="accent"
                    bg="rgba(66, 153, 225, 0.15)"
                    zIndex={-1}
                    pointerEvents="none"
                />
            )}

            {/* Left: Mode toggle / Reset */}
            <ModeResetButton
                isRecording={isRecording}
                isAmbient={isAmbient}
                onModeToggle={onModeToggle}
                onReset={onReset}
            />

            {/* Center: Record button */}
            <RecordButton
                isRecording={isRecording}
                isPaused={isPaused}
                onStart={onStart}
                onPause={onPause}
                onResume={onResume}
                size={46}
                canStart={canRecord}
                onBlockedClick={onBlockedRecord}
            />

            {/* Right: Transcript / Send */}
            <TranscriptSendButton
                isRecording={isRecording}
                onOpenTranscription={onOpenTranscription}
                onSend={onSend}
                isTranscriptionOpen={isTranscriptionOpen}
                hasRawTranscription={hasRawTranscription}
            />
        </PillBox>
    );
};

export default ScribePillBox;

import React, {
  useState,
  useRef,
  forwardRef,
  useImperativeHandle,
} from "react";
import TextareaAutosize from "react-textarea-autosize";
import { Box, Flex, Text, Collapsible, HStack, NativeSelect, VStack, Center, Spinner } from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import { Tooltip } from '@/components/ui/tooltip';
import {
  EditIcon,
  CopyIcon,
  CheckIcon,
} from "../common/icons";
import { FaSave, FaFileAlt, FaThumbtack, FaCheckDouble } from "react-icons/fa";
import { GreenButton, GreyButton } from "../common/Buttons";
import { useTemplateSelection } from "../../utils/templates/templateContext";
import { patientApi } from "../../utils/api/patientApi";
import ConfirmLeaveModal from "../modals/ConfirmLeaveModal";

const Summary = forwardRef(
  (
    {
      isSummaryCollapsed,
      patient,
      setPatient,
      handleGenerateLetterClick,
      handleSavePatientData,
      saveLoading,
      onWrapUp,
      wrapUpLoading,
      setIsModified,
      onCopy,
      recentlyCopied,
      isNewPatient,
      selectTemplate,
      isSearchedPatient,
      isEncounterSaved = false,
    },
    ref,
  ) => {
    const {
      currentTemplate,
      templates,
      status: templateStatus,
    } = useTemplateSelection();

    const textareasRefs = useRef({});
    const [isTemplateChangeModalOpen, setIsTemplateChangeModalOpen] =
      useState(false);
    const [pendingTemplateKey, setPendingTemplateKey] = useState(null);

    const handleTemplateChange = async (e) => {
      const newTemplateKey = e.target.value;

      if (!isNewPatient && !isSearchedPatient) {
        toaster.create({
          title: "Template Locked",
          description: "Template cannot be changed for historical encounters",
          type: "warning",
          duration: 3000,
        });
        return;
      }

      setPendingTemplateKey(newTemplateKey);
      setIsTemplateChangeModalOpen(true);
    };

    const confirmTemplateChange = async () => {
      console.log("confirmTemplateChange called", {
        ur_number: patient?.ur_number,
        pendingTemplateKey,
      });

      // If patient has a UR number, fetch persistent fields for the new template type
      if (patient?.ur_number) {
        try {
          // Extract base template key (e.g., "soap" from "soap_01")
          const baseTemplateKey = pendingTemplateKey.split("_")[0];
          console.log("Fetching history for template:", baseTemplateKey);

          const history = await patientApi.fetchPatientHistoryByTemplate(
            patient.ur_number,
            baseTemplateKey,
          );

          console.log("History result:", history);

          if (history && history.length > 0) {
            // Merge persistent fields from most recent note of this type
            const mostRecent = history[0];
            setPatient((prev) => ({
              ...prev,
              template_key: pendingTemplateKey,
              template_data: {
                ...mostRecent.template_data,
              },
            }));
            setIsTemplateChangeModalOpen(false);
            await selectTemplate(pendingTemplateKey);
            return;
          }
        } catch (error) {
          console.error("Error fetching history for template:", error);
        }
      }

      // Fallback: just change template without pre-filling
      console.log("Falling back to simple template change");
      selectTemplate(pendingTemplateKey);
      setIsTemplateChangeModalOpen(false);
    };

    const handleTemplateDataChange = (fieldKey, value) => {
      setPatient((prev) => ({
        ...prev,
        template_data: {
          ...prev.template_data,
          [fieldKey]: value,
        },
      }));
      setIsModified(true);
    };

    const renderField = (field) => {
      const persistentMarker = field.persistent ? (
        <Tooltip
          content="Persists between encounters."
          showArrow
          positioning={{
            placement: "right"
          }}
        >
          <Box as="span" className="cohesive-persistent-marker">
            <FaThumbtack />
          </Box>
        </Tooltip>
      ) : null;

      return (
        <Box key={field.field_key} className="cohesive-field">
          <Text className="cohesive-field-label">
            {field.field_name}:{persistentMarker}
          </Text>
          <TextareaAutosize
            placeholder="Enter text..."
            value={patient.template_data?.[field.field_key] || ""}
            onChange={(e) => {
              handleTemplateDataChange(field.field_key, e.target.value);
            }}
            className="cohesive-textarea"
            ref={(el) => (textareasRefs.current[field.field_key] = el)}
          />
        </Box>
      );
    };

    useImperativeHandle(ref, () => ({
      resizeTextarea: () => {
        Object.values(textareasRefs.current).forEach((textarea) => {
          if (textarea) {
            textarea.style.height = "auto";
            textarea.style.height = `${textarea.scrollHeight}px`;
          }
        });
      },
    }));

    if (templateStatus === "loading") {
      return (
        <Box p="4" borderRadius="sm" className="panels-bg">
          <Center mt={4}>
            <Spinner size="sm" animationDuration="0.65s" />
            <Text ml={2}>Loading template...</Text>
          </Center>
        </Box>
      );
    }

    return (
      <>
        <Box p={[2, 3, 4]} borderRadius="sm" className="panels-bg">
          <Flex align="center" justify="space-between">
            <Flex align="center">
              <HStack gap={2}>
                <EditIcon size="1.2em" />
                <Text as="h3">Note</Text>
              </HStack>
            </Flex>
            <Tooltip
              content={
                isNewPatient
                  ? "Select Template"
                  : "Template cannot be changed for historical encounters"
              }
              aria-label="Template Selector Tooltip"
            >
              <Box>
                <Flex alignItems="center">
                  <FaFileAlt
                    style={{ marginRight: "8px" }}
                    className="pill-box-icons"
                  />
                  <NativeSelect.Root>
                    <NativeSelect.Field
                      placeholder="Select Template"
                      value={
                        currentTemplate?.template_key ||
                        patient?.template_key ||
                        ""
                      }
                      onChange={handleTemplateChange}
                      size="sm"
                      width={["100px", "150px", "200px"]}
                      className="input-style"
                      disabled={!isNewPatient}>
                      {/* Show "Historical Template" only for viewing historical encounters */}
                      {!isNewPatient &&
                        !isSearchedPatient &&
                        patient?.template_key &&
                        !templates?.some(
                          (t) => t.template_key === patient.template_key,
                        ) && (
                          <option value={patient.template_key}>
                            Historical Template
                          </option>
                        )}
                      {templates?.map((t) => (
                        <option key={t.template_key} value={t.template_key}>
                          {t.template_name}
                        </option>
                      ))}
                    </NativeSelect.Field>
                    <NativeSelect.Indicator />
                  </NativeSelect.Root>
                </Flex>
              </Box>
            </Tooltip>
          </Flex>

          <Collapsible.Root open={!isSummaryCollapsed}>
            <Collapsible.Content>
              <Box mt="4" className="cohesive-fields-container">
                <VStack gap="0" align="stretch">
                  {currentTemplate?.fields?.map(renderField)}
                </VStack>
              </Box>
              <Flex mt="4" justifyContent="space-between">
                <Flex>
                  <Tooltip
                    content={
                      isEncounterSaved
                        ? "Generate a letter from this note"
                        : "Save the encounter first to generate a letter"
                    }
                    positioning={{
                      placement: "top"
                    }}
                  >
                    <Box>
                      <GreyButton
                        onClick={() => handleGenerateLetterClick(null)}
                        leftIcon={<EditIcon />}
                        mr="2"
                        disabled={saveLoading || !isEncounterSaved}
                      >
                        Generate Letter
                      </GreyButton>
                    </Box>
                  </Tooltip>
                </Flex>
                <Flex>
                  <Tooltip
                    content="Copy the full note to your clipboard"
                    positioning={{
                      placement: "top"
                    }}
                  >
                    <Box>
                      <GreyButton
                        onClick={onCopy}
                        width="190px"
                        leftIcon={recentlyCopied ? <CheckIcon /> : <CopyIcon />}
                        mr="2"
                      >
                        {recentlyCopied ? "Copied!" : "Copy to Clipboard"}
                      </GreyButton>
                    </Box>
                  </Tooltip>
                  <Tooltip
                    content="Save the current encounter"
                    positioning={{
                      placement: "top"
                    }}
                  >
                    <Box>
                      <GreyButton
                        onClick={handleSavePatientData}
                        loading={saveLoading}
                        loadingText="Saving"
                        width="190px"
                        leftIcon={saveLoading ? null : <FaSave />}
                      >
                        {saveLoading ? "Saving..." : "Save Encounter"}
                      </GreyButton>
                    </Box>
                  </Tooltip>
                  <Tooltip
                    content="Review AI-extracted jobs, then finish and move to a new note"
                    positioning={{
                      placement: "top"
                    }}
                  >
                    <Box>
                      <GreenButton
                        onClick={onWrapUp}
                        loading={wrapUpLoading}
                        loadingText="Wrapping"
                        width="150px"
                        ml="2"
                        leftIcon={wrapUpLoading ? null : <FaCheckDouble />}
                        disabled={saveLoading}
                      >
                        {wrapUpLoading ? "Wrapping..." : "Wrap Up"}
                      </GreenButton>
                    </Box>
                  </Tooltip>
                </Flex>
              </Flex>
            </Collapsible.Content>
          </Collapsible.Root>
        </Box>
        <ConfirmLeaveModal
          isOpen={isTemplateChangeModalOpen}
          onClose={() => setIsTemplateChangeModalOpen(false)}
          confirmNavigation={confirmTemplateChange}
        />
      </>
    );
  },
);

export default Summary;

