// Modal for replacing a template's PDF while keeping its field definitions.
import React, { useState, useRef } from "react";
import { Text, VStack, Box, Dialog, Portal } from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import { pdfFormsApi } from "../../utils/api/pdfFormsApi";
import { loadPdfDocument } from "../../utils/helpers/pdfVisionHelpers";
import { GreenButton, GreyButton } from "../common/Buttons";

const ReplacePdfModal = ({ isOpen, onClose, template, onReplaced }) => {
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef(null);

  const expectedPages = template?.page_count;
  const expectedHeights = template?.page_heights || [];

  const handleFileChange = (e) => {
    const selected = e.target.files?.[0];
    if (selected && !selected.name.toLowerCase().endsWith(".pdf")) {
      toaster.create({
        title: "Invalid file",
        description: "Please select a PDF file",
        type: "error",
        duration: 2000,
      });
      return;
    }
    setFile(selected || null);
  };

  const handleSubmit = async () => {
    if (!file || !template) return;

    setUploading(true);
    try {
      const arrayBuffer = await file.arrayBuffer();
      const pdf = await loadPdfDocument({ data: arrayBuffer });

      const pageCount = pdf.numPages;
      const pageHeights = [];
      for (let i = 1; i <= pageCount; i++) {
        const page = await pdf.getPage(i);
        const viewport = page.getViewport({ scale: 1 });
        pageHeights.push(viewport.height);
      }

      if (pageCount !== expectedPages) {
        throw new Error(
          `Replacement must have ${expectedPages} page(s); got ${pageCount}.`,
        );
      }
      for (let i = 0; i < pageHeights.length; i++) {
        if (Math.abs(pageHeights[i] - expectedHeights[i]) > 0.5) {
          throw new Error(
            `Page ${i + 1} height differs from the original; fields would misalign.`,
          );
        }
      }

      const formData = new FormData();
      formData.append("pdf", file);
      formData.append("page_count", String(pageCount));
      formData.append("page_heights", JSON.stringify(pageHeights));

      const updated = await pdfFormsApi.replaceTemplatePdf(
        template.id,
        formData,
      );
      toaster.create({
        title: "PDF replaced",
        description: "Field definitions kept",
        type: "success",
        duration: 2000,
      });
      onReplaced(updated);
      handleClose();
    } catch (error) {
      toaster.create({
        title: "Replace failed",
        description: error.message,
        type: "error",
        duration: 3000,
      });
    } finally {
      setUploading(false);
    }
  };

  const handleClose = () => {
    setFile(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
    onClose();
  };

  return (
    <Dialog.Root open={isOpen} size="md" onOpenChange={(e) => {
      if (!e.open) handleClose();
    }}>
      <Portal>
        <Dialog.Backdrop />
        <Dialog.Positioner>
          <Dialog.Content>
            <Dialog.Header>
              <Text as="h3">Replace PDF</Text>
            </Dialog.Header>
            <Dialog.Body>
              <VStack gap="4">
                <Box w="100%">
                  <Text fontSize="sm" fontWeight="bold" mb="2">
                    New PDF for &ldquo;{template?.name}&rdquo;
                  </Text>
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept=".pdf"
                    onChange={handleFileChange}
                    style={{ display: "block", width: "100%", fontSize: "0.875rem" }}
                  />
                </Box>
                <Text fontSize="xs" color="overlay0">
                  Field definitions are kept. The new PDF must have{" "}
                  {expectedPages} page(s) with matching dimensions.
                </Text>
              </VStack>
            </Dialog.Body>
            <Dialog.Footer>
              <GreyButton mr="3" onClick={handleClose}>
                Cancel
              </GreyButton>
              <GreenButton onClick={handleSubmit} loading={uploading} disabled={!file}>
                Replace
              </GreenButton>
            </Dialog.Footer>
          </Dialog.Content>
        </Dialog.Positioner>
      </Portal>
    </Dialog.Root>
  );
};

export default ReplacePdfModal;

// Modal for uploading a new PDF form template.
import React, { useState, useRef } from "react";
import { Input, Text, VStack, Box, Dialog, Portal } from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import { pdfFormsApi } from "../../utils/api/pdfFormsApi";
import { loadPdfDocument } from "../../utils/helpers/pdfVisionHelpers";
import { GreenButton, GreyButton } from "../common/Buttons";

const UploadTemplateModal = ({ isOpen, onClose, onCreated }) => {
  const [name, setName] = useState("");
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef(null);

  const handleFileChange = (e) => {
    const selected = e.target.files?.[0];
    if (selected && !selected.name.toLowerCase().endsWith(".pdf")) {
      toaster.create({
        title: "Invalid file",
        description: "Please select a PDF file",
        type: "error",
        duration: 2000,
      });
      return;
    }
    setFile(selected || null);
    if (!name && selected) {
      setName(selected.name.replace(/\.pdf$/i, ""));
    }
  };

  const handleSubmit = async () => {
    if (!file || !name.trim()) return;

    setUploading(true);
    try {
      const arrayBuffer = await file.arrayBuffer();
      const pdf = await loadPdfDocument({ data: arrayBuffer });

      const pageCount = pdf.numPages;
      const pageHeights = [];

      for (let i = 1; i <= pageCount; i++) {
        const page = await pdf.getPage(i);
        const viewport = page.getViewport({ scale: 1 });
        pageHeights.push(viewport.height);
      }

      const formData = new FormData();
      formData.append("name", name.trim());
      formData.append("pdf", file);
      formData.append("page_count", String(pageCount));
      formData.append("page_heights", JSON.stringify(pageHeights));

      const template = await pdfFormsApi.uploadTemplate(formData);
      toaster.create({
        title: "Template created",
        description: `"${name}" uploaded (${pageCount} page${pageCount !== 1 ? "s" : ""})`,
        type: "success",
        duration: 2000,
      });
      onCreated(template);
      handleClose();
    } catch (error) {
      toaster.create({
        title: "Upload failed",
        description: error.message,
        type: "error",
        duration: 3000,
      });
    } finally {
      setUploading(false);
    }
  };

  const handleClose = () => {
    setName("");
    setFile(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
    onClose();
  };

  return (
    <Dialog.Root open={isOpen} size='md' onOpenChange={e => {
      if (!e.open) {
        handleClose();
      }
    }}>
      <Portal>

        <Dialog.Backdrop />
        <Dialog.Positioner>
          <Dialog.Content>
            <Dialog.Header>
              <Text as="h3">New Form Template</Text>
            </Dialog.Header>
            <Dialog.Body>
              <VStack gap="4">
                <Box w="100%">
                  <Text fontSize="sm" fontWeight="bold" mb="2">
                    Template Name
                  </Text>
                  <Input
                    placeholder="e.g. Referral Form"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="input-style"
                  />
                </Box>
                <Box w="100%">
                  <Text fontSize="sm" fontWeight="bold" mb="2">
                    PDF File
                  </Text>
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept=".pdf"
                    onChange={handleFileChange}
                    style={{ display: "block", width: "100%", fontSize: "0.875rem" }}
                  />
                </Box>
                <Text fontSize="xs" color="overlay0">
                  Page metadata will be extracted automatically by the browser.
                </Text>
              </VStack>
            </Dialog.Body>
            <Dialog.Footer>
              <GreyButton mr="3" onClick={handleClose}>
                Cancel
              </GreyButton>
              <GreenButton
                onClick={handleSubmit}
                loading={uploading}
                disabled={!file || !name.trim()}
              >
                Upload
              </GreenButton>
            </Dialog.Footer>
          </Dialog.Content>
        </Dialog.Positioner>

      </Portal>
    </Dialog.Root>
  );
};

export default UploadTemplateModal;

// Component for bulk uploading and vectorizing multiple PDF documents.
import React, { useState, useRef } from "react";
import { Field, Box, Text, Flex, HStack, VStack, Input, Button, IconButton, Collapsible, Spinner } from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import {
    ChevronDownIcon,
    CloseIcon,
    CheckIcon,
    WarningIcon,
} from "../common/icons";
import { FaFilePdf, FaCloudUploadAlt } from "react-icons/fa";
import { useBulkUploadQueue, STATUS } from "../../utils/hooks/useBulkUploadQueue";

const StatusIcon = ({ status }) => {
    switch (status) {
        case STATUS.EXTRACTING:
        case STATUS.COMMITTING:
            return <Spinner size="xs" mr="2" />;
        case STATUS.EXTRACTED:
            return <CheckIcon color="successButton" mr="2" boxSize={3} />;
        case STATUS.COMMITTED:
            return (
                <CheckIcon color="successButton" mr="2" boxSize={3} />
            );
        case STATUS.FAILED:
            return <WarningIcon color="dangerButton" mr="2" boxSize={3} />;
        default:
            return null;
    }
};

const BulkUploader = ({ setCollections }) => {
    const [isDragOver, setIsDragOver] = useState(false);
    const [expandedFile, setExpandedFile] = useState(null);
    const fileInputRef = useRef(null);

    const {
        fileQueue,
        isProcessing,
        addFiles,
        removeFromQueue,
        updateMetadata,
        extractAll,
        commitAll,
        extractedCount,
        committedCount,
        totalPending,
        readyToCommit,
        hasPendingOrFailed,
    } = useBulkUploadQueue({ setCollections });

    // --- Drag and drop handlers ---

    const handleDragOver = (e) => {
        e.preventDefault();
        setIsDragOver(true);
    };

    const handleDragLeave = (e) => {
        e.preventDefault();
        setIsDragOver(false);
    };

    const handleDrop = (e) => {
        e.preventDefault();
        setIsDragOver(false);
        const files = Array.from(e.dataTransfer?.files || []);
        const pdfFiles = files.filter(
            (f) =>
                f.type === "application/pdf" ||
                f.name.toLowerCase().endsWith(".pdf"),
        );
        if (pdfFiles.length === 0) {
            toaster.create({
                title: "No PDF files",
                description: "Only PDF files are supported",
                type: "warning",
                duration: 3000,
            });
            return;
        }
        if (files.length > pdfFiles.length) {
            toaster.create({
                title: "Some files skipped",
                description: `${files.length - pdfFiles.length} non-PDF file(s) were ignored`,
                type: "info",
                duration: 3000,
            });
        }
        addFiles(pdfFiles);
    };

    const handleFileSelect = (e) => {
        const files = Array.from(e.target.files || []);
        if (files.length > 0) {
            addFiles(files);
        }
        e.target.value = "";
    };

    // --- Status icon ---

    const statusLabel = (entry) => {
        switch (entry.status) {
            case STATUS.PENDING:
                return "Pending";
            case STATUS.EXTRACTING:
                return "Extracting...";
            case STATUS.EXTRACTED:
                return "Ready to commit";
            case STATUS.COMMITTING:
                return "Committing...";
            case STATUS.COMMITTED:
                return "Committed ✓";
            case STATUS.FAILED:
                return entry.error || "Failed";
            default:
                return "";
        }
    };

    return (
        <VStack gap={4} align="stretch">
            {/* Drop zone */}
            <Box
                        border="2px dashed"
                        borderColor={isDragOver ? "accent" : "border"}
                        borderRadius="md"
                        p="6"
                        textAlign="center"
                        cursor="pointer"
                        bg={isDragOver ? "surfaceMuted" : "transparent"}
                        _hover={{ borderColor: "border" }}
                        onDragOver={handleDragOver}
                        onDragLeave={handleDragLeave}
                        onDrop={handleDrop}
                        onClick={() => fileInputRef.current?.click()}
                        transition="all 0.2s"
                    >
                        <FaCloudUploadAlt
                            size="2em"
                            color={isDragOver ? "#3182ce" : "#a0aec0"}
                            style={{ margin: "0 auto 8px" }}
                        />
                        <Text fontSize="sm" color="overlay0">
                            Drag and drop PDFs here, or click to browse
                        </Text>
                        <Input
                            ref={fileInputRef}
                            type="file"
                            multiple
                            accept=".pdf"
                            onChange={handleFileSelect}
                            display="none"
                        />
                    </Box>
            {/* File queue */}
            {fileQueue.length > 0 && (
                <VStack gap={2} align="stretch">
                    {fileQueue.map((entry) => (
                        <Box key={entry.id}>
                            <Flex
                                alignItems="center"
                                p="2"
                                borderRadius="sm"
                                className="documentExplorer-style"
                                _hover={{ bg: "surfaceMuted" }}
                            >
                                <Box mr="2" color="dangerButton" asChild><FaFilePdf /></Box>
                                <Text
                                    fontSize="sm"
                                    fontWeight="medium"
                                    flex="1"
                                    isTruncated
                                >
                                    {entry.file.name}
                                </Text>
                                <StatusIcon status={entry.status} />
                                <Text
                                    fontSize="xs"
                                    color={
                                        entry.status === STATUS.FAILED
                                            ? "dangerButton"
                                            : "overlay0"
                                    }
                                    mr="2"
                                >
                                    {statusLabel(entry)}
                                </Text>
                                {entry.status === STATUS.EXTRACTED && (
                                    <IconButton
                                        aria-label="Edit metadata"
                                        size="xs"
                                        variant="ghost"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setExpandedFile(
                                                expandedFile ===
                                                    entry.id
                                                    ? null
                                                    : entry.id,
                                            );
                                        }}
                                        mr="1"><ChevronDownIcon /></IconButton>
                                )}
                                {(entry.status === STATUS.PENDING ||
                                    entry.status === STATUS.EXTRACTED) &&
                                    !isProcessing && (
                                        <IconButton
                                            aria-label="Remove from queue"
                                            size="xs"
                                            variant="ghost"
                                            colorPalette="red"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                removeFromQueue(
                                                    entry.id,
                                                );
                                            }}><CloseIcon /></IconButton>
                                    )}
                            </Flex>

                            {/* Metadata editing */}
                            {entry.status === STATUS.EXTRACTED &&
                                entry.metadata && (
                                    <Collapsible.Root
                                        open={
                                            expandedFile === entry.id
                                        }>
                                        <Collapsible.Content>
                                            <VStack
                                                gap={2}
                                                align="stretch"
                                                pl="8"
                                                py="2"
                                                className="filelist-style"
                                            >
                                                <Field.Root>
                                                <Field.Label
                                                    fontSize="xs"
                                                    mb="0"
                                                >
                                                    Collection Name
                                                </Field.Label>
                                                <Input
                                                    size="sm"
                                                    className="input-style"
                                                    value={
                                                        entry.metadata
                                                            .disease_name
                                                    }
                                                    onChange={(e) =>
                                                        updateMetadata(
                                                            entry.id,
                                                            "disease_name",
                                                            e.target.value,
                                                        )
                                                    }
                                                />
                                                </Field.Root>
                                                <Field.Root>
                                                <Field.Label
                                                    fontSize="xs"
                                                    mb="0"
                                                >
                                                    Document Source
                                                </Field.Label>
                                                <Input
                                                    size="sm"
                                                    className="input-style"
                                                    value={
                                                        entry.metadata
                                                            .document_source
                                                    }
                                                    onChange={(e) =>
                                                        updateMetadata(
                                                            entry.id,
                                                            "document_source",
                                                            e.target.value,
                                                        )
                                                    }
                                                />
                                                </Field.Root>
                                                <Field.Root>
                                                <Field.Label
                                                    fontSize="xs"
                                                    mb="0"
                                                >
                                                    Focus Area
                                                </Field.Label>
                                                <Input
                                                    size="sm"
                                                    className="input-style"
                                                    value={
                                                        entry.metadata
                                                            .focus_area
                                                    }
                                                    onChange={(e) =>
                                                        updateMetadata(
                                                            entry.id,
                                                            "focus_area",
                                                            e.target.value,
                                                        )
                                                    }
                                                />
                                                </Field.Root>
                                            </VStack>
                                        </Collapsible.Content>
                                    </Collapsible.Root>
                                )}
                        </Box>
                    ))}
                </VStack>
            )}
            {/* Action bar */}
            {fileQueue.length > 0 && (
                <Flex
                    justify="space-between"
                    align="center"
                    wrap="wrap"
                    gap="2"
                >
                    <Text fontSize="xs" color="overlay0">
                        {totalPending} pending · {readyToCommit} ready
                        to commit · {committedCount} committed
                    </Text>
                    <HStack>
                        <Button
                            onClick={extractAll}
                            disabled={
                                !hasPendingOrFailed || isProcessing
                            }
                            loading={isProcessing && extractedCount === 0}
                            loadingText="Extracting..."
                            size="sm"
                            className="orange-button"><CheckIcon />Extract All
                                                    </Button>
                        <Button
                            onClick={commitAll}
                            disabled={
                                readyToCommit === 0 || isProcessing
                            }
                            loading={
                                isProcessing && readyToCommit === 0
                            }
                            loadingText="Committing..."
                            size="sm"
                            className="green-button"><CheckIcon />Commit All
                                                    </Button>
                    </HStack>
                </Flex>
            )}
        </VStack>
    );
};

export default BulkUploader;

// Modal component to confirm delete operations for collections or files.
import { Button, Spinner, Text, Dialog, Portal } from "@chakra-ui/react";

const DeleteModal = ({ isOpen, onClose, onDelete, item }) => {
    const isDeleting = isOpen && !item;
    if (!item) return null; // Don't render if no item to delete

    return (
        <Dialog.Root open={isOpen} onOpenChange={e => {
            if (!e.open) {
                onClose();
            }
        }}>
            <Portal>

                <Dialog.Backdrop />
                <Dialog.Positioner>
                    <Dialog.Content className="modal-style">
                        <Dialog.Header>
                            {item.type === "file" ? "Delete File" : "Delete Collection"}
                        </Dialog.Header>
                        <Dialog.CloseTrigger />
                        <Dialog.Body>
                            {isDeleting ? (
                                <Spinner size="md" />
                            ) : (
                                <Text>
                                    Are you sure you want to delete the{" "}
                                    {item.type === "file" ? "file" : "collection"} "
                                    {item.name}"
                                    {item.type === "file" &&
                                        ` from the collection "${item.collection}"`}
                                    ?
                                </Text>
                            )}
                        </Dialog.Body>
                        <Dialog.Footer>
                            <Button
                                className="red-button"
                                mr={3}
                                onClick={onDelete}
                                disabled={isDeleting}
                            >
                                {isDeleting ? "Deleting..." : "Delete"}
                            </Button>
                            <Button
                                className="green-button"
                                onClick={onClose}
                                disabled={isDeleting}
                            >
                                Cancel
                            </Button>
                        </Dialog.Footer>
                    </Dialog.Content>
                </Dialog.Positioner>

            </Portal>
        </Dialog.Root>
    );
};

export default DeleteModal;

// Component for navigating and managing document collections.
import React, { useState, useEffect } from "react";
import {
    Box,
    Text,
    HStack,
    Flex,
    List,
    Collapsible,
    IconButton,
    Spinner,
} from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import { Tooltip } from "@/components/ui/tooltip";
import {
    ChevronDownIcon,
    ChevronRightIcon,
    EditIcon,
    DeleteIcon,
    DownloadIcon,
} from "../common/icons";
import { FaFolder, FaFolderOpen, FaFile } from "react-icons/fa";
import { MdOutlineFolderCopy } from "react-icons/md";
import { ragApi } from "../../utils/api/ragApi";
import { formatCollectionName } from "../../utils/helpers/formatHelpers";
import { EditDocumentPopover } from "./EditDocumentPopover";

const DocumentExplorer = ({
    isCollapsed,
    setIsCollapsed,
    collections,
    setCollections,
    loading,
    setItemToDelete,
}) => {
    const [expandedCollections, setExpandedCollections] = useState({});

    useEffect(() => {
        if (collections.length > 0 && collections.every((c) => !c.loaded)) {
            setExpandedCollections({});
        }
    }, [collections]);

    const toggleCollection = async (collectionName) => {
        setExpandedCollections((prev) => ({
            ...prev,
            [collectionName]: !prev[collectionName],
        }));
        const collection = collections.find((c) => c.name === collectionName);
        if (collection && !collection.loaded) {
            try {
                const files = await ragApi.fetchCollectionFiles(collectionName);
                setCollections((prev) =>
                    prev.map((c) =>
                        c.name === collectionName
                            ? { ...c, files: files.files, loaded: true }
                            : c,
                    ),
                );
            } catch (error) {
                console.error("Error fetching collection:", error);
                toaster.create({
                    title: "Error",
                    description: "Error fetching collection files",
                    type: "error",
                    duration: 3000,
                });
            }
        }
    };

    const handleRenameCollection = async (oldName, newName) => {
        if (newName) {
            ragApi
                .renameCollection(oldName, newName)
                .then(() => {
                    toaster.create({
                        title: "Success",
                        description: `Successfully renamed to ${newName}`,
                        type: "success",
                        duration: 3000,
                    });
                    // After successful rename, refetch collections
                    const fetchCollections = async () => {
                        try {
                            const updatedCollections =
                                await ragApi.fetchCollections();
                            setCollections(
                                updatedCollections.files.map((name) => ({
                                    name,
                                    files: [],
                                    loaded: false,
                                })),
                            );
                        } catch {
                            toaster.create({
                                title: "Error",
                                description:
                                    "Error fetching updated collection list",
                                type: "error",
                                duration: 3000,
                            });
                        }
                    };
                    fetchCollections();
                })
                .catch((error) => {
                    console.error("Error renaming collection:", error);
                    toaster.create({
                        title: "Error",
                        description: "Failed to rename collection",
                        type: "error",
                        duration: 3000,
                    });
                });
        }
    };

    const handleDownloadPdf = async (collectionName, filename) => {
        try {
            const blob = await ragApi.downloadPdf(collectionName, filename);
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = filename;
            document.body.appendChild(a);
            a.click();
            a.remove();
            window.URL.revokeObjectURL(url);
        } catch (error) {
            console.error("Error downloading PDF:", error);
            toaster.create({
                title: "Error",
                description: "Failed to download PDF",
                type: "error",
                duration: 3000,
            });
        }
    };
    return (
        <Box className="panels-bg" p="4" borderRadius="sm">
            <Flex align="center" justify="space-between">
                <Flex align="center">
                    <IconButton
                        onClick={() => setIsCollapsed(!isCollapsed)}
                        aria-label="Toggle collapse"
                        variant="outline"
                        size="sm"
                        mr="2"
                        className="collapse-toggle"
                    >
                        {isCollapsed ? (
                            <ChevronRightIcon />
                        ) : (
                            <ChevronDownIcon />
                        )}
                    </IconButton>
                    <HStack gap={2}>
                        <MdOutlineFolderCopy size="1.2em" />
                        <Text as="h3">Document Explorer</Text>
                    </HStack>
                </Flex>
            </Flex>
            <Collapsible.Root open={!isCollapsed}>
                <Collapsible.Content>
                    {loading && <Spinner />}
                    {!loading && (
                        <Box mt="4">
                            <List.Root gap={3}>
                                {collections.map((collection) => (
                                    <List.Item
                                        key={collection.name}
                                        borderRadius="sm"
                                        overflow="hidden"
                                    >
                                        <Flex
                                            alignItems="center"
                                            p="2"
                                            className="documentExplorer-style"
                                            _hover={{ bg: "surfaceMuted" }}
                                        >
                                            <Tooltip
                                                content="Toggle collection"
                                                showArrow
                                            >
                                                <IconButton
                                                    onClick={() =>
                                                        toggleCollection(
                                                            collection.name,
                                                        )
                                                    }
                                                    aria-label="Toggle collection"
                                                    variant="ghost"
                                                    size="sm"
                                                    mr="2"
                                                    className="documentExplorer-button"
                                                >
                                                    {expandedCollections[
                                                        collection.name
                                                    ] ? (
                                                        <ChevronDownIcon />
                                                    ) : (
                                                        <ChevronRightIcon />
                                                    )}
                                                </IconButton>
                                            </Tooltip>
                                            <Box
                                                as={
                                                    expandedCollections[
                                                        collection.name
                                                    ]
                                                        ? FaFolderOpen
                                                        : FaFolder
                                                }
                                                mr="2"
                                                color="yellow.500"
                                            />
                                            <Text
                                                fontSize="md"
                                                fontWeight="medium"
                                            >
                                                {formatCollectionName(
                                                    collection.name,
                                                )}
                                            </Text>
                                            <Flex ml="auto">
                                                <Tooltip
                                                    content="Rename collection"
                                                    showArrow
                                                >
                                                    <IconButton
                                                        aria-label="Rename collection"
                                                        onClick={() => {
                                                            const newName =
                                                                prompt(
                                                                    "Enter new name:",
                                                                    collection.name,
                                                                );
                                                            handleRenameCollection(
                                                                collection.name,
                                                                newName,
                                                            );
                                                        }}
                                                        size="sm"
                                                        variant="ghost"
                                                        colorPalette="blue"
                                                    >
                                                        <EditIcon />
                                                    </IconButton>
                                                </Tooltip>
                                                <Tooltip
                                                    content="Delete collection"
                                                    showArrow
                                                >
                                                    <IconButton
                                                        aria-label="Delete collection"
                                                        onClick={() =>
                                                            setItemToDelete({
                                                                type: "collection",
                                                                name: collection.name,
                                                                collection:
                                                                    null,
                                                            })
                                                        }
                                                        size="sm"
                                                        variant="ghost"
                                                        colorPalette="red"
                                                    >
                                                        <DeleteIcon />
                                                    </IconButton>
                                                </Tooltip>
                                            </Flex>
                                        </Flex>
                                        <Collapsible.Root
                                            open={
                                                expandedCollections[
                                                    collection.name
                                                ]
                                            }
                                        >
                                            <Collapsible.Content>
                                                <List.Root
                                                    pl="8"
                                                    py="2"
                                                    className="filelist-style"
                                                >
                                                    {collection.files.length ===
                                                        0 &&
                                                    !collection.loaded ? (
                                                        <List.Item>
                                                            <Spinner
                                                                size="sm"
                                                                mr="2"
                                                            />{" "}
                                                            Loading files...
                                                        </List.Item>
                                                    ) : collection.files
                                                          .length > 0 ? (
                                                        collection.files.map(
                                                            (file, index) => {
                                                                const fileName =
                                                                    typeof file ===
                                                                    "string"
                                                                        ? file
                                                                        : file.filename;
                                                                const fileTitle =
                                                                    typeof file ===
                                                                    "object"
                                                                        ? file.title ||
                                                                          file.filename
                                                                        : file;
                                                                const hasPdf =
                                                                    typeof file ===
                                                                    "object"
                                                                        ? file.has_pdf
                                                                        : false;
                                                                return (
                                                                    <List.Item
                                                                        key={
                                                                            index
                                                                        }
                                                                        display="flex"
                                                                        alignItems="center"
                                                                        py="1"
                                                                    >
                                                                        <Box
                                                                            as={
                                                                                FaFile
                                                                            }
                                                                            mr="2"
                                                                            color="primaryButton"
                                                                        />
                                                                        <Text fontSize="sm">
                                                                            {fileTitle ||
                                                                                fileName}
                                                                        </Text>
                                                                        <Flex
                                                                            ml="auto"
                                                                            alignItems="center"
                                                                        >
                                                                            {typeof file ===
                                                                                "object" && (
                                                                                <EditDocumentPopover
                                                                                    collectionName={
                                                                                        collection.name
                                                                                    }
                                                                                    file={
                                                                                        file
                                                                                    }
                                                                                    onSaved={(
                                                                                        updated,
                                                                                    ) => {
                                                                                        setCollections(
                                                                                            (
                                                                                                prev,
                                                                                            ) =>
                                                                                                prev.map(
                                                                                                    (
                                                                                                        c,
                                                                                                    ) =>
                                                                                                        c.name ===
                                                                                                        collection.name
                                                                                                            ? {
                                                                                                                  ...c,
                                                                                                                  files: c.files.map(
                                                                                                                      (
                                                                                                                          f,
                                                                                                                      ) => {
                                                                                                                          const fn =
                                                                                                                              typeof f ===
                                                                                                                              "string"
                                                                                                                                  ? f
                                                                                                                                  : f.filename;
                                                                                                                          return fn ===
                                                                                                                              updated.filename
                                                                                                                              ? {
                                                                                                                                    ...f,
                                                                                                                                    ...updated,
                                                                                                                                }
                                                                                                                              : f;
                                                                                                                      },
                                                                                                                  ),
                                                                                                              }
                                                                                                            : c,
                                                                                                ),
                                                                                        );
                                                                                    }}
                                                                                />
                                                                            )}
                                                                            {hasPdf && (
                                                                                <Tooltip
                                                                                    content="Download PDF"
                                                                                    showArrow
                                                                                >
                                                                                    <IconButton
                                                                                        aria-label="Download PDF"
                                                                                        onClick={() =>
                                                                                            handleDownloadPdf(
                                                                                                collection.name,
                                                                                                fileName,
                                                                                            )
                                                                                        }
                                                                                        size="xs"
                                                                                        variant="ghost"
                                                                                        colorPalette="blue"
                                                                                        mr="1"
                                                                                    >
                                                                                        <DownloadIcon />
                                                                                    </IconButton>
                                                                                </Tooltip>
                                                                            )}
                                                                            <Tooltip
                                                                                content="Delete file"
                                                                                showArrow
                                                                            >
                                                                                <IconButton
                                                                                    aria-label="Delete file"
                                                                                    onClick={() =>
                                                                                        setItemToDelete(
                                                                                            {
                                                                                                type: "file",
                                                                                                name: fileName,
                                                                                                collection:
                                                                                                    collection.name,
                                                                                            },
                                                                                        )
                                                                                    }
                                                                                    size="xs"
                                                                                    variant="ghost"
                                                                                    colorPalette="red"
                                                                                >
                                                                                    <DeleteIcon />
                                                                                </IconButton>
                                                                            </Tooltip>
                                                                        </Flex>
                                                                    </List.Item>
                                                                );
                                                            },
                                                        )
                                                    ) : (
                                                        <List.Item
                                                            fontSize="sm"
                                                            color="overlay0"
                                                        >
                                                            No files found.
                                                        </List.Item>
                                                    )}
                                                </List.Root>
                                            </Collapsible.Content>
                                        </Collapsible.Root>
                                    </List.Item>
                                ))}
                            </List.Root>
                        </Box>
                    )}
                </Collapsible.Content>
            </Collapsible.Root>
        </Box>
    );
};

export default DocumentExplorer;

