                        variant="outline"
                        size="sm"
                        mr="2"
                        className="collapse-toggle"
                    >
                        {isCollapsed ? (
                            <ChevronRightIcon />
                        ) : (
                            <ChevronDownIcon />
                        )}
                    </IconButton>
                    <FaCog size="1.2em" style={{ marginRight: "5px" }} />
                    <Text as="h3">Model Settings</Text>
                </Flex>
            </Flex>
            <Collapsible.Root open={!isCollapsed}>
                <Collapsible.Content>
                    <VStack gap={4} align="stretch" mt={4}>
                        {/* Inference Type Selection - Desktop (Tauri) only and not in Docker */}
                        {isTauri() && !isDocker && (
                            <Box>
                                <Tooltip content="Choose between running models locally on your machine or connecting to remote API services">
                                    <Text
                                        fontSize="md"
                                        fontWeight="bold"
                                        mb="3"
                                    >
                                        Inference Type
                                    </Text>
                                </Tooltip>
                                <Flex
                                    className="mode-selector"
                                    alignItems="center"
                                    p={1}
                                    width="100%"
                                >
                                    <Box
                                        className="mode-selector-indicator"
                                        left={
                                            isLocalInference
                                                ? "2px"
                                                : "calc(50% - 2px)"
                                        }
                                    />
                                    <Flex
                                        width="full"
                                        position="relative"
                                        zIndex={1}
                                    >
                                        <Tooltip content="Run models directly on your machine using bundled inference engines">
                                            <Button
                                                className={`mode-selector-button ${isLocalInference ? "active" : ""}`}
                                                onClick={() =>
                                                    handleInferenceTypeChange(
                                                        true,
                                                    )
                                                }
                                                disabled={
                                                    !isTauri() &&
                                                    !localStatus?.available
                                                }
                                            >
                                                <FaDesktop />
                                                Local
                                            </Button>
                                        </Tooltip>
                                        <Tooltip content="Connect to external OpenAI/Ollama-compatible APIs">
                                            <Button
                                                className={`mode-selector-button ${!isLocalInference ? "active" : ""}`}
                                                onClick={() =>
                                                    handleInferenceTypeChange(
                                                        false,
                                                    )
                                                }
                                            >
                                                <FaCloud />
                                                Remote
                                            </Button>
                                        </Tooltip>
                                    </Flex>
                                </Flex>
                            </Box>
                        )}

                        {isLocalInference ? (
                            <Tabs.Root
                                variant="enclosed"
                                defaultValue="0"
                            >
                                <Tabs.List>
                                    <Tooltip content="Manage local LLM and Whisper models">
                                        <Tabs.Trigger
                                            className="tab-style"
                                            value="0"
                                        >
                                            <HStack>
                                                <FaDesktop />
                                                <Text>Models</Text>
                                            </HStack>
                                        </Tabs.Trigger>
                                    </Tooltip>
                                    <Tooltip content="Configure external tool servers">
                                        <Tabs.Trigger
                                            className="tab-style"
                                            value="1"
                                        >
                                            <HStack>
                                                <FaPuzzlePiece />
                                                <Text>Tools</Text>
                                            </HStack>
                                        </Tabs.Trigger>
                                    </Tooltip>
                                </Tabs.List>
                                <Tabs.Content
                                    className="floating-main"
                                    value="0"
                                >
                                    <LocalModelManager />
                                </Tabs.Content>
                                <Tabs.Content
                                    className="floating-main"
                                    value="1"
                                >
                                    <ToolsSettingsTab />
                                </Tabs.Content>
                            </Tabs.Root>
                        ) : (
                            <Tabs.Root
                                variant="enclosed"
                                defaultValue="0"
                            >
                                <Tabs.List>
                                    <Tooltip content="Configure speech-to-text service settings">
                                        <Tabs.Trigger
                                            className="tab-style"
                                            value="0"
