                                                    <FaDatabase />
                                                    <Text>RAG</Text>
                                                </HStack>
                                            </Tabs.Trigger>
                                        </Tooltip>
                                    )}
                                    <Tooltip content="Configure external tool servers">
                                        <Tabs.Trigger
                                            className="tab-style"
                                            value="3"
                                        >
                                            <HStack>
                                                <FaPuzzlePiece />
                                                <Text>Tools</Text>
                                            </HStack>
                                        </Tabs.Trigger>
                                    </Tooltip>
                                </Tabs.List>
                                <Tabs.Content
                                    className="floating-main"
                                    value="0"
                                >
                                    <WhisperTab
                                        config={config}
                                        handleConfigChange={handleConfigChange}
                                        whisperModelOptions={
                                            whisperModelOptions
                                        }
                                        whisperModelListAvailable={
                                            whisperModelListAvailable
                                        }
                                        whisperModelsLoading={
                                            whisperModelsLoading
                                        }
                                        urlStatus={urlStatus}
                                    />
                                </Tabs.Content>
                                <Tabs.Content
                                    className="floating-main"
                                    value="1"
                                >
                                    <LlmTab
                                        config={config}
                                        handleConfigChange={handleConfigChange}
                                        modelOptions={modelOptions}
                                        llmModelsLoading={llmModelsLoading}
                                        urlStatus={urlStatus}
                                    />
                                </Tabs.Content>
                                {isRagEnabled() && (
                                    <Tabs.Content
                                        className="floating-main"
                                        value="2"
                                    >
