import { Box, Text, NativeSelect, VStack, HStack, Spinner, Button, Dialog, Portal } from "@chakra-ui/react";
import { Tooltip } from "@/components/ui/tooltip";
import { ReEmbedProgress } from "../common/ReEmbedProgress";
import { useState } from "react";

const RagTab = ({
    config,
    embeddingModelOptions = [],
    llmModelsLoading = false,
    handleReEmbed,
}) => {
    const [isEmbeddingModelModalOpen, setIsEmbeddingModelModalOpen] =
        useState(false);
    const [pendingEmbeddingModel, setPendingEmbeddingModel] = useState(null);
    const [isReEmbedding, setIsReEmbedding] = useState(false);
    const [reEmbedProgress, setReEmbedProgress] = useState(null);

    const handleEmbeddingModelChange = (value) => {
        setPendingEmbeddingModel(value);
        setIsEmbeddingModelModalOpen(true);
    };

    const handleConfirmEmbeddingChange = async () => {
        setIsReEmbedding(true);
        setReEmbedProgress({ percentage: 0 });
        try {
            await handleReEmbed(pendingEmbeddingModel, (event) => {
                if (
                    event.type === "batch_progress" ||
                    event.type === "collection_start"
                ) {
                    setReEmbedProgress({
                        percentage: event.percentage ?? 0,
                        collection_index: event.collection_index ?? 0,
                        total_collections: event.total_collections ?? 0,
                        collection_name: event.collection_name ?? "",
                        chunks_embedded: event.chunks_embedded ?? 0,
                        total_chunks_in_collection:
                            event.total_chunks_in_collection ?? 0,
                    });
                }
            });
            setIsEmbeddingModelModalOpen(false);
            setPendingEmbeddingModel(null);
        } catch (error) {
            console.error("Error changing embedding model:", error);
        } finally {
            setIsReEmbedding(false);
            setReEmbedProgress(null);
        }
    };

    const handleCancelEmbeddingChange = () => {
        setIsEmbeddingModelModalOpen(false);
        setPendingEmbeddingModel(null);
    };

    return (
        <>
            <VStack gap={4} align="stretch">
                <Box>
                    <Text fontSize="md" fontWeight="bold">
                        Knowledge Base (RAG)
                    </Text>
                    <Text fontSize="sm" color="overlay0">
                        Configure the embedding model used for knowledge base
                        searches
                    </Text>
                </Box>

                <Box>
                    <Tooltip content="Model used for generating embeddings for RAG - changing this will re-embed all documents">
                        <Text fontSize="sm" mb="2" fontWeight={"bold"}>
                            Embedding Model
                        </Text>
                    </Tooltip>
                    {llmModelsLoading ? (
                        <HStack gap="2">
                            <Spinner size="sm" />
                            <Text fontSize="sm" color="overlay0">
                                Loading models...
                            </Text>
                        </HStack>
                    ) : (
                        <NativeSelect.Root>
                            <NativeSelect.Field
                                size="sm"
                                value={config?.EMBEDDING_MODEL || ""}
                                onChange={(e) =>
                                    handleEmbeddingModelChange(e.target.value)
                                }
                                placeholder="Select embedding model"
                                className="input-style"
                            >
                                {embeddingModelOptions.map((model) => (
                                    <option key={model} value={model}>
                                        {model}
                                    </option>
                                ))}
                            </NativeSelect.Field>
                            <NativeSelect.Indicator />
                        </NativeSelect.Root>
                    )}
                    <Text fontSize="xs" color="overlay0" mt="1">
                        Available embedding models depend on the LLM endpoint
                        configured in the LLM tab
                    </Text>
                    <Text
                        fontSize="xs"
                        color="secondaryButton"
                        mt="2"
                        fontWeight="medium"
                    >
                        ⚠️ Changing the embedding model will re-embed all
                        documents automatically
                    </Text>
                </Box>
            </VStack>

            <Dialog.Root
                open={isEmbeddingModelModalOpen}
                closeOnInteractOutside={!isReEmbedding}
                closeOnEscape={!isReEmbedding}
                size="md"
                onOpenChange={(e) => {
                    if (!e.open) {
                        (
                            isReEmbedding
                                ? undefined
                                : handleCancelEmbeddingChange
                        )();
                    }
                }}
            >
                <Portal>
                    <Dialog.Backdrop />
                    <Dialog.Positioner>
                        <Dialog.Content className="modal-style">
                            <Dialog.Header>Re-embed Documents</Dialog.Header>
                            <Dialog.Body>
                                {isReEmbedding ? (
                                    <VStack gap={4} align="stretch">
                                        <Text>
                                            Re-embedding documents with the new
                                            model…
                                        </Text>
                                        <ReEmbedProgress
                                            progress={reEmbedProgress}
                                        />
                                    </VStack>
                                ) : (
                                    <>
                                        <Text>
                                            Changing the embedding model will
                                            re-embed all existing document
                                            collections with the new model. Your
                                            documents and collections will be
                                            preserved.
                                        </Text>
                                        <Text mt={4} fontWeight="bold">
                                            Are you sure you want to proceed?
                                        </Text>
                                    </>
                                )}
                            </Dialog.Body>
                            {!isReEmbedding && (
                                <Dialog.Footer>
                                    <Button
                                        className="red-button"
                                        mr={3}
                                        onClick={handleCancelEmbeddingChange}
                                    >
                                        Cancel
                                    </Button>
                                    <Button
                                        className="green-button"
                                        onClick={handleConfirmEmbeddingChange}
                                    >
                                        Confirm Change
                                    </Button>
                                </Dialog.Footer>
                            )}
                        </Dialog.Content>
                    </Dialog.Positioner>
                </Portal>
            </Dialog.Root>
        </>
    );
};

export default RagTab;

import {
    Box,
    Flex,
    HStack,
    IconButton,
    Text,
    Button,
    VStack,
    Badge,
} from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import { AddIcon, DeleteIcon, EditIcon } from "../common/icons";
import { FaFileAlt } from "react-icons/fa";
import { Tooltip } from "@/components/ui/tooltip";
import { useState } from "react";
import TemplateEditor from "../modals/TemplateEditor";
import NewTemplateFromExampleModal from "../modals/NewTemplateFromExampleModal";
import DeleteConfirmationModal from "../modals/DeleteConfirmationModal";
import { templateApi } from "../../utils/api/templateApi";
import { useTemplate } from "../../utils/templates/templateContext";

const DEFAULT_TEMPLATE_KEYS = ["phlox_", "soap_", "progress_"];

const isDefaultTemplate = (templateKey) =>
    DEFAULT_TEMPLATE_KEYS.some((prefix) => templateKey.startsWith(prefix));

const TemplateSettingsPanel = ({ templates, setTemplates }) => {
    const [selectedTemplate, setSelectedTemplate] = useState(null);
    const [selectedTemplateKey, setSelectedTemplateKey] = useState(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isNewTemplate, setIsNewTemplate] = useState(false);
    const [, setIsSaving] = useState(false);

    const [isNewTemplateModalOpen, setIsNewTemplateModalOpen] = useState(false);
    const [exampleNote, setExampleNote] = useState("");
    const [isGeneratingTemplate, setIsGeneratingTemplate] = useState(false);

    const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
    const [templateToDelete, setTemplateToDelete] = useState(null);
    const { deleteTemplate } = useTemplate();

    const handleEditTemplate = (templateKey) => {
        const template = templates.find((t) => t.template_key === templateKey);
        if (template) {
            setSelectedTemplate(template);
            setSelectedTemplateKey(templateKey);
            setIsNewTemplate(false);
            setIsModalOpen(true);
        }
    };

    const handleSaveTemplate = async (_templateKey, _updatedTemplate) => {
        setIsSaving(true);
        try {
            const freshTemplates = await templateApi.fetchTemplates();
            setTemplates(freshTemplates);

            toaster.create({
                title: "Success",
                description: "Template saved successfully",
                type: "success",
                duration: 3000,
            });
        } catch (error) {
            console.error("Failed to save template:", error);
            toaster.create({
                title: "Error",
                description: "Failed to save template",
                type: "error",
                duration: 3000,
            });
        } finally {
            setIsSaving(false);
            setIsModalOpen(false);
        }
    };

    const handleDeleteTemplate = async (templateKey) => {
        try {
            const success = await deleteTemplate(templateKey);
            if (success) {
                const freshTemplates = await templateApi.fetchTemplates();
                setTemplates(freshTemplates);
                setIsDeleteModalOpen(false);
                setTemplateToDelete(null);
            }
        } catch (error) {
            console.error("Error deleting template:", error);
            toaster.create({
                title: "Error",
                description: error.message || "Failed to delete template",
                type: "error",
                duration: 3000,
            });
        }
    };

    const handleNewTemplateFromExample = async () => {
        setIsGeneratingTemplate(true);
        try {
            const newTemplate = await templateApi.generateTemplate(exampleNote);

            const freshTemplates = await templateApi.fetchTemplates();
            setTemplates(freshTemplates);

            setSelectedTemplate(newTemplate);
            setSelectedTemplateKey(newTemplate.template_key);
            setIsNewTemplateModalOpen(false);
            setIsNewTemplate(true);
            setIsModalOpen(true);
        } catch (error) {
            console.error("Error generating template from example:", error);
            toaster.create({
                title: "Error",
                description: "Failed to generate template from example",
                type: "error",
                duration: 3000,
            });
        } finally {
            setIsGeneratingTemplate(false);
            setExampleNote("");
        }
    };

    const sortedTemplates = Array.isArray(templates)
        ? [...templates].sort((a, b) => {
              const isDefaultA = isDefaultTemplate(a.template_key);
              const isDefaultB = isDefaultTemplate(b.template_key);
              if (isDefaultA && !isDefaultB) return -1;
              if (!isDefaultA && isDefaultB) return 1;
              return 0;
          })
        : [];

    return (
        <VStack gap={3} align="stretch">
            <Flex justify="space-between" align="center">
                <Text fontSize="xs" className="pill-box-icons" maxW="60%">
                    Templates control the structure of generated notes. Defaults
                    can be edited but not removed.
                </Text>
                <Button
                    onClick={() => setIsNewTemplateModalOpen(true)}
                    variant="outline"
                    size="sm"
                    className="nav-button"
                ><AddIcon />New Template
                </Button>
            </Flex>

            {sortedTemplates.length === 0 ? (
                <Box
                    p={6}
                    textAlign="center"
                    borderWidth="1px"
                    borderColor="border"
                    borderRadius="md"
                >
                    <FaFileAlt
                        size="1.5em"
                        style={{ opacity: 0.5, marginBottom: "8px" }}
                    />
                    <Text fontSize="sm" className="pill-box-icons">
                        No templates available
                    </Text>
                    <Text fontSize="xs" className="pill-box-icons" mt={1}>
                        Create a template to customize note structure
                    </Text>
                </Box>
            ) : (
                <VStack gap={2} align="stretch">
                    {sortedTemplates.map((template) => {
                        const isDefault = isDefaultTemplate(
                            template.template_key,
                        );
                        return (
                            <Box
                                key={template.template_key}
                                p={3}
                                borderWidth="1px"
                                borderColor="border"
                                borderRadius="md"
                            >
                                <Flex justify="space-between" align="center">
                                    <HStack gap={3}>
                                        <FaFileAlt
                                            style={{ opacity: 0.5 }}
                                        />
                                        <Text fontWeight="bold" fontSize="sm">
                                            {template.template_name}
                                        </Text>
                                        <Badge
                                            colorPalette={
                                                isDefault ? "green" : "gray"
                                            }
                                            fontSize="xs"
                                        >
                                            {isDefault ? "Default" : "Custom"}
                                        </Badge>
                                    </HStack>
                                    <HStack gap={1}>
                                        <Tooltip content="Edit template">
                                            <IconButton
                                                variant="ghost"
                                                size="sm"
                                                aria-label="Edit template"
                                                onClick={() =>
                                                    handleEditTemplate(
                                                        template.template_key,
                                                    )
                                                }
                                            ><EditIcon /></IconButton>
                                        </Tooltip>
                                        {!isDefault && (
                                            <Tooltip content="Delete template">
                                                <IconButton
                                                    variant="ghost"
                                                    size="sm"
                                                    colorPalette="red"
                                                    aria-label="Delete template"
                                                    onClick={() => {
                                                        setTemplateToDelete({
                                                            key: template.template_key,
                                                            name: template.template_name,
                                                        });
                                                        setIsDeleteModalOpen(
                                                            true,
                                                        );
                                                    }}
                                                ><DeleteIcon /></IconButton>
                                            </Tooltip>
                                        )}
                                    </HStack>
                                </Flex>
                            </Box>
                        );
                    })}
                </VStack>
            )}

            <TemplateEditor
                key={selectedTemplateKey || selectedTemplate?.id || "new"}
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                template={selectedTemplate}
                templateKey={selectedTemplateKey}
                onSave={handleSaveTemplate}
                isNewTemplate={isNewTemplate}
            />
            <NewTemplateFromExampleModal
                isOpen={isNewTemplateModalOpen}
                onClose={() => setIsNewTemplateModalOpen(false)}
                onCreate={handleNewTemplateFromExample}
                exampleNote={exampleNote}
                setExampleNote={setExampleNote}
                isLoading={isGeneratingTemplate}
            />
            <DeleteConfirmationModal
                isOpen={isDeleteModalOpen}
                onClose={() => {
                    setIsDeleteModalOpen(false);
                    setTemplateToDelete(null);
                }}
                onConfirm={() => handleDeleteTemplate(templateToDelete?.key)}
                itemName={templateToDelete?.name}
                title="Delete Template"
            />
        </VStack>
    );
};

export default TemplateSettingsPanel;

import { Alert, Badge, Box, Button, Checkbox, Flex, HStack, IconButton, Input, Spacer, Switch, Text, VStack, Field } from "@chakra-ui/react";
import { Tooltip } from '@/components/ui/tooltip';
import {
    FaPuzzlePiece,
    FaPlus,
    FaCheck,
    FaServer,
    FaLock,
} from "react-icons/fa";
import { DeleteIcon } from "../common/icons";
import { useState } from "react";
import { useToolServers } from "../../utils/hooks/useToolServers";

// Built-in tools configuration
const BUILT_IN_TOOLS = [
    {
        name: "transcript_search",
        label: "Transcript Search",
        description: "Search patient transcripts",
        external: false,
    },
    {
        name: "get_relevant_literature",
        label: "Literature Search",
        description: "Local literature database",
        external: false,
    },
    {
        name: "pubmed_search",
        label: "PubMed Search",
        description: "PubMed API (may expose PHI)",
        external: true,
    },
    {
        name: "wiki_search",
        label: "Wikipedia Search",
        description: "Wikipedia API (may expose PHI)",
        external: true,
    },
    {
        name: "get_previous_encounter",
        label: "Previous Encounters",
        description: "Patient history lookup",
        external: false,
    },
];

const ToolsSettingsTab = ({ className }) => {
    const {
        toolServers,
        isLoading,
        testingServerId,
        addServer,
        deleteServer,
        toggleServer,
        toggleSensitiveData,
        testServer,
        toggleBuiltInTool,
        isToolEnabled,
    } = useToolServers();

    const [showAddForm, setShowAddForm] = useState(false);
    const [serverName, setServerName] = useState("");
    const [serverUrl, setServerUrl] = useState("");
    const [allowSensitiveData, setAllowSensitiveData] = useState(false);
    const [nameError, setNameError] = useState("");
    const [urlError, setUrlError] = useState("");

    const validateForm = () => {
        let isValid = true;
        setNameError("");
        setUrlError("");

        if (!serverName.trim()) {
            setNameError("Server name is required");
            isValid = false;
        }

        if (!serverUrl.trim()) {
            setUrlError("Server URL is required");
            isValid = false;
        } else {
            try {
                new URL(serverUrl);
            } catch {
                setUrlError("Please enter a valid URL");
                isValid = false;
            }
        }

        return isValid;
    };

    const handleAddServer = async () => {
        if (!validateForm()) return;
        const ok = await addServer({
            name: serverName,
            url: serverUrl,
            allow_sensitive_data: allowSensitiveData,
        });
        if (ok) {
            setServerName("");
            setServerUrl("");
            setAllowSensitiveData(false);
            setShowAddForm(false);
        }
    };

    return (
        <VStack gap={4} align="stretch" className={className}>
            {/* Warning Banner */}
            <Alert.Root status="warning" borderRadius="md">
                <Alert.Indicator color="secondaryButton" />
                <Alert.Description fontSize="sm">
                    Tool servers may receive sensitive patient information
                    (PHI). Only add servers you trust that comply with your
                    privacy requirements.
                </Alert.Description>
            </Alert.Root>
            {/* Built-in Tools Section */}
            <Box>
                <Flex align="center" mb={2}>
                    <HStack>
                        <FaPuzzlePiece style={{ opacity: 0.7 }} />
                        <Text fontSize="sm" fontWeight="semibold">
                            Built-in Tools
                        </Text>
                    </HStack>
                </Flex>

                <Text fontSize="xs" className="pill-box-icons" mb={2}>
                    Enable or disable built-in tools. External tools (PubMed,
                    Wikipedia) are disabled by default to protect patient
                    privacy.
                </Text>

                <VStack gap={1} align="stretch">
                    {BUILT_IN_TOOLS.map((tool) => (
                        <Box
                            key={tool.name}
                            p={2}
                            borderRadius="md"
                            className="floating-main"
                        >
                            <Flex justify="space-between" align="center">
                                <HStack gap={2} flex="1">
                                    <Box flex="1">
                                        <HStack>
                                            <Text
                                                fontWeight="medium"
                                                fontSize="sm"
                                            >
                                                {tool.label}
                                            </Text>
                                            {tool.external && (
                                                <Tooltip content="External API - may expose PHI">
                                                    <Box>
                                                        <FaLock
                                                            style={{
                                                                opacity: 0.6,
                                                                color: "var(--chakra-colors-secondary-button)",
                                                            }}
                                                        />
                                                    </Box>
                                                </Tooltip>
                                            )}
                                        </HStack>
                                        <Text
                                            fontSize="xs"
                                            className="pill-box-icons"
                                        >
                                            {tool.description}
                                        </Text>
                                    </Box>
                                </HStack>

                                <Switch.Root
                                    checked={isToolEnabled(tool.name)}
                                    onCheckedChange={({ checked }) =>
                                        toggleBuiltInTool(tool.name, checked)
                                    }
                                    size="sm"
                                >
                                    <Switch.HiddenInput />
                                    <Switch.Control>
                                        <Switch.Thumb />
                                    </Switch.Control>
                                </Switch.Root>
                            </Flex>
                        </Box>
                    ))}
                </VStack>
            </Box>
            {/* Tool Servers Header */}
            <Flex align="center">
                <HStack>
                    <FaPuzzlePiece style={{ opacity: 0.7 }} />
                    <Text fontSize="sm" fontWeight="semibold">
                        Tool Servers
                    </Text>
                </HStack>
                <Spacer />
                <Badge colorPalette="purple" fontSize="xs">
                    Streamable HTTP
                </Badge>
            </Flex>
            <Text fontSize="xs" className="pill-box-icons">
                External tool servers provide additional tools for chat and
                chart insights. Servers must implement the Streamable HTTP
                transport.
            </Text>
            {/* Add Server Button */}
            <Button
                onClick={() => setShowAddForm(!showAddForm)}
                variant="outline"
                size="sm"
                className="nav-button"
                alignSelf="flex-start"><FaPlus />Add Server
                            </Button>
            {/* Add Server Form */}
            {showAddForm && (
                <Box p={4} borderRadius="md" className="floating-main">
                    <VStack gap={3}>
                        <Field.Root invalid={!!nameError}>
                            <Field.Label fontSize="xs">Server Name</Field.Label>
                            <Input
                                value={serverName}
                                onChange={(e) => setServerName(e.target.value)}
                                placeholder="My MCP Server"
                                size="sm"
                                className="input-style"
                            />
                            <Field.ErrorText fontSize="xs">
                                {nameError}
                            </Field.ErrorText>
                        </Field.Root>

                        <Field.Root invalid={!!urlError}>
                            <Field.Label fontSize="xs">Server URL</Field.Label>
                            <Input
                                value={serverUrl}
                                onChange={(e) => setServerUrl(e.target.value)}
                                placeholder="http://localhost:3000/tools"
                                size="sm"
                                className="input-style"
                            />
                            <Field.ErrorText fontSize="xs">
                                {urlError}
                            </Field.ErrorText>
                        </Field.Root>

                        <Field.Root>
                            <HStack gap={2}>
                                <Checkbox.Root
                                    onCheckedChange={({ checked }) => setAllowSensitiveData(checked)}
                                    colorPalette="red"
                                    size="sm"
                                    checked={allowSensitiveData}
                                ><Checkbox.HiddenInput /><Checkbox.Control><Checkbox.Indicator /></Checkbox.Control><Checkbox.Label>
                                    <Text fontSize="xs">Allow sensitive data (PHI)</Text>
                                </Checkbox.Label></Checkbox.Root>
                                <Tooltip content="When enabled, patient data will be sent to this server without sanitization. Only enable for fully trusted servers.">
                                    <Box>
                                        <FaLock style={{ opacity: 0.6, color: "var(--chakra-colors-secondary-button)" }} />
                                    </Box>
                                </Tooltip>
                            </HStack>
                            <Text fontSize="xs" className="pill-box-icons" mt={1}>
                                Default: sanitized. Enable only for trusted servers.
                            </Text>
                        </Field.Root>

                        <HStack justify="flex-end" w="100%">
                            <Button
                                onClick={() => setShowAddForm(false)}
                                variant="ghost"
                                size="sm"
                            >
                                Cancel
                            </Button>
                            <Button
                                onClick={handleAddServer}
                                loading={isLoading}
                                colorPalette="green"
                                size="sm"
                            >
                                Add Server
                            </Button>
                        </HStack>
                    </VStack>
                </Box>
            )}
            {/* Server List */}
            {toolServers.length === 0 ? (
                <Box p={6} textAlign="center" className="floating-main">
                    <FaServer
                        size="1.5em"
                        style={{ opacity: 0.5, marginBottom: "8px" }}
                    />
                    <Text fontSize="sm" className="pill-box-icons">
                        No tool servers configured
                    </Text>
                    <Text fontSize="xs" className="pill-box-icons" mt={1}>
                        Add a server to extend available tools
                    </Text>
                </Box>
            ) : (
                <VStack gap={2} align="stretch">
                    {toolServers.map((server) => (
                        <Box
                            key={server.id}
                            p={3}
                            borderRadius="md"
                            className="floating-main"
                        >
                            <Flex justify="space-between" align="center">
                                <HStack gap={3} flex="1">
                                    <FaServer style={{ opacity: 0.5 }} />
                                    <Box flex="1">
                                        <HStack>
                                            <Text
                                                fontWeight="bold"
                                                fontSize="sm"
                                            >
                                                {server.name}
                                            </Text>
                                            <Badge
                                                size="sm"
                                                colorPalette={
                                                    server.enabled
                                                        ? "green"
                                                        : "gray"
                                                }
                                                fontSize="xs"
                                            >
                                                {server.enabled
                                                    ? "Active"
                                                    : "Disabled"}
                                            </Badge>
                                            {server.allow_sensitive_data && (
                                                <Tooltip content="PHI allowed - data sent without sanitization">
                                                    <Badge
                                                        size="sm"
                                                        colorPalette="red"
                                                        fontSize="xs"
                                                    >
                                                        PHI
                                                    </Badge>
                                                </Tooltip>
                                            )}
                                        </HStack>
                                        <Text
                                            fontSize="xs"
                                            className="pill-box-icons"
                                        >
                                            {server.url}
                                        </Text>
                                        {server.description && (
                                            <Text
                                                fontSize="xs"
                                                className="pill-box-icons"
                                                fontStyle="italic"
                                                opacity={0.8}
                                            >
                                                {server.description}
                                            </Text>
                                        )}
                                    </Box>
                                </HStack>

                                <HStack gap={1}>
                                    <Tooltip content="Test connection">
                                        <IconButton
                                            size="sm"
                                            variant="ghost"
                                            onClick={() =>
                                                testServer(server.id)
                                            }
                                            loading={
                                                testingServerId === server.id
                                            }
                                            aria-label="Test connection"><FaCheck /></IconButton>
                                    </Tooltip>

                                    <Tooltip
                                        content={
                                            server.allow_sensitive_data
                                                ? "PHI allowed - click to sanitize"
                                                : "PHI sanitized - click to allow"
                                        }
                                    >
                                        <IconButton
                                            size="sm"
                                            variant="ghost"
                                            colorPalette={server.allow_sensitive_data ? "red" : "gray"}
                                            opacity={server.allow_sensitive_data ? 1 : 0.4}
                                            onClick={() =>
                                                toggleSensitiveData(
                                                    server.id,
                                                    !server.allow_sensitive_data,
                                                )
                                            }
                                            aria-label="Toggle PHI sanitization"><FaLock /></IconButton>
                                    </Tooltip>

                                    <Tooltip
                                        content={
                                            server.enabled
                                                ? "Disable"
                                                : "Enable"
                                        }
                                    >
                                        <Switch.Root
                                            checked={server.enabled}
                                            onCheckedChange={({ checked }) =>
                                                toggleServer(server.id, checked)
                                            }
                                            size="sm"
                                        >
                                            <Switch.HiddenInput />
                                            <Switch.Control>
                                                <Switch.Thumb />
                                            </Switch.Control>
                                        </Switch.Root>
                                    </Tooltip>

                                    <Tooltip content="Delete">
                                        <IconButton
                                            size="sm"
                                            colorPalette="red"
                                            variant="ghost"
                                            onClick={() =>
                                                deleteServer(server.id)
                                            }
                                            aria-label="Delete server"><DeleteIcon /></IconButton>
                                    </Tooltip>
                                </HStack>
                            </Flex>
                        </Box>
                    ))}
                </VStack>
            )}
        </VStack>
    );
};

