import { useState, useCallback, useEffect } from "react";
import { invoke } from "@tauri-apps/api/core";
import { Box, Button, Heading, VStack, Text, Input, Flex, Image, Progress, HStack, Icon, Alert } from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import { FaEye, FaEyeSlash } from "react-icons/fa";
import {
  encryptionApi,
  calculatePassphraseStrength,
} from "../../utils/api/encryptionApi";
import { resetApiConfig, isTauri } from "../../utils/helpers/apiConfig";
import {
  SPLASH_STEPS,
  STEP_TITLES,
  STEP_DESCRIPTIONS,
} from "../common/splash/constants";

const EncryptionSetup = ({ onComplete }) => {

  const [passphrase, setPassphrase] = useState("");
  const [confirmPassphrase, setConfirmPassphrase] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [strength, setStrength] = useState(calculatePassphraseStrength(""));

  // Encryption + 3 splash steps (About You, Templates, AI Models)
  const totalSteps = 4;

  const currentStepIndex = 0; // Encryption is always step 1 (index 0)

  useEffect(() => {
    setStrength(calculatePassphraseStrength(passphrase));
  }, [passphrase]);

  const isValid = useCallback(() => {
    return (
      passphrase.length >= 12 &&
      passphrase === confirmPassphrase &&
      strength.score >= 2
    );
  }, [passphrase, confirmPassphrase, strength]);

  const handleSubmit = useCallback(async () => {
    if (!isValid()) {
      toaster.create({
        title: "Invalid Passphrase",
        description:
          passphrase.length < 12
            ? "Passphrase must be at least 12 characters"
            : passphrase !== confirmPassphrase
              ? "Passphrases do not match"
              : "Please use a stronger passphrase",
        type: "warning",
        duration: 3000,
      });
      return;
    }

    setIsSubmitting(true);
    try {
      // Setup encryption and get hex passphrase
      const hexPassphrase = await encryptionApi.setup(passphrase);

      // Start the server (in warm mode) and then send the passphrase
      try {
        await invoke("start_server_command");
        await invoke("send_passphrase_command", { passphraseHex: hexPassphrase });
        // Reset cached port so we get the new server port
        resetApiConfig();

        // Start llama and whisper services after server is up
        // They will use the ports allocated by the Python server
        try {
          await invoke("start_llama_service");
        } catch (llamaError) {
          console.warn("Llama service did not start (no model downloaded yet):", llamaError);
        }

        try {
          await invoke("start_whisper_service");
        } catch (whisperError) {
          console.warn("Whisper service did not start (no model downloaded yet):", whisperError);
        }

        try {
          await invoke("start_embedding_service");
        } catch (embeddingError) {
          console.warn("Embedding service did not start (no model downloaded yet):", embeddingError);
        }
      } catch (serverError) {
        console.error("Server start failed:", serverError);
        toaster.create({
          title: "Server Warning",
          description: serverError.toString(),
          type: "warning",
          duration: 5000,
        });
      }

      toaster.create({
        title: "Encryption Setup Complete",
        description:
          "Your encryption key has been created. Your data is now secure.",
        type: "success",
        duration: 5000,
      });
      onComplete();
    } catch (error) {
      toaster.create({
        title: "Setup Failed",
        description: error.toString() || "An error occurred during setup",
        type: "error",
        duration: 5000,
      });
    } finally {
      setIsSubmitting(false);
    }
  }, [passphrase, confirmPassphrase, isValid, onComplete]);

  const getStrengthColor = () => {
    if (strength.score <= 1) return "red";
    if (strength.score === 2) return "yellow";
    if (strength.score === 3) return "blue";
    return "green";
  };

  const getStrengthPercent = () => {
    return (strength.score / 4) * 100;
  };


  return (
    <Flex
      align="center"
      justify="center"
      minH="100dvh"
      className="splash-bg"
      px={4}
      py={8}
      position="relative"
    >
      {/* Tauri titlebar drag region - full window width */}
      {isTauri() && (
        <Box
          data-tauri-drag-region
          height="25px"
          position="fixed"
          top="0"
          left="0"
          right="0"
          zIndex="1000"
        />
      )}
      <Box
        className="anim-fade-scale panels-bg splash-panel"
        p={{ base: 6, md: 8 }}
        boxShadow="2xl"
        borderWidth="1px"
        borderColor="surface"
        w={{ base: "100%", sm: "90%", md: "600px" }}
        maxW="600px"
        h="600px"
        maxH="85vh"
        position="relative"
        overflow="hidden"
        display="flex"
        flexDirection="column"
      >
        <Box
          position="absolute"
          top="0"
          left="0"
          right="0"
          height="120px"
          bgGradient="linear(to b, sidebarBackgroundFaint, transparent)"
          zIndex="0"
        />

        <VStack gap={2} position="relative" zIndex={1} flexShrink={0} align="center">
          <Image src="/logo.webp" alt="Phlox" height="40px" width="auto" />
          <Heading as="h2" size="md" color="textPrimary" textAlign="center">
            {STEP_TITLES[SPLASH_STEPS.ENCRYPTION]}
          </Heading>
          <Text fontSize="sm" color="textSecondary" textAlign="center" maxW="420px" lineHeight="1.5">
            {STEP_DESCRIPTIONS[SPLASH_STEPS.ENCRYPTION]}
          </Text>
          <HStack w="100%" justify="space-between" mt={1}>
            <Progress.Root
              value={((currentStepIndex + 1) / totalSteps) * 100}
              colorPalette="blue"
              borderRadius="full"
              size="sm"
              flex="1"
            >
              <Progress.Track>
                <Progress.Range />
              </Progress.Track>
            </Progress.Root>
            <Text fontSize="xs" color="textSecondary" whiteSpace="nowrap" ml={3}>
              {currentStepIndex + 1} of {totalSteps}
            </Text>
          </HStack>
        </VStack>

        {/* Content area — scrolls independently */}
        <Box
          flex="1"
          overflowY="auto"
          minH="340px"
          position="relative"
          zIndex={1}
          className="custom-scrollbar"
        >
          <Alert.Root status="warning" borderRadius="md">
            <Alert.Indicator />
            <Box>
              <Alert.Description>
                If you forget your passphrase, your data cannot be recovered.
              </Alert.Description>
            </Box>
          </Alert.Root>

          <VStack gap={4} align="stretch" mt={4}>
            <Box>
              <Text mb={1} fontSize="sm" fontWeight="500" color="textPrimary">
                Passphrase
              </Text>
              <HStack>
                <Input
                  type={showPassword ? "text" : "password"}
                  placeholder="Enter a secure passphrase (min 12 characters)"
                  value={passphrase}
                  onChange={(e) => setPassphrase(e.target.value)}
                  size="sm"
                  className="input-style"
                />
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => setShowPassword(!showPassword)}
                  aria-label="Toggle password visibility"
                >
                  <Icon asChild>{showPassword ? <FaEyeSlash /> : <FaEye />}</Icon>
                </Button>
              </HStack>

              {passphrase.length > 0 && (
                <Box mt={2}>
                  <HStack justify="space-between" mb={1}>
                    <Text fontSize="xs" color="textSecondary">
                      Strength
                    </Text>
                    <Text
                      fontSize="xs"
                      fontWeight="600"
                      color={getStrengthColor() + ".400"}
                    >
                      {strength.strength}
                    </Text>
                  </HStack>
                  <Progress.Root
                    value={getStrengthPercent()}
                    colorPalette={getStrengthColor()}
                    size="xs"
                    borderRadius="full"
                  >
                    <Progress.Track>
                      <Progress.Range />
                    </Progress.Track>
                  </Progress.Root>
                </Box>
              )}
            </Box>

            <Box>
              <Text mb={1} fontSize="sm" fontWeight="500" color="textPrimary">
                Confirm Passphrase
              </Text>
              <HStack>
                <Input
                  type={showConfirmPassword ? "text" : "password"}
                  placeholder="Confirm your passphrase"
                  value={confirmPassphrase}
                  onChange={(e) => setConfirmPassphrase(e.target.value)}
                  size="sm"
                  className="input-style"
                  onKeyPress={(e) => {
                    if (e.key === "Enter" && isValid()) {
                      handleSubmit();
                    }
                  }}
                />
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                  aria-label="Toggle confirm password visibility"
                >
                  <Icon asChild>
                    {showConfirmPassword ? <FaEyeSlash /> : <FaEye />}
                  </Icon>
                </Button>
              </HStack>

              {confirmPassphrase.length > 0 &&
                passphrase !== confirmPassphrase && (
                  <Text mt={1} fontSize="xs" color="dangerButton">
                    Passphrases do not match
                  </Text>
                )}
            </Box>
          </VStack>
        </Box>

        {/* Footer */}
        <Flex
          justify="flex-end"
          align="center"
          flexShrink={0}
          position="relative"
          zIndex={1}
          pt={4}
        >
          <Button
            onClick={handleSubmit}
            loading={isSubmitting}
            loadingText="Setting up encryption..."
            disabled={!isValid()}
            size="md"
            borderRadius="2xl"
            className="green-button"
            css={{
              fontFamily: '"Space Grotesk", sans-serif',
              fontWeight: "600",
            }}
          >
            Continue
          </Button>
        </Flex>
      </Box>
    </Flex>
  );
};

export default EncryptionSetup;

import { useState, useCallback } from "react";
import { invoke } from "@tauri-apps/api/core";
import { Box, Button, Heading, HStack, VStack, Text, Input, Flex, Image, Icon, Alert } from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import { FaEye, FaEyeSlash } from "react-icons/fa";
import { encryptionApi } from "../../utils/api/encryptionApi";
import { resetApiConfig, isTauri } from "../../utils/helpers/apiConfig";

const EncryptionUnlock = ({ onComplete }) => {

  const [passphrase, setPassphrase] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [attempts, setAttempts] = useState(0);
  const [lastWasPassphrase, setLastWasPassphrase] = useState(false);

  const handleSubmit = useCallback(async () => {
    if (passphrase.length < 1) {
      toaster.create({
        title: "Passphrase Required",
        description: "Please enter your passphrase to unlock.",
        type: "warning",
        duration: 3000,
      });
      return;
    }

    setIsSubmitting(true);
    try {
      // Unlock and get hex passphrase
      const hexPassphrase = await encryptionApi.unlock(passphrase);

      // Ensure the server is warmed up / still alive before sending; pm is idempotent
      try {
        await invoke("start_server_command");
      } catch (warmError) {
        console.warn(
          "start_server_command failed (will surface via send_passphrase):",
          warmError,
        );
      }

      // Send passphrase to the waiting server
      await invoke("send_passphrase_command", { passphraseHex: hexPassphrase });
      // Reset cached port so we get the new server port
      resetApiConfig();

      // Start llama and whisper services after server is up
      // They will use the ports allocated by the Python server
      try {
        await invoke("start_llama_service");
      } catch (llamaError) {
        console.warn(
          "Llama service did not start (no model downloaded yet):",
          llamaError,
        );
      }

      try {
        await invoke("start_whisper_service");
      } catch (whisperError) {
        console.warn(
          "Whisper service did not start (no model downloaded yet):",
          whisperError,
        );
      }

      try {
        await invoke("start_embedding_service");
      } catch (embeddingError) {
        console.warn(
          "Embedding service did not start (no model downloaded yet):",
          embeddingError,
        );
      }

      toaster.create({
        title: "Unlocked",
        description: "Your database has been unlocked successfully.",
        type: "success",
        duration: 3000,
      });
      onComplete();
    } catch (error) {
      const newAttempts = attempts + 1;
      setAttempts(newAttempts);

      const errStr = error?.toString() || "";
      const isPassphraseError =
        /wrong key|wrong encryption key|cannot decrypt database/i.test(errStr);
      setLastWasPassphrase(isPassphraseError);

      toaster.create({
        title: isPassphraseError
          ? "Incorrect Passphrase"
          : "Server Failed to Start",
        description: isPassphraseError
          ? "The passphrase you entered is incorrect. Please try again."
          : "The server couldn't start (this isn't a passphrase problem). Click Unlock to retry — it will re-launch the server.",
        type: "error",
        duration: 6000,
      });

      if (isPassphraseError) {
        setPassphrase("");
      }
    } finally {
      setIsSubmitting(false);
    }
  }, [passphrase, attempts, onComplete]);

  const handleKeyPress = useCallback(
    (e) => {
      if (e.key === "Enter" && passphrase.length > 0) {
        handleSubmit();
      }
    },
    [passphrase, handleSubmit],
  );

  return (
    <Flex
      align="center"
      justify="center"
      minH="100dvh"
      className="splash-bg"
      px={4}
      py={8}
      position="relative"
    >
      {/* Tauri titlebar drag region - full window width */}
      {isTauri() && (
        <Box
          data-tauri-drag-region
          height="25px"
          position="fixed"
          top="0"
          left="0"
          right="0"
          zIndex="1000"
        />
      )}
      <Box
        className="anim-fade-slide-up panels-bg splash-panel"
        p={{ base: 6, md: 8 }}
        borderRadius="2xl"
        boxShadow="2xl"
        border={`1px solid ${"surface"}`}
        w={{ base: "100%", sm: "90%", md: "450px" }}
        maxW="450px"
        position="relative"
        overflow="hidden"
      >
        <Box
          position="absolute"
          top="0"
          left="0"
          right="0"
          height="120px"
          bgGradient={`linear(to b, "sidebarBackgroundFaint", transparent)`}
          borderRadius="2xl"
          zIndex="0"
        />

        <VStack gap={6} align="stretch" position="relative" zIndex="1">
          <Flex
            className="anim-fade-slide-up"
            css={{ animationDelay: "80ms" }}
            direction="column"
            align="center"
            mb={2}
          >
            <Image src="/logo.webp" alt="Phlox Logo" width="60px" mb={3} />
            <Heading
              as="h1"
              textAlign="center"
              color={"textPrimary"}
              css={{
                fontFamily: '"Space Grotesk", sans-serif',
                fontSize: ["1.5rem", "1.75rem"],
                fontWeight: "700",
                lineHeight: "1.2",
                marginBottom: "0.5rem"
              }}
            >
              Unlock Your Data
            </Heading>
            <Text
              textAlign="center"
              fontSize="sm"
              color={"textSecondary"}
              maxW="350px"
              lineHeight="1.6"
            >
              Enter your passphrase to decrypt and access your patient data.
            </Text>
          </Flex>

          {attempts > 0 && lastWasPassphrase && (
            <Alert.Root status="warning" borderRadius="md" fontSize="sm">
              <Alert.Indicator />
              <Text fontSize="xs">
                Incorrect passphrase. Please try again. ({attempts} attempt
                {attempts > 1 ? "s" : ""})
              </Text>
            </Alert.Root>
          )}

          <VStack gap={4} align="stretch">
            <Box>
              <Text
                mb={1}
                fontSize="sm"
                fontWeight="500"
                color={"textPrimary"}
              >
                Passphrase
              </Text>
              <HStack>
                <Input
                  type={showPassword ? "text" : "password"}
                  placeholder="Enter your passphrase"
                  value={passphrase}
                  onChange={(e) => setPassphrase(e.target.value)}
                  onKeyPress={handleKeyPress}
                  size="md"
                  fontWeight="400"
                  autoFocus
                  borderRadius="lg"
                  bg={"surface"}
                  border={`1px solid ${"border"}`}
                  color={"textPrimary"}
                  _placeholder={{ color: "textSecondary" }}
                  _focus={{
                    borderColor: "accent",
                    boxShadow: `0 0 0 1px ${"accent"}`,
                  }}
                />
                <Button
                  size="md"
                  variant="ghost"
                  onClick={() => setShowPassword(!showPassword)}
                  aria-label="Toggle password visibility"
                >
                  <Icon as={showPassword ? FaEyeSlash : FaEye} />
                </Button>
              </HStack>
            </Box>
          </VStack>

          <Button
            onClick={handleSubmit}
            loading={isSubmitting}
            loadingText="Unlocking..."
            disabled={passphrase.length < 1}
            borderRadius="2xl"
            size="lg"
            className="green-button"
            css={{
              fontFamily: '"Space Grotesk", sans-serif',
              fontWeight: "600"
            }}
            mt={2}
          >
            Unlock
          </Button>
        </VStack>
      </Box>
    </Flex>
  );
};

export default EncryptionUnlock;

import { useState, useEffect, useRef } from "react";
import { Box, Button, Heading, VStack, Text, Flex, Spinner, Icon } from "@chakra-ui/react";
import { FaServer } from "react-icons/fa";
import { settingsApi } from "../../utils/api/settingsApi";
import { isTauri } from "../../utils/helpers/apiConfig";

const LOADING_MESSAGES = [
  "Reticulating splines...",
  "Initializing quip database...",
  "Herding cats...",
  "Warming up the hamsters...",
  "Calculating escape velocity...",
  "Decrypting the arc of the covenant...",
  "Consulting the oracle...",
  "Synergizing our core competencies...",
  "Aligning our chakras...",
  "Loading next experience point...",
  "Polishing the bits...",
  "Defragmenting the ether...",
  "Convincing the AI to cooperate...",
  "Applying coffee to the problem...",
  "Downloading more RAM...",
];

const POLL_INTERVAL = 2000; // ms - increased to reduce CPU load
const TIMEOUT = 60000; // 60 seconds - increased for slower systems

const ServerStartupLoader = ({ onReady, onError }) => {

  const [messageIndex, setMessageIndex] = useState(0);
  const [isTimedOut, setIsTimedOut] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [shouldPoll, setShouldPoll] = useState(true);

  // Store callbacks and state in refs to avoid dependency issues
  const onReadyRef = useRef(onReady);
  const onErrorRef = useRef(onError);
  const shouldPollRef = useRef(shouldPoll);
  const isTimedOutRef = useRef(isTimedOut);

  // Keep refs in sync with state
  useEffect(() => {
    onReadyRef.current = onReady;
    onErrorRef.current = onError;
    shouldPollRef.current = shouldPoll;
    isTimedOutRef.current = isTimedOut;
  }, [onReady, onError, shouldPoll, isTimedOut]);

  // Single consolidated useEffect for all intervals
  // Note: We track shouldPoll/isTimedOut inside the interval callbacks
  // rather than as dependencies to prevent interval recreation
  useEffect(() => {
    if (!shouldPoll) return;

    let elapsedInterval, pollInterval, messageInterval, timeoutId;

    // Update elapsed time
    elapsedInterval = setInterval(() => {
      setElapsed((prev) => prev + POLL_INTERVAL);
    }, POLL_INTERVAL);

    // Poll server status - inline to avoid dependency issues
    const pollServerStatusAsync = async () => {
      // Check refs instead of state to avoid stale closures
      if (shouldPollRef.current && !isTimedOutRef.current) {
        try {
          await settingsApi.fetchServerStatus(AbortSignal.timeout(5000));
          shouldPollRef.current = false;
          setShouldPoll(false);
          onReadyRef.current();
        } catch {
          // Server not ready yet, continue polling
        }
      }
    };

    // Initial poll
    pollServerStatusAsync();

    // Set up polling interval
    pollInterval = setInterval(pollServerStatusAsync, POLL_INTERVAL);

    // Cycle loading messages every 2 seconds
    messageInterval = setInterval(() => {
      setMessageIndex((prev) => (prev + 1) % LOADING_MESSAGES.length);
    }, 2000);

    // Timeout after 30 seconds
    timeoutId = setTimeout(() => {
      shouldPollRef.current = false;
      setShouldPoll(false);
      setIsTimedOut(true);
      onErrorRef.current(new Error("Server startup timed out"));
    }, TIMEOUT);

    // Cleanup ALL intervals
    return () => {
      clearInterval(elapsedInterval);
      clearInterval(pollInterval);
      clearInterval(messageInterval);
      clearTimeout(timeoutId);
    };

  }, [shouldPoll]);

  const handleRetry = () => {
    setIsTimedOut(false);
    setElapsed(0);
    setShouldPoll(true);
  };

  if (isTimedOut) {
    return (
      <Flex
        align="center"
        justify="center"
        minH="100dvh"
        className="splash-bg"
        px={4}
        py={8}
        position="relative"
      >
        {/* Tauri titlebar drag region - full window width */}
        {isTauri() && (
          <Box
            data-tauri-drag-region
            height="25px"
            position="fixed"
            top="0"
            left="0"
            right="0"
            zIndex="1000"
          />
        )}
        <Box
          className="anim-fade-slide-up panels-bg splash-panel"
          p={8}
          borderRadius="2xl"
          boxShadow="2xl"
          border={`1px solid ${"surface"}`}
          w="100%"
          maxW="450px"
          textAlign="center"
        >
          <VStack gap={6}>
            <Icon boxSize={12} color="dangerButton" asChild><FaServer /></Icon>
            <Heading
              as="h1"
              color={"textPrimary"}
              css={{
                fontFamily: '"Space Grotesk", sans-serif',
                fontSize: "1.5rem",
                fontWeight: "700"
              }}
            >
              Server Taking Too Long
            </Heading>
            <Text color={"textSecondary"}>
              The server is taking longer than expected to start. This might be
              due to system resources or other factors.
            </Text>
            <Text color={"textSecondary"} fontSize="sm">
              Waited {Math.floor(elapsed / 1000)} seconds
            </Text>
            <Button
              onClick={handleRetry}
              size="lg"
              className="green-button"
              css={{
