        extractedDocData,
        replacedFields,
        docFileName,
        setDocFileName,
        handleDocumentComplete,
        toggleDocumentField,
        resetDocumentState,
    } = useDocumentExtraction({ patient, setPatient, setIsModified });

    const requiredDemographicsMet = areRequiredDemographicsMet(patient);

    const { open, toggle, close, closeAll, isOpen } = useActivePanel();

    const letter = useLetterOrchestration({
        patient,
        setIsModified: setIsLetterModified,
        onResetLetter,
        openLetter: () => open("letter"),
        toast,
    });

    // Scribe hook for recording controls
    const scribeControls = useScribe({
        name: patient?.name,
        dob: patient?.dob,
        gender: patient?.gender,
        template: currentTemplate,
        noteId: patient?.id,
        handleTranscriptionComplete: (data) =>
            handleTranscriptionComplete(data),
        setLoading,
        onSendStart: () => close("transcription"),
    });

    const scribeConsent = useScribeConsent({
        urNumber: patient?.ur_number,
        isAmbient: scribeControls.isAmbient,
        requiresConsentConfig: scribeControls.requireConsent,
        requiredDemographicsMet,
        startRecording: scribeControls.startRecording,
        onRequireDemographics: onOpenDemographics,
    });

    const wrapUp = useWrapUp({
        patient,
        savePatientCore,
        resetTranscription,
        setIsSummaryModified,
        resetSearchFlow: searchFlow.reset,
        onOpenNewNoteModal,
        refreshSidebar,
        selectedDate,
        toast,
        hasTranscriptionOccurred,
        initialTranscriptionContent,
    });

    const textToCopy =
        patient && currentTemplate?.fields
            ? currentTemplate.fields
                  .map(
                      (field) =>
                          `${field.field_name}:\n${
                              patient.template_data?.[field.field_key] || ""
                          }`,
                  )
                  .join("\n\n")
            : "";

    const { onCopy: handleCopy, hasCopied: recentlyCopied } = useClipboard(
        textToCopy,
        { format: "text/plain" },
    );

    useEffect(() => {
        // Reset component states when patient changes.
        // (chat is self-reset by Chat.jsx via internal effect on patientData?.id)
        summary.setIsCollapsed(false);
        closeAll();
        resetDocumentState();
        // eslint-disable-next-line react-hooks/exhaustive-deps -- summary/closeAll/resetDocumentState come from hooks that return fresh object literals each render; this effect intentionally fires only on patient/template/isNewPatient changes
    }, [patient?.id, currentTemplate, isNewPatient]);

    useEffect(() => {
        toaster.remove();
    }, []);

    const handleTranscriptionComplete = (data, triggerResize = false) => {
        const isRestoration = data.isRestoration === true;
        previousTranscriptionRef.current = patient?.raw_transcription;

        if (
            !hasTranscriptionOccurred &&
            data.fields &&
            Object.keys(data.fields).length > 0 &&
            !isRestoration
        ) {
            captureTranscription(data.fields);
        }

        handleProcessingComplete(data, {
            setLoading,
            setters: {
                template_data: (_value) => {
                    setPatient((prev) => ({
                        ...prev,
                        template_data: {
                            ...prev.template_data,
                            ...data.fields,
                        },
                    }));
                },
                rawTranscription: (_value) =>
                    setPatient((prev) => ({
                        ...prev,
                        raw_transcription: data.rawTranscription,
                    })),
                transcriptionDuration: (_value) =>
                    setPatient((prev) => ({
                        ...prev,
                        transcription_duration: data.transcriptionDuration,
                    })),
                processDuration: (_value) =>
                    setPatient((prev) => ({
                        ...prev,
                        process_duration: data.processDuration,
                    })),
            },
            setIsSourceCollapsed: () => {},
            setIsSummaryCollapsed: () => summary.setIsCollapsed(false),
            triggerResize,
            summaryRef,
        });
    };

    const handleSavePatientData = async (e) => {
        e.preventDefault();
        setSaveLoading(true);
        try {
            if (location.pathname === "/new-note") {
                const savedPatient = await savePatient(
                    refreshSidebar,
                    selectedDate,
                    toast,
                    hasTranscriptionOccurred
                        ? initialTranscriptionContent
                        : null,
                );
                if (savedPatient?.id) {
                    setIsSummaryModified(false);
                    resetTranscription();
                    navigate(`/note/${savedPatient.id}`);
                }
            } else {
                await savePatient(
                    refreshSidebar,
                    selectedDate,
                    toast,
                    hasTranscriptionOccurred
                        ? initialTranscriptionContent
                        : null,
                );
                setIsSummaryModified(false);
                resetTranscription();
            }
        } finally {
            setSaveLoading(false);
        }
    };

    const handleDemographicsSave = async (updatedPatient) => {
        setInitialPatient(updatedPatient);
        if (!updatedPatient.id) return;
        await patientApi.savePatientData(
            { patientData: updatedPatient },
            toast,
            refreshSidebar,
        );
    };

    const handleConfirmCandidate = (candidate) =>
        searchFlow.handleConfirmCandidate(
            candidate,
            selectedDate,
            loadCandidate,
        );

    // Functions for the Floating Action Menu
    const handleOpenLetter = () => toggle("letter");
    const handleOpenChat = () => toggle("chat");
    const handleOpenReasoning = () => toggle("reasoning");
    const handleOpenTranscription = () => toggle("transcription");
    const handleOpenDocument = () => toggle("document");
    const handleOpenPreviousVisit = () => {
        if (!isOpen("previous-visit")) {
            setHasViewedPreviousVisit(true);
        }
        toggle("previous-visit");
    };

    // Handle when reasoning is generated - update patient state for red dot indicator
    const handleReasoningGenerated = (newReasoning) => {
        setPatient((prev) => ({
            ...prev,
            reasoning_output: newReasoning,
        }));
    };

    // Check if reasoning has critical items
    const hasCriticalReasoning = useMemo(() => {
        if (!patient?.reasoning_output) return false;
        const r = patient.reasoning_output;
        const allItems = [
            ...(r.differentials || []),
            ...(r.investigations || []),
            ...(r.clinical_considerations || []),
        ];
        return allItems.some((item) => item.critical === true);
    }, [patient?.reasoning_output]);

    // Show red dot for previous visit if summary exists and hasn't been viewed
    const showPreviousVisitDot =
        Boolean(patient?.previous_visit_summary) && !hasViewedPreviousVisit;

    if (!patient) {
        return (
            <Center h="100dvh">
                <Spinner size="xl" />
            </Center>
        );
    }

    if (searchFlow.showStartCard) {
        return (
            <NewNoteStartCard
                onFind={searchFlow.handleSearch}
                onConfirmCandidate={handleConfirmCandidate}
                onNewPatient={() => {
                    searchFlow.dismissStartCard();
                    onOpenDemographics();
                }}
                isSearchLoading={searchFlow.isSearchLoading}
            />
        );
    }

    return (
        <Box
            px={[2, 4, 5]}
            pt={[1, 2, 3]}
            pb={[1, 2, 3]}
            borderRadius="sm"
            w="100%"
        >
            <VStack gap={[3, 4, 5]} align="stretch">
                <PatientInfoBar patient={patient} onEdit={onOpenDemographics} />

                <Summary
                    ref={summaryRef}
                    isSummaryCollapsed={summary.isCollapsed}
                    patient={patient}
                    setPatient={setPatient}
                    handleGenerateLetterClick={letter.handleGenerateLetterClick}
                    handleSavePatientData={handleSavePatientData}
                    onWrapUp={wrapUp.openWrapUp}
                    saveLoading={saveLoading}
                    wrapUpLoading={wrapUp.wrapUpLoading}
                    setIsModified={setIsSummaryModified}
                    selectTemplate={selectTemplate}
                    isNewPatient={isNewPatient}
                    isSearchedPatient={searchFlow.isSearchedPatient}
                    onCopy={handleCopy}
                    recentlyCopied={recentlyCopied}
                    isEncounterSaved={Boolean(patient?.id)}
                />

                <WrapUpModal
                    key={String(wrapUp.isWrapUpOpen)}
                    isOpen={wrapUp.isWrapUpOpen}
                    onClose={wrapUp.closeWrapUp}
                    onConfirm={wrapUp.confirmWrapUp}
                    planText={patient?.template_data?.plan || ""}
                    submitting={wrapUp.wrapUpLoading}
                />

                <DemographicsModal
                    isOpen={isDemographicsOpen}
                    onClose={onCloseDemographics}
                    patient={patient}
                    setPatient={setPatient}
                    onSave={handleDemographicsSave}
                />

                <ScribeConsentModal
                    isOpen={scribeConsent.isConsentOpen}
                    onClose={scribeConsent.onCloseConsent}
                    onConsent={scribeConsent.handleConsentGranted}
                    onDecline={scribeConsent.handleConsentDeclined}
                    hasDeclined={scribeConsent.hasDeclined}
                    declinedDate={
                        scribeConsent.consent?.scribe_consent_declined_at
                    }
                    patientName={patient?.name}
                />

                <Letter
                    isOpen={isOpen("letter")}
                    onClose={() => close("letter")}
                    finalCorrespondence={letter.finalCorrespondence}
                    handleSaveLetter={letter.handleLetterSave}
                    setFinalCorrespondence={letter.setFinalCorrespondence}
                    handleRefineLetter={letter.handleRefineLetter}
                    loading={letter.loading}
                    handleGenerateLetterClick={letter.handleGenerateLetterClick}
                    setIsModified={letter.setIsModified}
                    patient={patient}
                    setLoading={setLoading}
                />

                <Chat
                    isOpen={isOpen("chat")}
                    onClose={() => close("chat")}
                    patientData={patient}
                    currentTemplate={currentTemplate}
                    rawTranscription={patient.raw_transcription}
                />

                <ReasoningPanel
                    isOpen={isOpen("reasoning")}
                    noteId={patient?.id}
                    initialReasoning={patient?.reasoning_output}
                    onReasoningGenerated={handleReasoningGenerated}
                />
            </VStack>
            {/* Scribe Pill Box - centered at bottom */}
            <ScribePillBox
                isRecording={scribeControls.isRecording}
                isPaused={scribeControls.isPaused}
                onStart={scribeControls.startRecording}
                onPause={scribeControls.pauseRecording}
                onResume={scribeControls.resumeRecording}
                onSend={scribeControls.stopAndSendRecording}
                onReset={scribeControls.resetRecording}
                isLoading={scribeControls.isLoading}
                isAmbient={scribeControls.isAmbient}
                onModeToggle={scribeControls.toggleAmbientMode}
                onOpenTranscription={handleOpenTranscription}
                isTranscriptionOpen={isOpen("transcription")}
                hasRawTranscription={!!patient.raw_transcription}
                onAudioDrop={scribeControls.handleAudioDrop}
                canRecord={scribeConsent.canRecord}
                onBlockedRecord={scribeConsent.handleBlockedRecord}
                sendError={scribeControls.sendError}
                onRetry={scribeControls.retrySend}
                onDownload={scribeControls.downloadLastRecording}
                onDismiss={scribeControls.dismissSendError}
            />
            {/* Floating Action Menu - always expanded on right side */}
            <FloatingActionMenu
                onOpenChat={handleOpenChat}
                onOpenLetter={handleOpenLetter}
                onOpenReasoning={handleOpenReasoning}
                onOpenDocument={handleOpenDocument}
                onOpenPreviousVisit={handleOpenPreviousVisit}
                isChatOpen={isOpen("chat")}
                isLetterOpen={isOpen("letter")}
                isReasoningOpen={isOpen("reasoning")}
                isDocumentOpen={isOpen("document")}
                isPreviousVisitOpen={isOpen("previous-visit")}
                hasCriticalReasoning={hasCriticalReasoning}
                hasPreviousVisitSummary={Boolean(
                    patient?.previous_visit_summary,
                )}
                showPreviousVisitDot={showPreviousVisitDot}
                isEncounterSaved={Boolean(patient?.id)}
            />
            {/* Transcription Panel */}
            <TranscriptionPanel
                isOpen={isOpen("transcription")}
                onClose={() => close("transcription")}
                rawTranscription={patient.raw_transcription}
                transcriptionDuration={patient.transcription_duration}
                processDuration={patient.process_duration}
                onReprocess={handleTranscriptionComplete}
                isAmbient={scribeControls.isAmbient}
                name={patient.name}
                gender={patient.gender}
                dob={patient.dob}
                templateKey={currentTemplate?.template_key}
                noteId={patient?.id}
            />
            {/* Document Panel */}
            <DocumentPanel
                isOpen={isOpen("document")}
                handleDocumentComplete={handleDocumentComplete}
                toggleDocumentField={toggleDocumentField}
                replacedFields={replacedFields}
                extractedDocData={extractedDocData}
                resetDocumentState={resetDocumentState}
                name={patient.name}
                dob={patient.dob}
                gender={patient.gender}
                setLoading={setLoading}
                template={currentTemplate}
                docFileName={docFileName}
                setDocFileName={setDocFileName}
            />
            {/* Previous Visit Panel */}
            <PreviousVisitPanel
                isOpen={isOpen("previous-visit")}
                previousVisitSummary={patient.previous_visit_summary}
                previousVisitTemplateData={patient.previous_visit_template_data}
                previousVisitTemplateKey={patient.previous_visit_template_key}
                previousVisitEncounterDate={
                    patient.previous_visit_encounter_date
                }
                templates={templates}
            />
        </Box>
    );
};

export default PatientDetails;

// Page component for document management (upload, explore, and PDF form templates).
import React from "react";
import { Box, Text, HStack, Tabs } from "@chakra-ui/react";
import { FaBook, FaFileAlt } from "react-icons/fa";
import { isRagEnabled, isPdfFormsEnabled } from "../utils/helpers/featureFlags";
import { useRagDocuments } from "../utils/hooks/useRagDocuments";
import { usePdfForms } from "../utils/hooks/usePdfForms";
import DeleteModal from "../components/rag/DeleteModal";
import KnowledgeBasePanel from "../components/rag/KnowledgeBasePanel";
import FormTemplatesPanel from "../components/pdf-forms/FormTemplatesPanel";
import UploadTemplateModal from "../components/pdf-forms/UploadTemplateModal";
import ReplacePdfModal from "../components/pdf-forms/ReplacePdfModal";
import FillFormModal from "../components/pdf-forms/FillFormModal";

const Rag = () => {
  const rag = useRagDocuments();
  const forms = usePdfForms();

  const ragEnabled = isRagEnabled();
  const formsEnabled = isPdfFormsEnabled();
  const showTabs = ragEnabled && formsEnabled;

  const knowledgeBaseProps = {
    collapseExplorer: rag.collapseExplorer,
    collapseUploader: rag.collapseUploader,
    collections: rag.collections,
    setCollections: rag.setCollections,
    loading: rag.loading,
    setItemToDelete: rag.setItemToDelete,
  };

  const formTemplatesProps = {
    templates: forms.templates,
    templatesLoading: forms.templatesLoading,
    selectedTemplate: forms.selectedTemplate,
    fields: forms.fields,
    selectedField: forms.selectedField,
    selectedFieldId: forms.selectedFieldId,
    saving: forms.saving,
    isDrawingMode: forms.isDrawingMode,
    activeFieldType: forms.activeFieldType,
    visionCapable: forms.visionCapable,
    detecting: forms.detecting,
    onSetDrawingMode: forms.setIsDrawingMode,
    onSetFieldType: forms.setActiveFieldType,
    onAutoDetect: forms.handleAutoDetectFields,
    onOpenUpload: () => forms.setShowUploadModal(true),
    onReplaceTemplate: forms.handleOpenReplace,
    onSelectTemplate: forms.handleTemplateSelected,
    onDeleteTemplate: forms.handleTemplateDeleted,
    onFieldsChange: forms.setFields,
    onSelectField: forms.setSelectedFieldId,
    onUpdateField: forms.handleUpdateField,
    onDeleteField: forms.handleDeleteField,
    onSaveFields: forms.handleSaveFields,
  };

  return (
    <>
      <Box p="5" w="100%">
        <Text as="h2" mb="4">
          Documents
        </Text>

        <Box p={[2, 3, 4]} borderRadius="sm" className="panels-bg">
          {showTabs ? (
            <Tabs.Root variant='enclosed' defaultValue="0">
              <Tabs.List>
                <Tabs.Trigger className="tab-style" value="0">
                  <HStack gap="1">
                    <FaBook size="0.85em" />
                    <Text>Knowledge Base</Text>
                  </HStack>
                </Tabs.Trigger>
                <Tabs.Trigger className="tab-style" value="1">
                  <HStack gap="1">
                    <FaFileAlt size="0.85em" />
                    <Text>Form Templates</Text>
                  </HStack>
                </Tabs.Trigger>
              </Tabs.List>
              <Tabs.Content className="floating-main" px="4" py="3" value="0">
                <KnowledgeBasePanel {...knowledgeBaseProps} />
              </Tabs.Content>
              <Tabs.Content className="floating-main" px="4" py="3" value="1">
                <FormTemplatesPanel {...formTemplatesProps} />
              </Tabs.Content>
            </Tabs.Root>
          ) : formsEnabled ? (
            <FormTemplatesPanel {...formTemplatesProps} />
          ) : ragEnabled ? (
            <KnowledgeBasePanel {...knowledgeBaseProps} />
          ) : null}
        </Box>
      </Box>
      {ragEnabled && (
        <DeleteModal
          isOpen={!!rag.itemToDelete}
          onClose={() => rag.setItemToDelete(null)}
          onDelete={rag.handleDelete}
          item={rag.itemToDelete}
        />
      )}
      {formsEnabled && (
        <>
          <UploadTemplateModal
            isOpen={forms.showUploadModal}
            onClose={() => forms.setShowUploadModal(false)}
            onCreated={forms.handleTemplateCreated}
          />
          {forms.selectedTemplate && (
            <ReplacePdfModal
              isOpen={forms.showReplaceModal}
              onClose={() => forms.setShowReplaceModal(false)}
              template={forms.selectedTemplate}
              onReplaced={forms.handlePdfReplaced}
            />
          )}
          {forms.selectedTemplate && (
            <FillFormModal
              isOpen={forms.showFillModal}
              onClose={() => forms.setShowFillModal(false)}
              template={forms.selectedTemplate}
            />
          )}
        </>
      )}
    </>
  );
};

export default Rag;

// Page component for configuring application settings.
import {
    Box,
    Text,
    VStack,
    Center,
    Spinner,
} from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import { useState, useEffect, useCallback, useRef } from "react";
import { settingsService } from "../utils/settings/settingsUtils";
import { settingsApi } from "../utils/api/settingsApi";
import { settingsHelpers } from "../utils/helpers/settingsHelpers";
import { syncLanguage } from "../i18n";
import { UI_LANGUAGES } from "../utils/i18n/languages";
import UserSettingsPanel from "../components/settings/UserSettingsPanel";
import ModelSettingsPanel from "../components/settings/ModelSettingsPanel";
import PromptSettingsPanel from "../components/settings/PromptSettingsPanel";
import { SPECIALTIES } from "../utils/constants";
import { templateService } from "../utils/services/templateService";
import { localModelApi } from "../utils/api/localModelApi";
import { useDebounce } from "../utils/hooks/useDebounce";
import { useAutosave } from "../utils/hooks/useAutosave";

const Settings = () => {
    const [userSettings, setUserSettings] = useState({
        name: "",
        specialty: "",
        quick_chat_1_title: "Review my plan",
        quick_chat_1_prompt: "Review my plan",
        quick_chat_2_title: "Additional points to review",
        quick_chat_2_prompt: "Additional points to review",
        quick_chat_3_title: "Other conditions worth reviewing",
        quick_chat_3_prompt: "Other conditions worth reviewing",
    });
    const [prompts, setPrompts] = useState(null);
    const [options, setOptions] = useState({
        general: { num_ctx: 0 },
        secondary: { num_ctx: 0 },
        letter: { temperature: 0 },
    });
    const [templates, setTemplates] = useState({});
    const [letterTemplates, setLetterTemplates] = useState([]);

    const [config, setConfig] = useState(null);
    const [coreLoading, setCoreLoading] = useState(true);
    const [showSpinner, setShowSpinner] = useState(false);
    const [llmModelsLoading, setLlmModelsLoading] = useState(false);
    const [whisperModelsLoading, setWhisperModelsLoading] = useState(false);
    const [modelOptions, setModelOptions] = useState([]);
    const [whisperModelOptions, setWhisperModelOptions] = useState([]);
    const [whisperModelListAvailable, setWhisperModelListAvailable] =
        useState(false);

    const [urlStatus, setUrlStatus] = useState({
        whisper: false,
        llm: false,
    });
    const [collapseStates, setCollapseStates] = useState({
        userSettings: false,
        modelSettings: true,
        promptSettings: true,
        localModels: true,
    });

    // Track default_template separately — it persists via a different endpoint
    const lastDefaultTemplateRef = useRef(null);

    const fetchCoreSettings = useCallback(async () => {
        try {
            setCoreLoading(true);
            const configData = await settingsApi.fetchConfig();
            setConfig(configData);

            // Letter templates fetched here instead of a separate useEffect
            const [letterResponse, prompts, optionsData, userSettings, templates] = await Promise.all([
                settingsService.fetchLetterTemplates().catch((error) => {
                    console.error(
                        "Failed to fetch letter templates:",
                        error,
                    );
                    return { templates: [], default_template_id: null };
                }),
                settingsApi.fetchPrompts(),
                configData?.LLM_PROVIDER !== "local"
                    ? settingsApi.fetchOptions()
                    : Promise.resolve(null),
                settingsApi.fetchUserSettings(),
                settingsApi.fetchTemplates(),
            ]);

            setPrompts(prompts);
            if (optionsData) {
                setOptions(settingsHelpers.processOptionsData(optionsData));
            } else {
                setOptions({
                    general: { num_ctx: 0 },
                    secondary: { num_ctx: 0 },
                    letter: { temperature: 0 },
                });
            }
            // Coerce a stored language without a UI locale (pre-localisation
            // picks) to English so the dropdown never holds an unlisted value.
            if (!UI_LANGUAGES.some((l) => l.code === userSettings.preferred_language)) {
                userSettings.preferred_language = "en";
            }
            setUserSettings(userSettings);
            setTemplates(templates);

            // Sync the preferred language to the localStorage mirror and i18n
            // so locale-aware formatting tracks the clinic language.
            syncLanguage(userSettings.preferred_language);

            // Set letter templates from parallel fetch
            if (letterResponse) {
                setLetterTemplates(letterResponse.templates);
                if (letterResponse.default_template_id !== null) {
                    setUserSettings((prev) => ({
                        ...prev,
                        default_letter_template_id:
                            letterResponse.default_template_id,
                    }));
                }
            }

            // Fetch and merge default template into user settings
            const defaultTemplate = await templateService.getDefaultTemplate();
            setUserSettings((prev) => ({
                ...prev,
                default_template: defaultTemplate.template_key,
            }));
            lastDefaultTemplateRef.current = defaultTemplate.template_key;
        } catch (error) {
            console.error("Error loading settings:", error);
            toaster.create({
                title: "Error loading settings",
                description: error.message,
                type: "error",
                duration: 3000,
            });
        } finally {
            setCoreLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchCoreSettings();
    }, [fetchCoreSettings]);

    const debouncedWhisperUrl = useDebounce(config?.WHISPER_BASE_URL, 500);
    const debouncedLlmBaseUrl = useDebounce(config?.LLM_BASE_URL, 500);
    const debouncedLlmProvider = useDebounce(config?.LLM_PROVIDER, 500);
    const debouncedLlmApiKey = useDebounce(config?.LLM_API_KEY, 500);

    useEffect(() => {
        const validateUrls = async () => {
            if (debouncedWhisperUrl) {
                const whisperValid = await settingsApi.validateUrl(
                    "whisper",
                    debouncedWhisperUrl,
                );
                setUrlStatus((prev) => ({ ...prev, whisper: whisperValid }));
            } else {
                setUrlStatus((prev) => ({ ...prev, whisper: false }));
            }

            if (debouncedLlmBaseUrl) {
                // Use provider type from config for URL validation
                const providerType = debouncedLlmProvider || "openai";
                const llmValid = await settingsApi.validateUrl(
                    providerType,
                    debouncedLlmBaseUrl,
                );
                setUrlStatus((prev) => ({ ...prev, llm: llmValid }));
            } else {
                setUrlStatus((prev) => ({ ...prev, llm: false }));
            }
        };

        validateUrls();
    }, [debouncedWhisperUrl, debouncedLlmBaseUrl, debouncedLlmProvider]);

    useEffect(() => {
        const refreshWhisperModels = async () => {
            // Guard: don't clear existing models during debounce settling
            if (!debouncedWhisperUrl) {
                return;
            }

            setWhisperModelsLoading(true);
            try {
                await settingsService.fetchWhisperModels(
                    debouncedWhisperUrl,
                    setWhisperModelOptions,
                    setWhisperModelListAvailable,
                );
            } catch (error) {
                console.error("Error refreshing Whisper models:", error);
                setWhisperModelOptions([]);
                setWhisperModelListAvailable(false);
            } finally {
                setWhisperModelsLoading(false);
            }
        };

        refreshWhisperModels();
    }, [debouncedWhisperUrl]);

    useEffect(() => {
        const refreshLlmModels = async () => {
            // Local mode uses local model manager, not remote model listing
            if ((config?.LLM_PROVIDER || "openai") === "local") {
                return;
            }

            // Guard: don't clear existing models during debounce settling
            if (!debouncedLlmBaseUrl) {
                return;
            }

            setLlmModelsLoading(true);
            try {
                await settingsService.fetchLLMModels(
                    {
                        LLM_PROVIDER: debouncedLlmProvider || "openai",
                        LLM_BASE_URL: debouncedLlmBaseUrl,
                        LLM_API_KEY: debouncedLlmApiKey,
                    },
                    setModelOptions,
                );
            } catch (error) {
                console.error("Error refreshing LLM models:", error);
                setModelOptions([]);
            } finally {
                setLlmModelsLoading(false);
            }
        };

        refreshLlmModels();
    }, [
        debouncedLlmBaseUrl,
        debouncedLlmProvider,
        debouncedLlmApiKey,
        config?.LLM_PROVIDER,
    ]);

    // Load local models when provider is "local"
    useEffect(() => {
        if (config?.LLM_PROVIDER !== "local") return;

        const fetchLocalModels = async () => {
            setLlmModelsLoading(true);
            try {
                const localModels = await localModelApi.fetchLocalModels();
                const modelNames = localModels.models.map(
                    (m) => m.name || m.filename,
                );
                setModelOptions(modelNames);
            } catch (error) {
                console.error("Error loading local models:", error);
                setModelOptions([]);
            } finally {
                setLlmModelsLoading(false);
            }
        };

        fetchLocalModels();
    }, [config?.LLM_PROVIDER]);

    const toggleCollapse = (section) => {
        setCollapseStates((prev) => ({
            ...prev,
            [section]: !prev[section],
        }));
    };

    const saveUserSettingsFn = async (newSettings) => {
        const { disabled_tools: _dt, default_template, ...rest } = newSettings;
        await settingsApi.saveUserSettings({
            ...rest,
            default_letter_template_id:
                newSettings.default_letter_template_id || null,
        });
        if (
            default_template &&
            default_template !== lastDefaultTemplateRef.current
        ) {
            await templateService.setDefaultTemplate(default_template);
            lastDefaultTemplateRef.current = default_template;
        }
    };

    const savePromptsFn = async (newPrompts) => {
        if (newPrompts) await settingsApi.savePrompts(newPrompts);
    };

    const saveConfigFn = async (newConfig) => {
        if (newConfig) await settingsApi.saveConfig(newConfig);
    };

    const saveOptionsFn = async (newOptions) => {
        for (const [category, categoryOptions] of Object.entries(newOptions)) {
            await settingsApi.saveOptions(category, categoryOptions);
        }
    };

    const autosaveEnabled = !coreLoading;
    const userAutosave = useAutosave(
        userSettings,
        saveUserSettingsFn,
        800,
        autosaveEnabled,
    );
    const promptsAutosave = useAutosave(
        prompts,
        savePromptsFn,
        1200,
        autosaveEnabled,
    );
    const configAutosave = useAutosave(
        config,
        saveConfigFn,
        800,
        autosaveEnabled,
    );
    const optionsAutosave = useAutosave(
        options,
        saveOptionsFn,
        800,
        autosaveEnabled,
    );

    const isDirty =
        userAutosave.isDirty ||
        promptsAutosave.isDirty ||
        configAutosave.isDirty ||
        optionsAutosave.isDirty;

    useEffect(() => {
        const handler = (e) => {
            if (isDirty) {
                e.preventDefault();
                e.returnValue = "";
            }
        };
        window.addEventListener("beforeunload", handler);
        return () => window.removeEventListener("beforeunload", handler);
    }, [isDirty]);

    const handlePromptReset = async (promptType) => {
        try {
            const updatedPrompts =
                await settingsService.resetIndividualPrompt(promptType);
            setPrompts(updatedPrompts);
            toaster.create({
                title: "Success",
                description: `${promptType} prompt reset to default`,
                type: "success",
                duration: 3000,
            });
        } catch {
            toaster.create({
                title: "Error",
                description: "Failed to reset prompt",
                type: "error",
                duration: 3000,
            });
        }
    };

    const handleOptionsReset = async () => {
        try {
            await settingsService.resetOptionsToDefaults();
            const optionsData = await settingsApi.fetchOptions();
            setOptions(settingsHelpers.processOptionsData(optionsData));
            toaster.create({
                title: "Success",
                description: "Advanced options reset to defaults",
                type: "success",
                duration: 3000,
            });
        } catch {
            toaster.create({
                title: "Error",
                description: "Failed to reset advanced options",
                type: "error",
                duration: 3000,
            });
        }
    };

    const handlePromptChange = (promptType, field, value) => {
        setPrompts((prev) => ({
            ...prev,
            [promptType]: {
                ...prev[promptType],
                [field]: value,
            },
        }));
    };

    const handleOptionChange = (category, key, value) => {
        setOptions((prev) => ({
            ...prev,
            [category]: {
                ...prev[category],
                [key]: value,
            },
        }));
    };
    const handleConfigChange = (key, value) => {
        setConfig((prev) => ({
            ...prev,
            [key]: value,
        }));
    };

    const handleReEmbed = async (newEmbeddingModel, onProgress = null) => {
        await settingsService.reEmbed(
            newEmbeddingModel,
            config,
            true,
            onProgress,
        );
        await fetchCoreSettings();
    };

    useEffect(() => {
        if (!coreLoading) return;
        const t = setTimeout(() => setShowSpinner(true), 150);
        return () => clearTimeout(t);
    }, [coreLoading]);

    if (coreLoading) {
        return (
            <Center h="100dvh">
                {showSpinner && <Spinner size="xl" />}
            </Center>
        );
    }
    return (
        <Box p="5" borderRadius="sm" w="100%">
            <Text as="h2" mb="4">
                Settings
            </Text>
            <VStack gap="5" align="stretch">
                <UserSettingsPanel
                    isCollapsed={collapseStates.userSettings}
                    setIsCollapsed={() => toggleCollapse("userSettings")}
                    userSettings={userSettings}
                    setUserSettings={setUserSettings}
                    specialties={SPECIALTIES}
                    templates={templates}
                    letterTemplates={letterTemplates}
                    setTemplates={setTemplates}
                />

                <ModelSettingsPanel
                    isCollapsed={collapseStates.modelSettings}
                    setIsCollapsed={() => toggleCollapse("modelSettings")}
                    config={config}
                    handleConfigChange={handleConfigChange}
                    modelOptions={modelOptions}
                    embeddingModelOptions={modelOptions}
                    whisperModelOptions={whisperModelOptions}
                    whisperModelListAvailable={whisperModelListAvailable}
                    whisperModelsLoading={whisperModelsLoading}
                    llmModelsLoading={llmModelsLoading}
                    urlStatus={urlStatus}
                    handleReEmbed={handleReEmbed}
                />

                <PromptSettingsPanel
                    isCollapsed={collapseStates.promptSettings}
                    setIsCollapsed={() => toggleCollapse("promptSettings")}
                    prompts={prompts}
                    handlePromptChange={handlePromptChange}
                    handlePromptReset={handlePromptReset}
                    options={options}
                    handleOptionChange={handleOptionChange}
                    handleOptionsReset={handleOptionsReset}
                    config={config}
                />
            </VStack>
        </Box>
    );
};

