// Audio capture via WebAudio API.

const TARGET_SAMPLE_RATE = 16000;
const PROCESSOR_BUFFER_SIZE = 4096;

export class AudioRecorder {
    constructor() {
        this.audioContext = null;
        this.source = null;
        this.processor = null;
        this.stream = null;
        this.chunks = [];
        this.isRecording = false;
        this.isPaused = false;
    }

    async start() {
        if (this.isRecording) {
            throw new Error("Already recording");
        }

        this.stream = await navigator.mediaDevices.getUserMedia({
            audio: {
                channelCount: 1,
                echoCancellation: true,
                noiseSuppression: true,
            },
        });

        this.audioContext = new AudioContext();
        this.source = this.audioContext.createMediaStreamSource(this.stream);

        this.processor = this.audioContext.createScriptProcessor(
            PROCESSOR_BUFFER_SIZE,
            1,
            1,
        );
        this.processor.onaudioprocess = (event) => {
            if (!this.isRecording || this.isPaused) return;
            const input = event.inputBuffer.getChannelData(0);
            this.chunks.push(new Float32Array(input));
        };

        this.source.connect(this.processor);
        this.processor.connect(this.audioContext.destination);

        this.isRecording = true;
        this.isPaused = false;
    }

    pause() {
        if (!this.isRecording) return;
        this.isPaused = true;
    }

    resume() {
        this.isPaused = false;
    }

    async stop() {
        if (!this.isRecording) {
            throw new Error("Not recording");
        }
        this.isRecording = false;
        this.isPaused = false;

        // Tear down the WebAudio graph before we touch chunks.
        this.processor.onaudioprocess = null;
        try {
            this.source.disconnect();
            this.processor.disconnect();
        } catch {
            // disconnect() throws if already disconnected — ignore.
        }
        this.stream.getTracks().forEach((track) => track.stop());

        const nativeSampleRate = this.audioContext.sampleRate;
        await this.audioContext.close();

        const flat = flattenFloat32(this.chunks);
        this.chunks = [];

        const final =
            nativeSampleRate === TARGET_SAMPLE_RATE
                ? flat
                : resampleLinear(flat, nativeSampleRate, TARGET_SAMPLE_RATE);

        const wav = encodeWav(final, TARGET_SAMPLE_RATE);
        return new Blob([wav], { type: "audio/wav" });
    }
}


function flattenFloat32(chunks) {
    const totalLength = chunks.reduce((acc, c) => acc + c.length, 0);
    const flat = new Float32Array(totalLength);
    let offset = 0;
    for (const chunk of chunks) {
        flat.set(chunk, offset);
        offset += chunk.length;
    }
    return flat;
}


function resampleLinear(input, fromRate, toRate) {
    if (fromRate === toRate) return input;
    const ratio = toRate / fromRate;
    const outputLength = Math.floor(input.length * ratio);
    const output = new Float32Array(outputLength);
    for (let i = 0; i < outputLength; i++) {
        const srcIdx = i / ratio;
        const idx0 = Math.floor(srcIdx);
        const idx1 = Math.min(idx0 + 1, input.length - 1);
        const frac = srcIdx - idx0;
        output[i] = input[idx0] * (1 - frac) + input[idx1] * frac;
    }
    return output;
}

/// Write a standard 16-bit PCM WAV header + samples from Float32 in [-1, 1].
function encodeWav(samples, sampleRate) {
    const buffer = new ArrayBuffer(44 + samples.length * 2);
    const view = new DataView(buffer);

    const writeString = (offset, str) => {
        for (let i = 0; i < str.length; i++) {
            view.setUint8(offset + i, str.charCodeAt(i));
        }
    };

    // RIFF chunk
    writeString(0, "RIFF");
    view.setUint32(4, 36 + samples.length * 2, true);
    writeString(8, "WAVE");

    // fmt subchunk
    writeString(12, "fmt ");
    view.setUint32(16, 16, true); // subchunk size
    view.setUint16(20, 1, true); // audio format = PCM
    view.setUint16(22, 1, true); // mono
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * 2, true); // byte rate
    view.setUint16(32, 2, true); // block align
    view.setUint16(34, 16, true); // bits per sample

    // data subchunk
    writeString(36, "data");
    view.setUint32(40, samples.length * 2, true);

    // Float32 [-1, 1] → Int16 [-32768, 32767]
    let offset = 44;
    for (let i = 0; i < samples.length; i++) {
        const s = Math.max(-1, Math.min(1, samples[i]));
        view.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7fff, true);
        offset += 2;
    }

    return buffer;
}

/**
 * Calculate LLM performance estimate for Apple Silicon.
 *
 * @param {number} genNumber - M-series generation (1-4)
 * @param {string} tier - Chip tier ("Base", "Pro", "Max", "Ultra")
 * @param {number} paramsBillions - Model parameter count in billions
 * @param {number} [activeParamsBillions] - Active parameters (for models like qwen3-30b with A3B architecture)
 * @returns {{estimatedTime: number, speedFactor: number, displayText: string}}
 */
export function calculateLLMPerformance(
  genNumber,
  tier,
  paramsBillions,
  activeParamsBillions,
) {
  // Tier multipliers (based on M3 anchored memory bandwidth ratios)
  const tierMultipliers = {
    Base: 1.0,
    Pro: 1.25,
    Max: 3.3,
    Ultra: 6.6,
  };

  // 20% improvement per generation
  const growthRate = 0.2;
  const genOffset = genNumber - 3; // M3 is reference point
  const gMult = Math.pow(1 + growthRate, genOffset);

  const tMult = tierMultipliers[tier] || 1.0;
  const baseSpeedFactor = tMult * gMult;

  const baselineParams = 8.0;
  const effectiveParams = activeParamsBillions || paramsBillions;
  // Calculate how many times larger/smaller than baseline
  const sizeRatio = effectiveParams / baselineParams;
  const scalingExponent = Math.log2(1 / 0.75);
  const modelSizeFactor = Math.pow(sizeRatio, scalingExponent);

  const totalSpeedFactor = baseSpeedFactor / modelSizeFactor;
  const estimatedTime = (45.0 * modelSizeFactor) / baseSpeedFactor;

  return {
    estimatedTime,
    speedFactor: totalSpeedFactor,
    displayText: `~${Math.round(estimatedTime)}s for 10min audio`,
  };
}


/**
 * Get smart LLM model recommendations based on system specifications.

 *
 * @param {Array} availableModels - Array of available model objects from API
 * @param {Object} systemSpecs - System specifications containing total_memory_gb
 * @returns {Array} All models with recommendedType property, ordered by RAM requirement
 */
export function getSmartRecommendations(availableModels, systemSpecs) {
  if (!availableModels?.length) return [];

  // Sort by recommended RAM (lightest first), with size as tiebreaker
  const sortedModels = [...availableModels].sort((a, b) => {
    const ramA = a.recommended_ram_gb || 4;
    const ramB = b.recommended_ram_gb || 4;
    if (ramA !== ramB) return ramA - ramB;
    return a.size_mb - b.size_mb;
  });

  // If no system specs or no RAM value, return models without badges
  if (!systemSpecs?.total_memory_gb) {
    return sortedModels.map((model) => ({
      ...model,
      recommendedType: null,
    }));
  }

  // Pool system RAM with discrete GPU VRAM on platforms that expose it
  const ram = systemSpecs.total_memory_gb + (systemSpecs.dgpu_vram_gb || 0);
  const RAM_BUFFER_GB = 4;

  // Filter out models that won't fit with at least a 4GB buffer
  const usableModels = sortedModels.filter((model) => {
    const recommendedRam = model.recommended_ram_gb || 4;
    return ram >= recommendedRam + RAM_BUFFER_GB;
  });

  // Determine tier based on machine RAM
  let tier;
  if (ram < 16) {
    tier = 1;
  } else if (ram < 32) {
    tier = 2;
  } else {
    tier = 3;
  }

  // Identify in-tier models (those whose tier array includes the user's tier)
  const inTierIndices = [];
  usableModels.forEach((model, idx) => {
    const modelTier = model.tier || [];
    if (modelTier.length > 0 && modelTier.includes(tier)) {
      inTierIndices.push(idx);
    }
  });

  // Pick the middle in-tier model as "recommended"
  // (2nd if 2+, 1st if only 1 — ensures the star always shows when there's a match)
  const recommendedIdx =
    inTierIndices.length > 0
      ? inTierIndices[Math.min(1, inTierIndices.length - 1)]
      : -1;

  return usableModels.map((model, idx) => ({
    ...model,
    recommendedType: idx === recommendedIdx ? "recommended" : null,
  }));
}

// API functions for interacting with the chat service backend.
import { handleApiRequest, universalFetch } from "../helpers/apiHelpers";
import { buildApiUrl } from "../helpers/apiConfig";

export const chatApi = {
    sendMessage: async (
        messages,
        rawTranscription = null,
        patientContext = null,
    ) => {
        return handleApiRequest({
            apiCall: async () => {
                const url = await buildApiUrl("/api/chat");
                return universalFetch(url, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        messages,
                        raw_transcription: rawTranscription,
                        patient_context: patientContext,
                    }),
                });
            },
            errorMessage: "Error in chat communication",
        });
    },

    generateLetter: async (letterData) => {
        return handleApiRequest({
            apiCall: async () => {
                const url = await buildApiUrl("/api/generate-letter");
                return universalFetch(url, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(letterData),
                });
            },
            successMessage: "Letter generated successfully.",
            errorMessage: "Error generating letter",
        });
    },

    analyzeVisualDocument: async (payload) => {
        return handleApiRequest({
            apiCall: async () => {
                const url = await buildApiUrl(
                    "/api/chat/analyze-document-visual",
                );
                return universalFetch(url, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(payload),
                });
            },
            errorMessage: "Error analyzing document visuals",
        });
    },

    probeVisionCapability: async (payload = {}) => {
        return handleApiRequest({
            apiCall: async () => {
                const url = await buildApiUrl("/api/chat/vision-capability");
                return universalFetch(url, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(payload),
                });
            },
            errorMessage: "Error probing vision capability",
        });
    },

    getCurrentVisionCapability: async () => {
        return handleApiRequest({
            apiCall: async () => {
                const url = await buildApiUrl(
                    "/api/chat/vision-capability/current",
                );
                return universalFetch(url);
            },
            errorMessage: "Error fetching current vision capability",
        });
    },

    respondVisual: async (payload) => {
        return handleApiRequest({
            apiCall: async () => {
                const url = await buildApiUrl("/api/chat/respond-visual");
                return universalFetch(url, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(payload),
                });
            },
            errorMessage: "Error generating visual response",
        });
    },

    uploadImage: async (file) => {
        return handleApiRequest({
            apiCall: async () => {
                const url = await buildApiUrl("/api/chat/upload-image");
                const formData = new FormData();
                formData.append("file", file);
                return universalFetch(url, {
                    method: "POST",
                    body: formData,
                });
            },
            errorMessage: "Error uploading image",
        });
    },

    streamMessage: async function* (
        messages,
        rawTranscription = null,
        patientContext = null,
    ) {
        const url = await buildApiUrl("/api/chat");
        const response = await universalFetch(url, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                messages,
                raw_transcription: rawTranscription,
                patient_context: patientContext,
            }),
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";

        while (true) {
            const { value, done } = await reader.read();
            if (done) break;

            buffer += decoder.decode(value, { stream: true });
            const parts = buffer.split("\n\n");

            // Keep the last part in the buffer — it may be incomplete
            buffer = parts.pop() || "";

            for (const line of parts) {
                if (line.trim() && line.startsWith("data: ")) {
                    try {
                        const data = JSON.parse(line.slice(6));
                        if (data.type === "end" && data.function_response) {
                            // Handle function response at the end of stream

                            const fr = data.function_response;
                            let citations;
                            if (Array.isArray(fr)) {
                                citations = fr;
                            } else if (
                                fr &&
                                typeof fr === "object" &&
                                Array.isArray(fr.citations)
                            ) {
                                citations = fr.citations;
                            }

                            if (citations && citations.length > 0) {
                                yield {
                                    type: "context",
                                    content: Object.fromEntries(
                                        citations.map((item, index) => [
                                            index + 1,
                                            item,
                                        ]),
                                    ),
                                };
                            }
                        } else {
                            yield data;
                        }
                        await new Promise((resolve) => setTimeout(resolve, 0));
                    } catch (error) {
                        console.error("Error parsing chunk:", error);
                    }
                }
            }
        }

        // Process any remaining data in the buffer
        if (buffer.trim() && buffer.startsWith("data: ")) {
            try {
                const data = JSON.parse(buffer.slice(6));
                yield data;
            } catch (error) {
                console.error("Error parsing final chunk:", error);
            }
        }
    },
};

import { invoke } from "@tauri-apps/api/core";

/**
 * Encryption API for Tauri commands
 * Handles passphrase setup and unlock for SQLCipher database encryption.
 * No keychain caching - user must re-enter passphrase on every session (PHI requirement).
 */
export const encryptionApi = {
  /**
   * Check if encryption has been set up (database file exists)
   */
  hasSetup: async () => {
    try {
      return await invoke("has_encryption_setup");
    } catch (error) {
      console.error("Error checking encryption setup:", error);
      return false;
    }
  },

  /**
   * Check if database file exists
   */
  hasDatabase: async () => {
    try {
      return await invoke("has_database");
    } catch (error) {
      console.error("Error checking database:", error);
      return false;
    }
  },

  /**
   * Check if passphrase is cached in keychain
   * Always returns false since we don't use keychain caching (PHI requirement)
   */
  hasKeychain: async () => {
    try {
      return await invoke("has_keychain_entry");
    } catch (error) {
      console.error("Error checking keychain:", error);
      return false;
    }
  },

  /**
   * Get complete encryption status
   */
  getStatus: async () => {
    try {
      return await invoke("get_encryption_status");
    } catch (error) {
      console.error("Error getting encryption status:", error);
      return {
        has_setup: false,
        has_database: false,
        has_keychain: false,
      };
    }
  },

  /**
   * Set up encryption with a new passphrase
   * @param {string} passphrase - User's passphrase (min 12 characters)
   * @returns {string} Hex-encoded passphrase to pass to start_server_command
   */
  setup: async (passphrase) => {
    return await invoke("setup_encryption", { passphrase });
  },

  /**
   * Unlock with passphrase
   * @param {string} passphrase - User's passphrase
   * @returns {string} Hex-encoded passphrase to pass to start_server_command
   */
  unlock: async (passphrase) => {
    return await invoke("unlock_with_passphrase", { passphrase });
  },

  /**
   * Change passphrase (not yet implemented)
   */
  changePassphrase: async (oldPassphrase, newPassphrase) => {
    return await invoke("change_passphrase", {
      oldPassphrase: oldPassphrase,
      newPassphrase: newPassphrase,
    });
  },

  /**
   * Clear keychain (no-op since we don't use keychain)
   */
  clearKeychain: async () => {
    return await invoke("clear_keychain");
  },
};

/**
 * Calculate passphrase strength
 * @param {string} passphrase
 * @returns {object} - { score: 0-4, feedback: string }
 */
export const calculatePassphraseStrength = (passphrase) => {
  let score = 0;
  const feedback = [];

  if (passphrase.length >= 12) score += 1;
  else feedback.push("Use at least 12 characters");

  if (passphrase.length >= 16) score += 1;
  else if (passphrase.length >= 12) feedback.push("16+ characters is better");

  if (/[a-z]/.test(passphrase) && /[A-Z]/.test(passphrase)) score += 1;
  else feedback.push("Mix uppercase and lowercase");

  if (/\d/.test(passphrase)) score += 1;
  else feedback.push("Add numbers");

  if (/[^a-zA-Z0-9]/.test(passphrase)) score += 1;
  else feedback.push("Add special characters");

  // Cap at 4
  const finalScore = Math.min(score, 4);

  let strength = "Weak";
  if (finalScore >= 4) strength = "Strong";
  else if (finalScore >= 3) strength = "Good";
  else if (finalScore >= 2) strength = "Fair";

  return {
    score: finalScore,
    strength,
    feedback: feedback.length > 0 ? feedback : ["Looks good!"],
  };
};

