                return universalFetch(url, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(payload),
                    signal,
                });
            },
            timeout: 300000,
            errorMessage: "Error processing visual document",
        });
    },
};

import { getToolName, getToolPresentation } from "./toolPresentation";

const THINK_OR_TOOL = new Set(["think", "tool"]);

/**
 * Determine the current activity label for a single block.
 * Think blocks → "Thinking"
 * Tool blocks → label from getToolPresentation (e.g., "PubMed", "Wikipedia")
 */
const getBlockActivity = (block) => {
    if (block.type === "think") {
        return { label: "Thinking" };
    }
    if (block.type === "tool") {
        const toolName = getToolName(block);
        const presentation = getToolPresentation(toolName);
        return { label: presentation.label };
    }
    return { label: "" };
};

/**
 * Group consecutive think+tool blocks into activity-trace wrapper blocks.
 * Whitespace-only text blocks between think/tool blocks are absorbed into
 * the trace group rather than splitting it.
 * Meaningful text blocks pass through untouched.
 *
 * @param {Array} blocks - output of parseMessageContent()
 * @returns {Array} blocks with activity-trace wrappers
 */
export const groupActivityTrace = (blocks) => {
    if (!blocks || blocks.length === 0) return blocks;

    const result = [];
    let traceGroup = null;

    const flushTrace = () => {
        if (!traceGroup || traceGroup.length === 0) return;

        // Filter out whitespace-only text blocks from the trace
        const meaningful = traceGroup.filter(
            (b) => !b.isWhitespacePadding,
        );

        if (meaningful.length === 0) {
            traceGroup = null;
            return;
        }

        const anyPartial = meaningful.some((b) => b.isPartial);
        const lastBlock = meaningful[meaningful.length - 1];
        const activity = getBlockActivity(
            anyPartial
                ? meaningful.find((b) => b.isPartial) ?? lastBlock
                : lastBlock,
        );

        result.push({
            type: "activity-trace",
            traceBlocks: meaningful,
            currentActivity: {
                label: activity.label,
                isOngoing: anyPartial,
            },
        });
        traceGroup = null;
    };

    for (const block of blocks) {
        if (THINK_OR_TOOL.has(block.type)) {
            if (!traceGroup) traceGroup = [];
            traceGroup.push(block);
        } else if (
            block.type === "text" &&
            !block.content?.trim()
        ) {
            // Whitespace-only text — absorb into current trace group
            if (traceGroup) {
                traceGroup.push({ ...block, isWhitespacePadding: true });
            }
            // If no trace group yet, just skip leading whitespace
        } else {
            flushTrace();
            result.push(block);
        }
    }

    flushTrace();
    return result;
};

const THINK_OPEN = "<think>";
const THINK_CLOSE = "</think>";
const TOOL_OPEN_MATCHER = /<tool\b([^>]*)>/i;
const TOOL_CLOSE = "</tool>";

const normalizeNewlines = (value = "") => String(value).replace(/\r\n/g, "\n");

const decodeHtmlEntities = (value = "") =>
    String(value)
        .replace(/&quot;/g, '"')
        .replace(/&#34;/g, '"')
        .replace(/&apos;/g, "'")
        .replace(/&#39;/g, "'")
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/&amp;/g, "&");

const parseToolAttributes = (raw = "") => {
    const attrs = {};
    const attrRegex =
        /([a-zA-Z_][\w-]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/g;

    let match = attrRegex.exec(raw);
    while (match) {
        const [, key, dQuoted, sQuoted, bare] = match;
        attrs[key] = decodeHtmlEntities(dQuoted ?? sQuoted ?? bare ?? "");
        match = attrRegex.exec(raw);
    }

    return attrs;
};

const findLastToolOpenTag = (content) => {
    const matches = [...content.matchAll(/<tool\b[^>]*>/gi)];
    if (matches.length === 0) return null;

    const last = matches[matches.length - 1];
    return {
        index: last.index ?? -1,
        openTag: last[0],
    };
};

/**
 * Parse chat content into structured blocks only.
 *
 * Output shape:
 * {
 *   blocks: Array<{
 *     type: "text" | "think" | "tool",
 *     content: string,
 *     attrs?: Record<string, string>,
 *     isPartial?: boolean,
 *   }>,
 *   hasThinkBlocks: boolean,
 *   hasToolBlocks: boolean,
 *   hasPartialBlock: boolean,
 *   partialBlockType: "think" | "tool" | null,
 *   visibleText: string
 * }
 */
export const parseMessageContent = (rawContent) => {
    const content = normalizeNewlines(rawContent ?? "");
    const blocks = [];

    const closedBlockRegex =
        /<think>([\s\S]*?)<\/think>|<tool\b([^>]*)>([\s\S]*?)<\/tool>/gi;

    let lastIndex = 0;
    let match = closedBlockRegex.exec(content);

    while (match) {
        const full = match[0];
        const start = match.index;
        const end = start + full.length;

        if (start > lastIndex) {
            blocks.push({
                type: "text",
                content: content.slice(lastIndex, start),
            });
        }

        if (typeof match[1] === "string") {
            blocks.push({
                type: "think",
                content: match[1],
                isPartial: false,
            });
        } else {
            const attrsRaw = match[2] ?? "";
            const toolInner = match[3] ?? "";
            blocks.push({
                type: "tool",
                content: toolInner,
                attrs: parseToolAttributes(attrsRaw),
                isPartial: false,
            });
        }

        lastIndex = end;
        match = closedBlockRegex.exec(content);
    }

    if (lastIndex < content.length) {
        const remainder = content.slice(lastIndex);

        const thinkOpenIndex = remainder.lastIndexOf(THINK_OPEN);
        const thinkCloseAfterOpen =
            thinkOpenIndex >= 0
                ? remainder.indexOf(
                      THINK_CLOSE,
                      thinkOpenIndex + THINK_OPEN.length,
                  )
                : -1;

        const toolOpen = findLastToolOpenTag(remainder);
        const toolCloseAfterOpen =
            toolOpen && toolOpen.index >= 0
                ? remainder.indexOf(
                      TOOL_CLOSE,
                      toolOpen.index + toolOpen.openTag.length,
                  )
                : -1;

        const hasPartialThink =
            thinkOpenIndex >= 0 && thinkCloseAfterOpen === -1;
        const hasPartialTool = !!toolOpen && toolCloseAfterOpen === -1;

        let activePartial = null;

        if (hasPartialThink && hasPartialTool) {
            activePartial =
                thinkOpenIndex > toolOpen.index
                    ? { type: "think", index: thinkOpenIndex }
                    : {
                          type: "tool",
                          index: toolOpen.index,
                          openTag: toolOpen.openTag,
                      };
        } else if (hasPartialThink) {
            activePartial = { type: "think", index: thinkOpenIndex };
        } else if (hasPartialTool) {
            activePartial = {
                type: "tool",
                index: toolOpen.index,
                openTag: toolOpen.openTag,
            };
        }

        if (!activePartial) {
            blocks.push({
                type: "text",
                content: remainder,
            });
        } else if (activePartial.type === "think") {
            if (activePartial.index > 0) {
                blocks.push({
                    type: "text",
                    content: remainder.slice(0, activePartial.index),
                });
            }

            blocks.push({
                type: "think",
                content: remainder.slice(
                    activePartial.index + THINK_OPEN.length,
                ),
                isPartial: true,
            });
        } else {
            const openTag = activePartial.openTag;
            const openTagStart = activePartial.index;
            const openTagEnd = openTagStart + openTag.length;

            if (openTagStart > 0) {
                blocks.push({
                    type: "text",
                    content: remainder.slice(0, openTagStart),
                });
            }

            const attrPartMatch = openTag.match(TOOL_OPEN_MATCHER);
            const rawAttrs = attrPartMatch?.[1] ?? "";

            blocks.push({
                type: "tool",
                content: remainder.slice(openTagEnd),
                attrs: parseToolAttributes(rawAttrs),
                isPartial: true,
            });
        }
    }

    const hasThinkBlocks = blocks.some((b) => b.type === "think");
    const hasToolBlocks = blocks.some((b) => b.type === "tool");
    const partialBlock = blocks.find((b) => b.isPartial);

    return {
        blocks,
        hasThinkBlocks,
        hasToolBlocks,
        hasPartialBlock: Boolean(partialBlock),
        partialBlockType: partialBlock?.type ?? null,
        visibleText: blocks
            .filter((b) => b.type === "text")
            .map((b) => b.content)
            .join(""),
    };
};

/**
 * Expand a citation-group body
 */
export const expandCitationNumbers = (contents: string): number[] => {
    const out: number[] = [];
    for (const part of contents.split(",")) {
        const trimmed = part.trim();
        const rangeMatch = trimmed.match(/^(\d+)\s*-\s*(\d+)$/);
        if (rangeMatch) {
            const lo = Math.min(+rangeMatch[1], +rangeMatch[2]);
            const hi = Math.max(+rangeMatch[1], +rangeMatch[2]);
            for (let n = lo; n <= hi; n++) out.push(n);
        } else {
            const n = parseInt(trimmed, 10);
            if (!Number.isNaN(n)) out.push(n);
        }
    }
    return out;
};

const CITATION_GROUP_RE = /\[(\d+(?:\s*[-,]\s*\d+)*)\]/g;

/**
 * Build a remap from original citation indices to contiguous numbers
 */
export const buildCitationRemap = (
    visibleText: string,
): { remap: Map<number, number>; citedOriginals: number[] } => {
    const remap = new Map<number, number>();
    const citedOriginals: number[] = [];
    const seen = new Set<number>();
    CITATION_GROUP_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = CITATION_GROUP_RE.exec(visibleText || "")) !== null) {
        for (const n of expandCitationNumbers(m[1])) {
            if (!seen.has(n)) {
                seen.add(n);
                citedOriginals.push(n);
                remap.set(n, citedOriginals.length);
            }
        }
    }
    return { remap, citedOriginals };
};

export const extractCitedIndices = (visibleText: string): Set<number> => {
    const set = new Set<number>();
    CITATION_GROUP_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = CITATION_GROUP_RE.exec(visibleText || "")) !== null) {
        for (const n of expandCitationNumbers(m[1])) set.add(n);
    }
    return set;
};

