            type: "error",
            ...DEFAULT_TOAST_CONFIG,
        });
    } else {
        toaster.create({
            title: "Error",
            description: "An unexpected error occurred",
            type: "error",
            ...DEFAULT_TOAST_CONFIG,
        });
    }
};

