// Shared PDF extraction helpers used by both single-file and bulk uploaders.
import { ragApi } from "../api/ragApi";
import { chatApi } from "../api/chatApi";
import { settingsApi } from "../api/settingsApi";
import { extractPdfTextOrRenderForVision } from "./pdfVisionHelpers";

/**
 * Determine the document processing mode and vision capability from config.
 * @returns {{ mode: string, visionCapable: boolean }}
 */
async function getProcessingConfig() {
    let mode = "auto";
    let visionCapable = false;

    try {
        const cfg = await settingsApi.fetchConfig();
        if (cfg) {
            const rawMode = String(
                cfg?.DOCUMENT_IMAGE_PROCESSING_MODE || "auto",
            )
                .trim()
                .toLowerCase();
            mode =
                rawMode === "vision" ||
                rawMode === "ocr" ||
                rawMode === "auto"
                    ? rawMode
                    : "auto";

            try {
                const capability =
                    await chatApi.getCurrentVisionCapability();
                visionCapable = Boolean(capability?.vision_capable);
            } catch (capabilityError) {
                console.warn(
                    "Could not load cached current vision capability, falling back to legacy flag:",
                    capabilityError,
                );
                visionCapable = Boolean(cfg?.VISION_MODEL_CAPABLE);
            }
        }
    } catch (configError) {
        console.warn(
            "Could not load processing mode config, defaulting to auto:",
            configError,
        );
    }

    return { mode, visionCapable };
}

/**
 * Extract text from a PDF using the vision path (frontend text-first).
 * @param {File} file
 * @param {string} filename
 * @returns {Promise<string>} The extracted text.
 */
async function extractTextViaVision(file, filename) {
    const pdfResult = await extractPdfTextOrRenderForVision(file);

    let extractedText;
    if (pdfResult.strategy === "text") {
        extractedText = pdfResult.textResult?.text || "";
    } else {
        const visualResult = await chatApi.analyzeVisualDocument({
            filename,
            content_type: "application/pdf",
            strategy: "vision",
            pages: (pdfResult.imageResult?.images || []).map((img) => ({
                page_number: img.pageNumber,
                data_url: img.dataUrl,
                mime_type: img.mimeType,
                width: img.width,
                height: img.height,
            })),
            fallback_text: pdfResult.textResult?.text || "",
            extraction_info: {
                reason:
                    pdfResult.textResult?.quality?.reason ||
                    "No usable embedded PDF text",
                stats: pdfResult.textResult?.quality?.stats || {},
                page_count: pdfResult.textResult?.pageCount || 0,
                processed_pages:
                    pdfResult.textResult?.processedPages || 0,
                rendered_pages:
                    pdfResult.imageResult?.renderedPages || 0,
            },
        });

        extractedText =
            visualResult.text || pdfResult.textResult?.text || "";
    }

    if (!extractedText.trim()) {
        throw new Error(
            "Could not extract usable text from frontend visual/text-first path.",
        );
    }

    return extractedText;
}

/**
 * Extract PDF metadata (disease_name, focus_area, document_source) from a file.
 *
 * Handles both the vision path (frontend text-first) and the legacy backend
 * fallback. Returns the extracted text alongside the metadata so callers can
 * later commit without re-extracting.
 *
 * @param {File} file - The PDF file to process.
 * @returns {Promise<{ extractedText: string, disease_name: string, focus_area: string, document_source: string, filename: string }>}
 * @throws {Error} If extraction fails.
 */
export async function extractPdfMetadata(file) {
    const filename = file.name || "uploaded.pdf";

    const { mode, visionCapable } = await getProcessingConfig();

    const shouldUseVision =
        mode === "vision" || (mode === "auto" && visionCapable);
    const allowOcrFallback = mode !== "vision";

    if (mode === "vision" && !visionCapable) {
        throw new Error(
            "Vision mode is enabled, but the selected endpoint/model is not marked as vision-capable.",
        );
    }

    let extractedText;
    let metadata;

    if (shouldUseVision) {
        try {
            extractedText = await extractTextViaVision(file, filename);

            metadata = await ragApi.extractPdfInfoFromText({
                extracted_text: extractedText,
                filename,
            });
        } catch (visionPathError) {
            if (!allowOcrFallback) {
                throw visionPathError;
            }

            console.warn(
                "Vision path unavailable; falling back to backend OCR/PDF extraction:",
                visionPathError,
            );
            const formData = new FormData();
            formData.append("file", file);
            metadata = await ragApi.extractPdfInfo(formData);
            // Backend path doesn't return extracted text — we won't have it for direct commit.
            // In this case the caller should fall back to the two-step staging flow.
            extractedText = null;
        }
    } else {
        const formData = new FormData();
        formData.append("file", file);
        metadata = await ragApi.extractPdfInfo(formData);
        extractedText = null;
    }

    // Read raw file bytes as base64 for PDF storage
    let pdfBase64 = null;
    try {
        const arrayBuffer = await file.arrayBuffer();
        pdfBase64 = btoa(
            new Uint8Array(arrayBuffer).reduce(
                (data, byte) => data + String.fromCharCode(byte),
                "",
            ),
        );
    } catch (e) {
        console.warn("Could not read PDF bytes for storage:", e);
    }

    return {
        extractedText,
        pdfBase64,
        disease_name: metadata.disease_name,
        focus_area: metadata.focus_area,
        document_source: metadata.document_source,
        title: metadata.title,
        filename,
    };
}

import pdfWorkerUrl from "pdfjs-dist/build/pdf.worker.min.mjs?url";

const DEFAULT_TEXT_OPTIONS = {
    maxPages: 25,
    minTextLength: 250,
    minAlphaNumericRatio: 0.45,
    minUniqueWords: 25,
};

const DEFAULT_RENDER_OPTIONS = {
    maxPages: 6,
    scale: 1.75,
    maxDimension: 2200,
    imageType: "image/png",
    imageQuality: 0.92,
};

let pdfjsModulePromise = null;
let pdfjsWorkerConfigured = false;

export async function getPdfJs() {
    if (!pdfjsModulePromise) {
        pdfjsModulePromise = import("pdfjs-dist/legacy/build/pdf");
    }

    const pdfjs = await pdfjsModulePromise;

    if (!pdfjsWorkerConfigured) {
        pdfjs.GlobalWorkerOptions.workerSrc = pdfWorkerUrl;
        pdfjsWorkerConfigured = true;
    }

    return pdfjs;
}

const WASM_URL = `${import.meta.env.BASE_URL}wasm/`;
const CMAP_URL = `${import.meta.env.BASE_URL}cmaps/`;
const STANDARD_FONT_URL = `${import.meta.env.BASE_URL}standard_fonts/`;

export async function loadPdfDocument(options) {
    const pdfjs = await getPdfJs();
    const loadingTask = pdfjs.getDocument({
        wasmUrl: WASM_URL,
        cMapUrl: CMAP_URL,
        cMapPacked: true,
        standardFontDataUrl: STANDARD_FONT_URL,
        ...options,
    });
    return loadingTask.promise;
}

function normalizeText(input) {
    return String(input ?? "")
        .replace(/\u0000/g, " ")
        .replace(/\s+/g, " ")
        .trim();
}

function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
}

function computeAlphaNumericRatio(text) {
    if (!text) return 0;
    const alphaNum = (text.match(/[A-Za-z0-9]/g) || []).length;
    return alphaNum / text.length;
}

function countUniqueWords(text) {
    if (!text) return 0;
    const words = text
        .toLowerCase()
        .split(/[^a-z0-9]+/i)
        .filter((w) => w.length > 2);
    return new Set(words).size;
}

function isLikelyUsableText(text, options = {}) {
    const cfg = { ...DEFAULT_TEXT_OPTIONS, ...options };
    const normalized = normalizeText(text);

    if (!normalized) {
        return {
            usable: false,
            reason: "No text extracted from PDF",
            stats: {
                length: 0,
                alphaNumericRatio: 0,
                uniqueWords: 0,
            },
        };
    }

    const length = normalized.length;
    const alphaNumericRatio = computeAlphaNumericRatio(normalized);
    const uniqueWords = countUniqueWords(normalized);

    const usable =
        length >= cfg.minTextLength &&
        alphaNumericRatio >= cfg.minAlphaNumericRatio &&
        uniqueWords >= cfg.minUniqueWords;

    let reason = "Text extraction looks usable";
    if (!usable) {
        if (length < cfg.minTextLength) reason = "Extracted text is too short";
        else if (alphaNumericRatio < cfg.minAlphaNumericRatio)
            reason = "Extracted text looks noisy";
        else if (uniqueWords < cfg.minUniqueWords)
            reason = "Extracted text lacks enough lexical variety";
        else reason = "Extracted text failed quality checks";
    }

    return {
        usable,
        reason,
        stats: { length, alphaNumericRatio, uniqueWords },
    };
}

export function isPdfFile(file) {
    if (!file) return false;
    const mime = (file.type || "").toLowerCase();
    const name = (file.name || "").toLowerCase();
    return mime === "application/pdf" || name.endsWith(".pdf");
}

/**
 * Convert an uploaded file (typically image/*) to a data URL
 * suitable for multimodal/visual analysis endpoints.
 */
export async function convertFileToDataUrl(file, options = {}) {
    const cfg = {
        allowedMimeTypes: ["image/png", "image/jpeg", "image/jpg", "image/gif"],
        ...options,
    };

    if (!file) {
        throw new Error("convertFileToDataUrl expects a file");
    }

    const mime = (file.type || "").toLowerCase();
    const normalizedName = (file.name || "").toLowerCase();

    const extensionToMime = {
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg",
        ".gif": "image/gif",
    };

    const inferredMime = Object.entries(extensionToMime).find(([ext]) =>
        normalizedName.endsWith(ext),
    )?.[1];

    const effectiveMime = mime || inferredMime || "";

    if (!cfg.allowedMimeTypes.includes(effectiveMime)) {
        throw new Error(
            `Unsupported file type for data URL conversion: ${file.type || file.name || "unknown"}. Supported formats: GIF, JPG, JPEG, PNG.`,
        );
    }

    return new Promise((resolve, reject) => {
        const reader = new FileReader();

        reader.onload = () => {
            const result = String(reader.result || "");
            if (!result.startsWith("data:")) {
                reject(new Error("Failed to convert file to data URL"));
                return;
            }
            resolve(result);
        };

        reader.onerror = () => {
            reject(new Error("Failed to read file for data URL conversion"));
        };

        reader.readAsDataURL(file);
    });
}

export async function extractPdfText(file, options = {}) {
    if (!isPdfFile(file)) {
        throw new Error("extractPdfText expects a PDF file");
    }

    const cfg = { ...DEFAULT_TEXT_OPTIONS, ...options };
    const buffer = await file.arrayBuffer();

    const doc = await loadPdfDocument({
        data: buffer,
    });
    const pageCount = doc.numPages;
    const pagesToProcess = clamp(cfg.maxPages, 1, pageCount);

    const pageTexts = [];
    for (let i = 1; i <= pagesToProcess; i += 1) {
        const page = await doc.getPage(i);
        const textContent = await page.getTextContent();
        const pageText = normalizeText(
            textContent.items.map((item) => item.str || "").join(" "),
        );
        pageTexts.push(pageText);
    }

    const text = normalizeText(pageTexts.join("\n\n"));
    const quality = isLikelyUsableText(text, cfg);

    return {
        strategy: "text",
        text,
        pageCount,
        processedPages: pagesToProcess,
        quality,
    };
}

function createCanvas(width, height) {
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(1, Math.floor(width));
    canvas.height = Math.max(1, Math.floor(height));
    return canvas;
}

function fitViewport(viewport, maxDimension) {
    if (!maxDimension || maxDimension <= 0) return viewport;

    const maxSide = Math.max(viewport.width, viewport.height);
    if (maxSide <= maxDimension) return viewport;

    const factor = maxDimension / maxSide;
    return {
        width: Math.floor(viewport.width * factor),
        height: Math.floor(viewport.height * factor),
        transformScale: factor,
    };
}

export async function renderPdfPagesToImages(file, options = {}) {
    if (!isPdfFile(file)) {
        throw new Error("renderPdfPagesToImages expects a PDF file");
    }

    const cfg = { ...DEFAULT_RENDER_OPTIONS, ...options };
    const buffer = await file.arrayBuffer();

    const doc = await loadPdfDocument({
        data: buffer,
    });
    const pageCount = doc.numPages;
    const pagesToRender = clamp(cfg.maxPages, 1, pageCount);

    const images = [];

    for (let pageNumber = 1; pageNumber <= pagesToRender; pageNumber += 1) {
        const page = await doc.getPage(pageNumber);

        const rawViewport = page.getViewport({ scale: cfg.scale });
        const fitted = fitViewport(rawViewport, cfg.maxDimension);

        const renderScale = fitted.transformScale ?? 1;
        const viewport =
            renderScale === 1
                ? rawViewport
                : page.getViewport({ scale: cfg.scale * renderScale });

        const canvas = createCanvas(viewport.width, viewport.height);
        const ctx = canvas.getContext("2d", { alpha: false });

        await page.render({
            canvasContext: ctx,
            viewport,
        }).promise;

        const dataUrl = canvas.toDataURL(cfg.imageType, cfg.imageQuality);
        images.push({
            pageNumber,
            dataUrl,
            width: canvas.width,
            height: canvas.height,
            mimeType: cfg.imageType,
        });

        // release memory
        canvas.width = 1;
        canvas.height = 1;
    }

    return {
        strategy: "vision",
        pageCount,
        renderedPages: pagesToRender,
        images,
    };
}

/**
 * High-level helper:
 * - tries text extraction first
 * - if low-quality text, returns rendered page images for vision model fallback
 */
export async function extractPdfTextOrRenderForVision(file, options = {}) {
    const textOptions = { ...DEFAULT_TEXT_OPTIONS, ...(options.text || {}) };
    const renderOptions = {
        ...DEFAULT_RENDER_OPTIONS,
        ...(options.render || {}),
    };

    const textResult = await extractPdfText(file, textOptions);

    if (textResult.quality.usable) {
        return {
            strategy: "text",
            textResult,
            imageResult: null,
        };
    }

    const imageResult = await renderPdfPagesToImages(file, renderOptions);

    return {
        strategy: "vision",
        textResult,
        imageResult,
    };
}

// Helper functions for handling processing of documents and transcriptions.
import { transcriptionApi } from "../api/transcriptionApi";

export const handleProcessingComplete = (
  data,
  {
    setLoading,
    setters = {},
    setIsSourceCollapsed,
    setIsSummaryCollapsed,
    triggerResize = false,
    summaryRef = null,
  },
) => {
  setLoading(false);

  // Special handling for template_data since it's nested in fields
  if (setters.template_data && data.fields) {
    setters.template_data(data.fields);
  }

  // Handle other setters
  Object.entries(setters).forEach(([key, setter]) => {
    if (key !== "template_data" && data[key] !== undefined && setter) {
      setter(data[key]);
    }
  });

  // Handle UI collapse states
  if (setIsSourceCollapsed) {
    setIsSourceCollapsed(true);
  }
  if (setIsSummaryCollapsed) {
    setIsSummaryCollapsed(false);
  }

  // Only try to resize if we have a valid ref and it has the method
  if (triggerResize && summaryRef?.current?.resizeTextarea) {
    setTimeout(() => {
      summaryRef.current.resizeTextarea();
    }, 0);
  }
};

export const processDocument = async (
  file,
  patientDetails,
  onSuccess,
  onError,
) => {
  const formData = new FormData();
  formData.append("file", file);

  // Add patient details to formData if they exist
  Object.entries(patientDetails).forEach(([key, value]) => {
    if (value) formData.append(key, value);
  });

  try {
    const data = await transcriptionApi.processDocument(formData);
    onSuccess(data);
    return data;
  } catch (error) {
    console.error("Error processing document:", error);
    onError(error);
    throw error;
  }
};

