    const showWarningToast = useCallback(
        (message) => {
            toaster.create({
                title: "Warning",
                description: message,
                type: "warning",
                ...DEFAULT_TOAST_CONFIG,
            });
        },
        [],
    );

    return useMemo(
        () => ({ showSuccessToast, showErrorToast, showWarningToast }),
        [showSuccessToast, showErrorToast, showWarningToast],
    );
};

import { useState, useCallback } from "react";

export const useActivePanel = () => {
    const [activePanel, setActivePanel] = useState(null);

    const open = useCallback((name) => {
        setActivePanel(name);
    }, []);

    const toggle = useCallback((name) => {
        setActivePanel((prev) => (prev === name ? null : name));
    }, []);

    const close = useCallback((name) => {
        setActivePanel((prev) => (prev === name ? null : prev));
    }, []);

    const closeAll = useCallback(() => {
        setActivePanel(null);
    }, []);

    const isOpen = useCallback((name) => activePanel === name, [activePanel]);

    return { activePanel, open, toggle, close, closeAll, isOpen };
};

import { useState, useEffect, useCallback } from "react";
import { Box } from "@chakra-ui/react";
import { toaster } from "@/components/ui/toaster";
import { invoke } from "@tauri-apps/api/core";
import SplashScreen from "../../components/common/SplashScreen";
import EncryptionSetup from "../../components/setup/EncryptionSetup";
import EncryptionUnlock from "../../components/setup/EncryptionUnlock";
import ServerStartupLoader from "../../components/setup/ServerStartupLoader";
import { settingsApi } from "../api/settingsApi";
import { isTauri } from "../../utils/helpers/apiConfig";
import {
    isForceSplashEnabled,
    setEmbeddingReady,
} from "../../utils/helpers/featureFlags";
import { encryptionApi } from "../../utils/api/encryptionApi";
import { localModelApi } from "../../utils/api/localModelApi";

export const useAppBootstrap = () => {
    const [showSplashScreen, setShowSplashScreen] = useState(undefined);
    const [, setIsLoadingSplashCheck] = useState(!isTauri());
    const [, setEncryptionStatus] = useState(null);
    const [showEncryptionSetup, setShowEncryptionSetup] = useState(false);
    const [showEncryptionUnlock, setShowEncryptionUnlock] = useState(false);
    const [, setIsLoadingEncryptionCheck] = useState(!isTauri());
    const [isCheckingEncryptionStatus, setIsCheckingEncryptionStatus] =
        useState(isTauri());
    const [showServerStartupLoader, setShowServerStartupLoader] =
        useState(false);
    const [isInGracePeriod, setIsInGracePeriod] = useState(isTauri());

    // App initialization state - true when server is not ready yet.
    const isInitializing =
        showEncryptionSetup ||
        showEncryptionUnlock ||
        showServerStartupLoader ||
        isInGracePeriod;

    const checkSplashStatus = useCallback(async (options = {}) => {
        const { maxRetries = 5, retryDelay = 500 } = options;

        if (isForceSplashEnabled()) {
            setShowSplashScreen(true);
            setIsLoadingSplashCheck(false);
            return;
        }

        let lastError;
        let success = false;

        for (let attempt = 0; attempt < maxRetries; attempt++) {
            try {
                const userData = await settingsApi.fetchUserSettings();
                if (
                    userData &&
                    typeof userData.has_completed_splash_screen ===
                        "boolean"
                ) {
                    setShowSplashScreen(
                        !userData.has_completed_splash_screen,
                    );
                } else {
                    setShowSplashScreen(true); // Default to showing splash if flag is missing/invalid
                }
                // Success - exit the retry loop
                success = true;
                break;
            } catch (error) {
                console.warn(
                    `Error checking splash screen status (attempt ${attempt + 1}/${maxRetries}):`,
                    error,
                );
                lastError = error;
                // Wait before retrying (except on the last attempt)
                if (attempt < maxRetries - 1) {
                    await new Promise((resolve) =>
                        setTimeout(resolve, retryDelay),
                    );
                }
            }
        }

        if (!success) {
            // All retries failed
            console.error(
                "Error checking splash screen status after retries:",
                lastError,
            );
            setShowSplashScreen(true); // Default to showing splash on error
        }

        setIsLoadingSplashCheck(false);
    }, []);

    // Only check splash status on mount if NOT in Tauri
    // In Tauri, we wait until after encryption unlock is complete
    useEffect(() => {
        if (!isTauri()) {
            checkSplashStatus();
        }
    }, [checkSplashStatus]);

    const handleSplashComplete = () => {
        setShowSplashScreen(false);
    };

    useEffect(() => {
        if (!isTauri()) {
            return;
        }

        const checkEncryptionStatus = async () => {
            try {
                const status = await encryptionApi.getStatus();
                setEncryptionStatus(status);

                if (!status.has_setup && !status.has_database) {
                    setShowEncryptionSetup(true);
                } else if (status.has_setup && !status.has_keychain) {
                    try {
                        await invoke("start_server_command");
                        console.log(
                            "Server started in warm mode, waiting for passphrase",
                        );
                    } catch (e) {
                        console.warn("Failed to warm start server:", e);
                    }
                    setShowEncryptionUnlock(true);
                }
            } catch (error) {
                console.error("Error checking encryption status:", error);
            } finally {
                setIsLoadingEncryptionCheck(false);
                setIsCheckingEncryptionStatus(false);
            }
        };

        checkEncryptionStatus();
    }, []);

    const handleEncryptionSetupComplete = () => {
        setShowEncryptionSetup(false);
        setShowServerStartupLoader(true);
    };

    const handleEncryptionUnlockComplete = () => {
        setShowEncryptionUnlock(false);
        setShowServerStartupLoader(true);
    };

    const handleServerReady = () => {
        setShowServerStartupLoader(false);
        checkSplashStatus({ maxRetries: 3, retryDelay: 300 });

        // Sync embedding model status for RAG feature flag (Tauri only)
        if (isTauri()) {
            localModelApi.fetchEmbeddingStatus()
                .then((res) => {
                    const has = !!res?.downloaded;
                    setEmbeddingReady(has);
                })
                .catch(() => {});
        }

        setTimeout(() => {
            setIsInGracePeriod(false);
        }, 2000); // 2 second grace period
    };

    const handleServerError = (error) => {
        console.error("Server startup error:", error);
        setShowServerStartupLoader(false);
        // Show error toast
        toaster.create({
            title: "Server Error",
            description: error.message || "Failed to start the server",
            type: "error",
            duration: 5000,
        });
        // Go back to unlock screen
        setShowEncryptionUnlock(true);
    };

    let gate = null;
    if (isCheckingEncryptionStatus) {
        gate = <Box className="splash-bg" w="100vw" h="100dvh" />;
    } else if (showEncryptionSetup) {
        gate = <EncryptionSetup onComplete={handleEncryptionSetupComplete} />;
    } else if (showEncryptionUnlock) {
        gate = <EncryptionUnlock onComplete={handleEncryptionUnlockComplete} />;
    } else if (showServerStartupLoader) {
        gate = (
            <ServerStartupLoader
                onReady={handleServerReady}
                onError={handleServerError}
            />
        );
    } else if (showSplashScreen) {
        gate = <SplashScreen onComplete={handleSplashComplete} />;
    }

    return { isInitializing, gate };
};

import { useRef, useEffect, useState, useCallback } from "react";

/**
 * Debounced autosave hook. Calls `saver(value)` after `delay` ms of quiet
 * whenever `value` changes, but only once `enabled` is true.
 *
 * @param {*} value - The current value to watch and persist.
 * @param {(value: *) => Promise} saver - Async function that persists the value.
 * @param {number} [delay=800] - Debounce delay in milliseconds.
 * @param {boolean} [enabled=true] - Master switch; when false, no saves fire.
 * @returns {{isDirty: boolean, flush: () => Promise<void>}}
 */
export const useAutosave = (value, saver, delay = 800, enabled = true) => {
  const [isDirty, setIsDirty] = useState(false);
  const timeoutRef = useRef(null);
  const lastSavedRef = useRef(value);
  const saverRef = useRef(saver);
  const wasEnabledRef = useRef(false);

  // Keep saver ref current without retriggering the effect
  useEffect(() => {
    saverRef.current = saver;
  }, [saver]);

  useEffect(() => {
    // When autosave first becomes enabled, treat current value as the baseline
    if (enabled && !wasEnabledRef.current) {
      wasEnabledRef.current = true;
      lastSavedRef.current = value;
      return;
    }

    if (!enabled) {
      wasEnabledRef.current = false;
      return;
    }

    // No change from last saved baseline
    if (value === lastSavedRef.current) return;

    setIsDirty(true);

    if (timeoutRef.current) clearTimeout(timeoutRef.current);

    timeoutRef.current = setTimeout(async () => {
      try {
        await saverRef.current(value);
        lastSavedRef.current = value;
      } catch (e) {
        console.error("Autosave failed:", e);
      } finally {
        setIsDirty(false);
        timeoutRef.current = null;
      }
    }, delay);

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
        timeoutRef.current = null;
      }
    };
  }, [value, delay, enabled]);

  // Manually flush pending changes (for navigation guards)
  const flush = useCallback(async () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    if (value !== lastSavedRef.current) {
      try {
        await saverRef.current(value);
        lastSavedRef.current = value;
      } catch (e) {
        console.error("Autosave flush failed:", e);
      } finally {
        setIsDirty(false);
      }
    }
  }, [value]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  return { isDirty, flush };
};

import { useState, useCallback } from "react";
import { toaster } from "@/components/ui/toaster";
import { ragApi } from "../api/ragApi";
import { extractPdfMetadata } from "../helpers/pdfExtractHelpers";

export const STATUS = {
    PENDING: "pending",
    EXTRACTING: "extracting",
    EXTRACTED: "extracted",
    COMMITTING: "committing",
    COMMITTED: "committed",
    FAILED: "failed",
};

/** Create a fresh queue entry for a File object. */
function makeQueueEntry(file) {
    return {
        id: `${file.name}-${file.size}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        file,
        status: STATUS.PENDING,
        extractedText: null,
        metadata: null,
        error: null,
    };
}

export const useBulkUploadQueue = ({ setCollections } = {}) => {
    const [fileQueue, setFileQueue] = useState([]);
    const [isProcessing, setIsProcessing] = useState(false);

    const addFiles = useCallback((files) => {
        const newEntries = files.map(makeQueueEntry);
        setFileQueue((prev) => [...prev, ...newEntries]);
    }, []);

    const removeFromQueue = useCallback((id) => {
        setFileQueue((prev) => prev.filter((entry) => entry.id !== id));
    }, []);

    const updateQueueEntry = useCallback((id, updates) => {
        setFileQueue((prev) =>
            prev.map((entry) =>
                entry.id === id ? { ...entry, ...updates } : entry,
            ),
        );
    }, []);

    const updateMetadata = useCallback((id, field, value) => {
        setFileQueue((prev) =>
            prev.map((entry) =>
                entry.id === id
                    ? { ...entry, metadata: { ...entry.metadata, [field]: value } }
                    : entry,
            ),
        );
    }, []);

    const extractAll = useCallback(async () => {
        setIsProcessing(true);
        const pending = fileQueue.filter(
            (e) => e.status === STATUS.PENDING || e.status === STATUS.FAILED,
        );

        for (const entry of pending) {
            updateQueueEntry(entry.id, {
                status: STATUS.EXTRACTING,
                error: null,
            });

            try {
                const result = await extractPdfMetadata(entry.file);
                updateQueueEntry(entry.id, {
                    status: STATUS.EXTRACTED,
                    extractedText: result.extractedText,
                    pdfBase64: result.pdfBase64,
                    metadata: {
                        disease_name: result.disease_name,
                        focus_area: result.focus_area,
                        document_source: result.document_source,
                        filename: result.filename,
                        title: result.title,
                    },
                });
            } catch (error) {
                console.error(
                    `Extraction failed for ${entry.file.name}:`,
                    error,
                );
                updateQueueEntry(entry.id, {
                    status: STATUS.FAILED,
                    error: error.message || "Extraction failed",
                });
            }
        }

        setIsProcessing(false);

        if (pending.length > 0) {
            // Re-read latest state via setFileQueue callback to compute counts.
            setFileQueue((current) => {
                const failedCount = pending.filter((p) => {
                    const e = current.find((f) => f.id === p.id);
                    return e?.status === STATUS.FAILED;
                }).length;
                if (failedCount === 0) {
                    toaster.create({
                        title: "Extraction Complete",
                        description: `Successfully extracted ${pending.length} file(s)`,
                        type: "success",
                        duration: 3000,
                    });
                } else {
                    toaster.create({
                        title: "Extraction Partially Complete",
                        description: `${pending.length - failedCount} of ${pending.length} file(s) extracted successfully`,
                        type: "warning",
                        duration: 3000,
                    });
                }
                return current;
            });
        }
    }, [fileQueue, updateQueueEntry]);

    const commitAll = useCallback(async () => {
        if (!setCollections) return;
        setIsProcessing(true);
        const ready = fileQueue.filter((e) => e.status === STATUS.EXTRACTED);

        let committedCount = 0;
        for (const entry of ready) {
            updateQueueEntry(entry.id, { status: STATUS.COMMITTING });

            try {
                if (entry.extractedText) {
                    await ragApi.commitDirect({
                        extracted_text: entry.extractedText,
                        disease_name: entry.metadata.disease_name,
                        focus_area: entry.metadata.focus_area,
                        document_source: entry.metadata.document_source,
                        filename: entry.metadata.filename,
                        title: entry.metadata.title || null,
                        pdf_base64: entry.pdfBase64 || null,
                    });
                } else {
                    await ragApi.commitToDatabase({
                        disease_name: entry.metadata.disease_name,
                        focus_area: entry.metadata.focus_area,
                        document_source: entry.metadata.document_source,
                        filename: entry.metadata.filename,
                        title: entry.metadata.title || null,
                    });
                }
                updateQueueEntry(entry.id, {
                    status: STATUS.COMMITTED,
                    extractedText: null,
                });
                committedCount++;
            } catch (error) {
                console.error(
                    `Commit failed for ${entry.metadata.filename}:`,
                    error,
                );
                updateQueueEntry(entry.id, {
                    status: STATUS.FAILED,
                    error: error.message || "Commit failed",
                });
            }
        }

        try {
            const updatedCollections = await ragApi.fetchCollections();
            setCollections(
                updatedCollections.files.map((name) => ({
                    name,
                    files: [],
                    loaded: false,
                })),
            );
        } catch (error) {
            console.error("Error refreshing collections:", error);
        }

        setIsProcessing(false);

        toaster.create({
            title: "Commit Complete",
            description: `${committedCount} of ${ready.length} file(s) committed successfully`,
            type: committedCount === ready.length ? "success" : "warning",
            duration: 3000,
        });
    }, [fileQueue, setCollections, updateQueueEntry]);

    return {
        fileQueue,
        isProcessing,
        addFiles,
        removeFromQueue,
        updateQueueEntry,
        updateMetadata,
        extractAll,
        commitAll,
        extractedCount: fileQueue.filter(
            (e) => e.status === STATUS.EXTRACTED || e.status === STATUS.COMMITTED,
        ).length,
        committedCount: fileQueue.filter((e) => e.status === STATUS.COMMITTED)
            .length,
        totalPending: fileQueue.filter((e) => e.status === STATUS.PENDING)
            .length,
        readyToCommit: fileQueue.filter((e) => e.status === STATUS.EXTRACTED)
            .length,
        hasPendingOrFailed: fileQueue.some(
            (e) => e.status === STATUS.PENDING || e.status === STATUS.FAILED,
        ),
    };
};

import { useState, useCallback } from "react";
import { chatApi } from "../api/chatApi";
import { formatPatientContext } from "../chat/messageUtils";

// Simple mode for RAG chat (no patient/template required)
const RAG_SYSTEM_MESSAGE = {
    role: "system",
    content:
        "The user is a qualified healthcare professional. They will ask you general questions about medical conditions, treatment and guidelines. You are an informational and educational assistant only; you are NOT a clinical decision support tool. Do not provide definitive diagnoses or treatment recommendations. All responses are general and educational; the clinician is solely responsible for all clinical decisions and must rely on their own professional judgement and current authoritative guidelines.",
};

const getClinicianToolActionLabel = (toolName = "") => {
    const normalized = String(toolName).toLowerCase();

    // Literature/Search tools
    if (normalized.includes("pubmed")) {
        return "Searching PubMed evidence";
    }
    if (normalized.includes("wiki")) {
        return "Reviewing reference material";
    }
    if (normalized.includes("literature")) {
        return "Searching medical literature";
    }

    // Transcript
    if (normalized.includes("transcript")) {
        return "Reviewing encounter transcript";
    }

    // Patient tools
    if (normalized.includes("create_note")) {
        return "Creating patient note";
    }
    if (normalized.includes("get_previous_encounter")) {
        return "Fetching previous encounter";
    }
    if (normalized.includes("search_patient_notes")) {
        return "Searching patient notes";
    }
    if (normalized.includes("get_patient_jobs")) {
        return "Fetching patient tasks";
    }

    // Job/Task tools
    if (normalized.includes("todo_list")) {
        return "Accessing todo list";
    }
    if (normalized.includes("list_outstanding_jobs")) {
        return "Listing outstanding tasks";
    }
    if (normalized.includes("complete_job")) {
        return "Completing task";
    }

    // Direct response
    if (normalized.includes("direct_response")) {
        return "Drafting response";
    }

    // MCP tools - format: mcp_{server_name}_{tool_name}
    if (normalized.startsWith("mcp_")) {
        const parts = normalized.split("_");
        if (parts.length >= 3) {
            const serverName = parts[1];
            const mcpToolName = parts.slice(2).join("_");
            return `Using ${mcpToolName} (${serverName})`;
        }
        return `Using MCP tool: ${normalized}`;
    }

    return "Processing request";
};

export const useChat = ({ mode = "patient" } = {}) => {
    const [chatExpanded, setChatExpanded] = useState(false);
    const [messages, setMessages] = useState([]);
    const [userInput, setUserInput] = useState("");
    const [showSuggestions, setShowSuggestions] = useState(true);
    const [loading, setLoading] = useState(false);

    const sendMessage = useCallback(
        async (
            input,
            patient = null,
            currentTemplate = null,
            rawTranscription = null,
            attachments = null,
        ) => {
            if (!input.trim() && !attachments) return;

            // For patient mode, require patient and template
            if (mode === "patient" && (!patient || !currentTemplate)) return;

            setLoading(true);
            setChatExpanded(true);

            // Build content for API (includes extracted text from attachments)
            let contentForApi = input.trim();
            if (attachments && attachments.length > 0) {
                const attachmentTexts = attachments.map(
                    (att) =>
                        `[Content extracted from ${att.filename}]:\n${att.extractedText}`,
                );
                contentForApi = contentForApi
                    ? `${contentForApi}\n\n${attachmentTexts.join("\n\n")}`
                    : attachmentTexts.join("\n\n");
            }

            // Add user message to UI (attachments shown as chips, not inline text)
            const userMessage = {
                role: "user",
                content: input.trim(),
                attachments: attachments,
            };
            setMessages((prev) => [...prev, userMessage]);

            // Message for API includes extracted text
            const userMessageForApi = { role: "user", content: contentForApi };

            // Clear input immediately when sending
            setUserInput("");
            setShowSuggestions(false);

            try {
                let initialMessage;
                let patientContext = null;

                if (mode === "rag") {
                    initialMessage = RAG_SYSTEM_MESSAGE;
                } else {
                    // Format patient context for the backend to build the system message
                    patientContext = formatPatientContext(
                        currentTemplate,
                        patient,
                    );
                    if (!patientContext) {
                        throw new Error("Failed to format patient context");
                    }
                    // No initial message needed - backend will build system message from patient context
                    initialMessage = null;
                }

                // Messages for API are just the conversation history (no initial message with patient data)
                // Use userMessageForApi which includes extracted attachment text
                const messagesForApi = initialMessage
                    ? [initialMessage, ...messages, userMessageForApi]
                    : [...messages, userMessageForApi];

                let fullContent = "";
                let firstChunkSeen = false;

                // Add placeholder assistant message with loading state
                setMessages((prev) => [
                    ...prev,
                    {
                        role: "assistant",
                        content: "",
                        loading: true,
                    },
                ]);

                // Stream the response
                for await (const chunk of chatApi.streamMessage(
                    messagesForApi,
                    rawTranscription,
                    patientContext,
                )) {
                    if (
                        !firstChunkSeen &&
                        (chunk.type === "chunk" || chunk.type === "status")
                    ) {
                        firstChunkSeen = true;
                        setLoading(false);
                    }

                    if (chunk.type === "chunk") {
                        // Create a local copy of fullContent to use in the closure
                        const newContent = fullContent + chunk.content;
                        fullContent = newContent; // Update fullContent after creating the local copy

                        setMessages((prev) => {
                            const newMessages = [...prev];
                            const lastMessage =
                                newMessages[newMessages.length - 1];
                            newMessages[newMessages.length - 1] = {
                                ...lastMessage, // Preserve existing properties like isThinkingExpanded
                                role: "assistant",
                                content: newContent,
                                loading: false,
                            };
                            return newMessages;
                        });
                    } else if (chunk.type === "status" && chunk.content) {
                        const statusText = chunk.content.trim();

                        const callMatch = statusText.match(
                            /^Calling tool:\s*([^|]+?)(?:\s*\|\s*query:\s*(.+))?$/i,
                        );

                        // Only render tool UI blocks for explicit tool-call status events.
                        if (!callMatch) {
                            continue;
                        }

                        const toolName = (callMatch[1] ?? "")
                            .replace(/\s+/g, " ")
                            .trim()
                            .replace(/^["'`]+|["'`]+$/g, "")
                            .replace(/"/g, "'");

                        const toolQuery = (callMatch[2] ?? "")
                            .replace(/\s+/g, " ")
                            .trim()
                            .replace(/"/g, "'");

                        const actionLabel =
                            getClinicianToolActionLabel(toolName);
                        const clinicianStatusText = toolQuery
                            ? `${actionLabel}: ${toolQuery}`
                            : actionLabel;

                        const escapeAttr = (value = "") =>
                            String(value)
                                .replace(/&/g, "&amp;")
                                .replace(/"/g, "&quot;")
                                .replace(/</g, "&lt;")
                                .replace(/>/g, "&gt;");

                        const toolTag = `<tool name="${escapeAttr(toolName)}" status="running"${toolQuery ? ` query="${escapeAttr(toolQuery)}"` : ""}>${clinicianStatusText}</tool>`;

                        const newContent = `${fullContent}\n${toolTag}\n`;
                        fullContent = newContent;

                        setMessages((prev) => {
                            const newMessages = [...prev];
                            const lastMessage =
                                newMessages[newMessages.length - 1];
                            newMessages[newMessages.length - 1] = {
                                ...lastMessage,
                                role: "assistant",
                                content: newContent,
                                loading: false,
                            };
                            return newMessages;
                        });
                    } else if (chunk.type === "context") {
                        setMessages((prev) => {
                            const newMessages = [...prev];
                            newMessages[newMessages.length - 1] = {
                                ...newMessages[newMessages.length - 1],
                                context: chunk.content,
                                loading: false,
                            };
                            return newMessages;
                        });
                    } else if (chunk.type === "artifact" && chunk.artifact) {
                        if (chunk.artifact.type === "form_fill") {
                            // form_fill artifacts carry metadata only (no base64 data);
                            // the frontend fills the PDF client-side via FormFillArtifact.
                            setMessages((prev) => {
                                const newMessages = [...prev];
                                const last = newMessages[newMessages.length - 1];
                                const existing = last.artifacts || [];
                                newMessages[newMessages.length - 1] = {
                                    ...last,
                                    artifacts: [...existing, chunk.artifact],
                                    loading: false,
                                };
                                return newMessages;
                            });
                        } else {
                            // Binary artifact (e.g. MCP file) — decode base64 payload.
                            const { data: b64Data, ...meta } = chunk.artifact;
                            if (!b64Data) return;
                            const binary = atob(b64Data);
                            const bytes = new Uint8Array(binary.length);
                            for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
                            const blob = new Blob([bytes], { type: meta.mime_type });
                            const blobUrl = URL.createObjectURL(blob);

                            setMessages((prev) => {
                                const newMessages = [...prev];
                                const last = newMessages[newMessages.length - 1];
                                const existing = last.artifacts || [];
                                newMessages[newMessages.length - 1] = {
                                    ...last,
                                    artifacts: [...existing, { ...meta, url: blobUrl }],
                                    loading: false,
                                };
                                return newMessages;
                            });
                        }
                    }
                }
            } catch (error) {
                console.error("Error in chat:", error);
                setMessages((prev) => [
                    ...prev,
                    { role: "assistant", content: `Error: ${error.message}` },
                ]);
            } finally {
                setLoading(false);
            }
        },
        [messages, mode],
    );

    const clearChat = useCallback(() => {
        setMessages([]);
        setUserInput("");
        setShowSuggestions(true);
    }, []);

    return {
        chatExpanded,
        setChatExpanded,
        messages,
        setMessages,
        userInput,
        setUserInput,
        showSuggestions,
        setShowSuggestions,
        loading,
        sendMessage,
        clearChat,
    };
};

import { useState, useCallback, useRef } from "react";

// Replaces Chakra v2's useClipboard (removed in v3). Returns { onCopy, hasCopied }.
// `text` may be a string or a () => string. `hasCopied` resets after `timeout` ms.
export function useClipboard(text, { timeout = 1500 } = {}) {
  const [hasCopied, setHasCopied] = useState(false);
  const timerRef = useRef(null);

  const onCopy = useCallback(() => {
    const value = typeof text === "function" ? text() : text;
    try {
      navigator.clipboard?.writeText(value ?? "");
    } catch {
      /* clipboard unavailable */
    }
    setHasCopied(true);
    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => setHasCopied(false), timeout);
  }, [text, timeout]);

  return { onCopy, hasCopied };
}

// Custom hook for managing collapse/expand state of a component.
import { useCallback, useMemo, useState } from "react";

export const useCollapse = (initialState = true) => {
    const [isCollapsed, setIsCollapsed] = useState(initialState);

    const toggle = useCallback(() => setIsCollapsed((prev) => !prev), []);

    return useMemo(
        () => ({ isCollapsed, setIsCollapsed, toggle }),
        [isCollapsed, toggle],
    );
};

import { useCallback, useEffect, useMemo, useState } from "react";
import useSWR from "swr";
import { landingApi } from "../api/landingApi";
import { KEYS } from "../cache/keys";

export const useDashboardTodos = ({
  initialShowAll = false,
  initialCollapsed = true,
  autoFetch = true,
} = {}) => {
  const [newTodo, setNewTodo] = useState("");
  const [showAllTodos, setShowAllTodos] = useState(initialShowAll);
  const [isCollapsed, setIsCollapsed] = useState(initialCollapsed);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState(null);

  const {
    data: todos = [],
    isValidating: isLoading,
    error: fetchError,
    mutate: mutateTodos,
  } = useSWR(autoFetch ? KEYS.TODOS : null, async () => {
    const data = await landingApi.fetchTodos();
    return Array.isArray(data?.todos) ? data.todos : [];
  });

  useEffect(() => {
    if (fetchError) {
      setError(fetchError);
      console.error("Error fetching todos:", fetchError);
    }
  }, [fetchError]);

  const visibleTodos = useMemo(
    () => (showAllTodos ? todos : todos.filter((todo) => !todo.completed)),
    [showAllTodos, todos],
  );

  const refreshTodos = useCallback(() => mutateTodos(), [mutateTodos]);

  const addTodo = useCallback(async () => {
    const task = newTodo.trim();
    if (!task) return null;

    setIsSaving(true);
    setError(null);

    try {
      const response = await landingApi.addTodo(task);
      const createdTodo = response?.todo ?? null;

      if (createdTodo) {
        mutateTodos((prev) => [...prev, createdTodo], { revalidate: false });
      } else {
        await mutateTodos();
      }

      setNewTodo("");
      return createdTodo;
    } catch (err) {
      setError(err);
      console.error("Error adding todo:", err);
      return null;
    } finally {
      setIsSaving(false);
    }
  }, [newTodo, mutateTodos]);

  const toggleTodo = useCallback(
    async (todoId) => {
      setIsSaving(true);
      setError(null);

      try {
        const existing = todos.find((todo) => todo.id === todoId);
        if (!existing) return null;

        const response = await landingApi.toggleTodo(
          todoId,
          existing.completed,
          existing.task,
        );

        if (response?.todo) {
          mutateTodos(
            (prev) =>
              prev.map((todo) =>
                todo.id === todoId ? response.todo : todo,
              ),
            { revalidate: false },
          );
          return response.todo;
        }

        await mutateTodos();
        return null;
      } catch (err) {
        setError(err);
        console.error("Error toggling todo:", err);
        return null;
      } finally {
        setIsSaving(false);
      }
    },
    [todos, mutateTodos],
  );

  const deleteTodo = useCallback(
    async (todoId) => {
      setIsSaving(true);
      setError(null);

      try {
        await landingApi.deleteTodo(todoId);
        mutateTodos(
          (prev) => prev.filter((todo) => todo.id !== todoId),
          { revalidate: false },
        );
        return true;
      } catch (err) {
        setError(err);
        console.error("Error deleting todo:", err);
        return false;
      } finally {
        setIsSaving(false);
      }
    },
    [mutateTodos],
  );

  const handleTodoKeyDown = useCallback(
    async (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        await addTodo();
      }
    },
    [addTodo],
  );

  const toggleCollapsed = useCallback(() => {
    setIsCollapsed((prev) => !prev);
  }, []);

  return {
    todos,
    visibleTodos,
    newTodo,
    setNewTodo,
    showAllTodos,
    setShowAllTodos,
    isCollapsed,
    setIsCollapsed,
    toggleCollapsed,
    isLoading,
    isSaving,
    error,
    refreshTodos,
    addTodo,
    toggleTodo,
    deleteTodo,
    handleTodoKeyDown,
  };
};

export default useDashboardTodos;

import { useState, useEffect } from "react";

/**
 * Custom hook that debounces a value
 * @param {*} value - The value to debounce
 * @param {number} delay - The debounce delay in milliseconds (default: 500ms)
 * @returns {*} - The debounced value
 */
export const useDebounce = (value, delay = 500) => {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(timer);
    };
  }, [value, delay]);

  return debouncedValue;
};

import { useState } from "react";
import { toaster } from "@/components/ui/toaster";

export const useDocumentExtraction = ({
    patient,
    setPatient,
    setIsModified,
}) => {
    const [originalContent, setOriginalContent] = useState({});
    const [replacedFields, setReplacedFields] = useState({});
    const [extractedDocData, setExtractedDocData] = useState(null);
    const [docFileName, setDocFileName] = useState("");

    const handleDocumentComplete = (data) => {
        if (!data.fieldByField) {
            if (!extractedDocData) {
                setOriginalContent({ ...patient.template_data });
            }

            setExtractedDocData(data);

            toaster.create({
                title: "Document processed",
                description: "Use the toggle buttons to update fields",
                type: "success",
                duration: 3000,
            });
        } else {
            const fieldKey = Object.keys(data.fields)[0];

            setReplacedFields((prev) => ({
                ...prev,
                [fieldKey]: !prev[fieldKey],
            }));

            setPatient((prev) => ({
                ...prev,
                template_data: {
                    ...prev.template_data,
                    ...data.fields,
                },
            }));

            setIsModified(true);
        }
    };

    const toggleDocumentField = (fieldKey) => {
        if (!extractedDocData) return;

        const hasExtractedContent = Boolean(
            extractedDocData.fields[fieldKey]?.trim(),
        );
        if (!hasExtractedContent) {
            toaster.create({
                title: "No content available",
                description:
                    "This field doesn't have any content in the uploaded document",
                type: "info",
                duration: 2000,
            });
            return;
        }

        const isCurrentlyReplaced = replacedFields[fieldKey];

        let fieldContent;
        if (isCurrentlyReplaced) {
            fieldContent = originalContent[fieldKey] || "";
        } else {
            fieldContent = extractedDocData.fields[fieldKey] || "";
        }

        handleDocumentComplete({
            fields: { [fieldKey]: fieldContent },
            fieldByField: true,
        });
    };

    const resetDocumentState = () => {
        setExtractedDocData(null);
        setReplacedFields({});
        setOriginalContent({});
        setDocFileName("");
    };

    return {
        extractedDocData,
        replacedFields,
        docFileName,
        setDocFileName,
        handleDocumentComplete,
        toggleDocumentField,
        resetDocumentState,
    };
};

import { useCallback, useState } from "react";
import { letterApi } from "../api/letterApi";
import { validateLetterData } from "../helpers/validationHelpers";
import { useToastMessage } from "./UseToastMessage";

export const useLetter = (setIsModified) => {
    const [loading, setLoading] = useState(false);
    const [finalCorrespondence, setFinalCorrespondence] = useState("");
    const [letterContext, setLetterContext] = useState([]);
    const [saveState, setSaveState] = useState("idle"); // Added saveState
    const { showSuccessToast, showErrorToast } = useToastMessage();

    const generateLetter = async (patient, additionalInstructions) => {
        // Clear context at the start of generation
        setLetterContext([]);
        // We require both template_data and a template key
        if (!patient?.template_data || !patient?.template_key) {
            showErrorToast(
                "Patient data and template are required for letter generation",
            );
            return;
        }

        setLoading(true);
        try {
            // Validate that necessary fields exist
            validateLetterData({
                patientName: patient.name,
                gender: patient.gender,
                dob: patient.dob,
            });

            // If no additional instructions were provided, use default instructions from the template
            if (!additionalInstructions) {
                const responseTemplates =
                    await letterApi.fetchLetterTemplates();
                if (
                    responseTemplates &&
                    responseTemplates.default_template_id
                ) {
                    const defaultTemplate = responseTemplates.templates.find(
                        (tpl) =>
                            tpl.id === responseTemplates.default_template_id,
                    );
                    if (defaultTemplate) {
                        additionalInstructions =
                            defaultTemplate.instructions || "";
                    }
                }
            }

            // Call the generateLetter API with the required fields (context is null on first generation)
            const response = await letterApi.generateLetter({
                patientName: patient.name,
                gender: patient.gender,
                dob: patient.dob,
                template_data: patient.template_data,
                additional_instruction: additionalInstructions,
                context: null,
            });
            setFinalCorrespondence(response.letter);
            setIsModified(true);
            showSuccessToast("Letter generated successfully");
        } catch (error) {
            console.error("Error generating letter:", error);
            showErrorToast(error.message || "Failed to generate letter");
        } finally {
            setLoading(false);
        }
    };

    const saveLetter = async (noteId) => {
        if (!noteId || !finalCorrespondence) {
            showErrorToast("Patient ID and letter content are required");
            return;
        }

        setSaveState("saving");
        try {
            await letterApi.saveLetter(noteId, finalCorrespondence);
            setIsModified(false);
            setSaveState("saved");
            setTimeout(() => setSaveState("idle"), 2000);
            showSuccessToast("Letter saved successfully");
        } catch (error) {
            console.error("Error saving letter:", error);
            setSaveState("idle");
            showErrorToast(error.message || "Failed to save letter");
            throw error; // Propagate error to handle in component
        }
    };

    async function refineLetter({
        patient,
        additionalInstructions,
        refinementInput,
        onSuccess = () => {},
    }) {
        if (!refinementInput.trim()) return;

        setLoading(true);
        try {
            // Start with a copy of the current letter context.
            let updatedContext = [...letterContext];

            // If there is no context yet but we have an initial generated letter,
            // include it as the first assistant message.
            if (updatedContext.length === 0 && finalCorrespondence) {
                updatedContext.push({
                    role: "assistant",
                    content: finalCorrespondence,
                });
            }

            // Add the user's refinement message.
            updatedContext.push({
                role: "user",
                content: refinementInput,
            });

            // Call the generateLetter API; the server truncates the context
            const response = await letterApi.generateLetter({
                patientName: patient.name,
                gender: patient.gender,
                dob: patient.dob,
                template_data: patient.template_data,
                additional_instruction: additionalInstructions,
                context: updatedContext,
            });

            // Append the assistant's response.
            const newContext = [
                ...(response.context || []),
                {
                    role: "assistant",
                    content: response.letter,
                },
            ];

            setLetterContext(newContext);
            setFinalCorrespondence(response.letter);
            setIsModified(true);
            onSuccess();
            showSuccessToast("Letter refined successfully");
        } catch (error) {
            console.error("Refinement error:", error);
            showErrorToast("Failed to refine letter");
        } finally {
            setLoading(false);
        }
    }

    function clearLetterContext() {
        setLetterContext([]);
    }

    async function loadLetter(noteId) {
        setLoading(true);
        try {
            const response = await letterApi.fetchLetter(noteId);
            setFinalCorrespondence(
                response.letter || "No letter attached to encounter",
            );
            setIsModified(false);
        } catch (error) {
            console.error("Error loading letter:", error);
            setFinalCorrespondence("No letter attached to encounter");
            showErrorToast("Failed to load letter");
        } finally {
            setLoading(false);
        }
    }

    const resetLetter = useCallback(() => {
        setFinalCorrespondence("");
        setLetterContext([]);
        setIsModified(false);
    }, [setIsModified]);

    return {
        loading,
        finalCorrespondence,
        setFinalCorrespondence,
        generateLetter,
        saveLetter,
        loadLetter,
        resetLetter,
        refineLetter,
        letterContext,
        setLetterContext,
        clearLetterContext,
        saveState,
        setSaveState,
    };
};

import { useEffect, useCallback } from "react";
import { useLetter } from "./useLetter";

export const useLetterOrchestration = ({
    patient,
    setIsModified,
    onResetLetter,
    openLetter,
    toast,
}) => {
    const letterHook = useLetter(setIsModified);
    const { loadLetter, generateLetter, saveLetter, setFinalCorrespondence, resetLetter } = letterHook;

    // Load letter when patient changes
    useEffect(() => {
        if (patient?.id) {
            loadLetter(patient.id, toast);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [patient?.id]);

    // Pipe resetLetter up to App via onResetLetter prop
    useEffect(() => {
        if (onResetLetter) {
            onResetLetter(resetLetter);
        }
    }, [onResetLetter, resetLetter]);

    const handleGenerateLetterClick = useCallback(
        async (additionalInstructions) => {
            if (!patient) return;
            openLetter();
            await generateLetter(
                patient,
                additionalInstructions,
                toast,
                setFinalCorrespondence,
            );
        },
        [patient, openLetter, toast, generateLetter, setFinalCorrespondence],
    );

    const handleLetterSave = async () => {
        await saveLetter(patient.id);
        setIsModified(false);
    };

    // Wrap setFinalCorrespondence to also flip the modified flag
    const setFinalCorrespondenceWithFlag = useCallback(
        (value) => {
            setFinalCorrespondence(value);
            setIsModified(true);
        },
        [setIsModified, setFinalCorrespondence],
    );

    return {
        finalCorrespondence: letterHook.finalCorrespondence,
        loading: letterHook.loading,
        setFinalCorrespondence: setFinalCorrespondenceWithFlag,
        handleGenerateLetterClick,
        handleLetterSave,
        // Direct pass-through — letterHook.refineLetter is stable from useLetter
        handleRefineLetter: letterHook.refineLetter,
        // setIsModified is consumed by LetterPanel's onLetterChange — pass through
        setIsModified,
    };
};

import { useState, useEffect } from "react";
import { letterApi } from "../api/letterApi";
import { settingsApi } from "../api/settingsApi";

export const useLetterTemplates = (noteId) => {
    const [letterTemplates, setLetterTemplates] = useState([]);
    const [defaultTemplateId, setDefaultTemplateId] = useState(null);
    const [selectedTemplate, setSelectedTemplate] = useState(null);
    const [additionalInstructions, setAdditionalInstructions] = useState("");
    const [options, setOptions] = useState(null);

    // Fetch options (settings)
    useEffect(() => {
        const fetchOptions = async () => {
            try {
                const response = await settingsApi.fetchOptions();
                setOptions(response);
            } catch (error) {
                console.error("Failed to fetch options:", error);
            }
        };
        fetchOptions();
    }, []);

    // Fetch letter templates
    useEffect(() => {
        if (!noteId) return;

        letterApi
            .fetchLetterTemplates()
            .then((response) => {
                setLetterTemplates(response.templates);
                if (response.default_template_id) {
                    setDefaultTemplateId(response.default_template_id);

                    // Reset to default template when patient changes or component mounts
                    const defaultTpl = response.templates.find(
                        (t) => t.id === response.default_template_id,
                    );
                    if (defaultTpl) {
                        setSelectedTemplate(defaultTpl);
                        // Set initial instructions from default template
                        setAdditionalInstructions(
                            defaultTpl.instructions || "",
                        );
                    }
                }
            })
            .catch((err) =>
                console.error("Error fetching letter templates:", err),
            );
    }, [noteId]);

    const selectTemplate = (template) => {
        if (template === "custom") {
            setSelectedTemplate("custom");
        } else {
            setSelectedTemplate(template);
            setAdditionalInstructions(template.instructions || "");
        }
    };

    const getInstructions = () => {
        if (selectedTemplate === "custom") {
            return additionalInstructions;
        } else if (selectedTemplate && selectedTemplate.instructions) {
            return selectedTemplate.instructions;
        } else if (!selectedTemplate && defaultTemplateId) {
            const defaultTpl = letterTemplates.find(
                (t) => t.id === defaultTemplateId,
            );
            return defaultTpl
                ? defaultTpl.instructions
                : additionalInstructions;
        }
        return additionalInstructions;
    };

    return {
        letterTemplates,
        defaultTemplateId,
        selectedTemplate,
        additionalInstructions,
        setAdditionalInstructions,
        options,
        selectTemplate,
        getInstructions,
    };
};

import { useState, useEffect, useCallback } from "react";
import { toaster } from "@/components/ui/toaster";
import { localModelApi } from "../api/localModelApi";
import { invoke } from "@tauri-apps/api/core";
import { downloadLlmModel as downloadLlmService, downloadWhisperModel as downloadWhisperService } from "../services/localModelService";

export const useLocalModels = () => {
  const [models, setModels] = useState([]);
  const [availableModels, setAvailableModels] = useState([]);
  const [loading, setLoading] = useState(false);
  const [localStatus, setLocalStatus] = useState(null);
  const [systemSpecs, setSystemSpecs] = useState(null);

  // Download progress state for LLM models
  const [downloadProgress, setDownloadProgress] = useState({
    llm: null, // { percentage, downloadedBytes, totalBytes, speedBytesPerSec, etaSeconds }
    whisper: null,
  });
  const [isDownloading, setIsDownloading] = useState({
    llm: false,
    whisper: false,
  });
  const [downloadingModelId, setDownloadingModelId] = useState({
    llm: null,
    whisper: null,
  });

  // Whisper models state
  const [whisperModels, setWhisperModels] = useState([]);
  const [whisperRecommendations, setWhisperRecommendations] = useState([]);
  const [whisperStatus, setWhisperStatus] = useState(null);


  // Fetch system specifications
  const fetchSystemSpecs = useCallback(async () => {
    try {
      const specs = await invoke("get_system_specs");
      setSystemSpecs(specs);
      return specs;
    } catch (error) {
      console.error("Error getting system specs:", error);
      toaster.create({
        title: "Warning",
        description: "Could not retrieve system specifications",
        type: "warning",
        duration: 3000,
      });
      return null;
    }
  }, []);

  // Fetch downloaded local models
  const fetchLocalModels = useCallback(async () => {
    try {
      const response = await localModelApi.fetchLocalModels();
      setModels(response.models || []);
      return response.models || [];
    } catch (error) {
      console.error("Error fetching local models:", error);
      setModels([]);
      return [];
    }
  }, []);

  // Fetch available pre-configured models
  const fetchAvailableModels = useCallback(async () => {
    try {
      const response = await localModelApi.fetchAvailableLlmModels();
      setAvailableModels(response.models || []);
      return response.models || [];
    } catch (error) {
      console.error("Error fetching available models:", error);
      setAvailableModels([]);
      return [];
    }
  }, []);

  // Check local status
  const checkLocalStatus = useCallback(async () => {
    try {
      const response = await localModelApi.checkLocalStatus();
      setLocalStatus(response);
      return response;
    } catch (error) {
      console.error("Error checking local status:", error);
      setLocalStatus(null);
      return null;
    }
  }, []);

  // Download LLM model (supports both pre-configured and custom)
  const downloadLlmModel = useCallback(
    async (modelId) => {
      setIsDownloading((prev) => ({ ...prev, llm: true }));
      setDownloadingModelId((prev) => ({ ...prev, llm: modelId }));
      setDownloadProgress((prev) => ({ ...prev, llm: { percentage: 0 } }));

      try {
        await downloadLlmService(modelId, {
          onStart: () => {
            setDownloadProgress((prev) => ({
              ...prev,
              llm: { percentage: 0, status: "starting" },
            }));
          },
          onProgress: (event) => {
            setDownloadProgress((prev) => ({
              ...prev,
              llm: {
                percentage: event.percentage,
                downloadedBytes: event.downloaded_bytes,
                totalBytes: event.total_bytes,
                speedBytesPerSec: event.speed_bytes_per_sec,
                etaSeconds: event.eta_seconds,
                currentFile: event.current_file,
              },
            }));
          },
        });

        // Refresh models after successful download
        await fetchLocalModels();
      } finally {
        setIsDownloading((prev) => ({ ...prev, llm: false }));
        setDownloadingModelId((prev) => ({ ...prev, llm: null }));
        setDownloadProgress((prev) => ({ ...prev, llm: null }));
      }
    },
    [fetchLocalModels],
  );

  // Delete LLM model
  const deleteLlmModel = useCallback(
    async (filename) => {
      try {
        await localModelApi.deleteLlmModel(filename);
        await fetchLocalModels();
        toaster.create({
          title: "Success",
          description: `Model deleted successfully`,
          type: "success",
          duration: 3000,
        });
      } catch (error) {
        console.error("Error deleting model:", error);
        toaster.create({
          title: "Error",
          description: `Failed to delete model: ${error.message}`,
          type: "error",
          duration: 5000,
        });
      }
    },
    [fetchLocalModels],
  );

  // ========== Whisper Model Functions ==========

  // Fetch Whisper models
  const fetchWhisperModels = useCallback(async () => {
    try {
      const response = await localModelApi.fetchWhisperModels();
      setWhisperModels(response.models || []);
      return response.models || [];
    } catch (error) {
      console.error("Error fetching Whisper models:", error);
      setWhisperModels([]);
      return [];
    }
  }, []);

  // Fetch Whisper model recommendations
  const fetchWhisperRecommendations = useCallback(async () => {
    try {
      const response = await localModelApi.fetchWhisperRecommendations();
      setWhisperRecommendations(response.models || []);
      return response.models || [];
    } catch (error) {
      console.error("Error fetching Whisper recommendations:", error);
      setWhisperRecommendations([]);
      return [];
    }
  }, []);

  // Fetch Whisper status
  const fetchWhisperStatus = useCallback(async () => {
    try {
      const response = await localModelApi.fetchWhisperStatus();
      setWhisperStatus(response);
      return response;
    } catch (error) {
      console.error("Error fetching Whisper status:", error);
      setWhisperStatus(null);
      return null;
    }
  }, []);

  // Download Whisper model
  const downloadWhisperModel = useCallback(
    async (modelId) => {
      setIsDownloading((prev) => ({ ...prev, whisper: true }));
      setDownloadingModelId((prev) => ({ ...prev, whisper: modelId }));
      setDownloadProgress((prev) => ({ ...prev, whisper: { percentage: 0 } }));

      try {
        await downloadWhisperService(modelId, {
          onStart: () => {
            setDownloadProgress((prev) => ({
              ...prev,
              whisper: { percentage: 0, status: "starting" },
            }));
          },
          onProgress: (event) => {
            setDownloadProgress((prev) => ({
              ...prev,
              whisper: {
                percentage: event.percentage,
                downloadedBytes: event.downloaded_bytes,
                totalBytes: event.total_bytes,
                speedBytesPerSec: event.speed_bytes_per_sec,
                etaSeconds: event.eta_seconds,
                currentFile: event.current_file,
              },
            }));
          },
        });

        // Refresh models after successful download
        await fetchWhisperModels();
      } finally {
        setIsDownloading((prev) => ({ ...prev, whisper: false }));
        setDownloadingModelId((prev) => ({ ...prev, whisper: null }));
        setDownloadProgress((prev) => ({ ...prev, whisper: null }));
      }
    },
    [fetchWhisperModels],
  );

  // Delete Whisper model
  const deleteWhisperModel = useCallback(
    async (modelId) => {
      try {
        await localModelApi.deleteWhisperModel(modelId);
        await fetchWhisperModels();
        toaster.create({
          title: "Success",
          description: `Whisper model ${modelId} deleted successfully`,
          type: "success",
          duration: 3000,
        });
      } catch (error) {
        console.error("Error deleting Whisper model:", error);
        toaster.create({
          title: "Error",
          description: `Failed to delete Whisper model: ${error.message}`,
          type: "error",
          duration: 5000,
        });
      }
    },
    [fetchWhisperModels],
  );

  // Initialize data on mount
  useEffect(() => {
    const initializeData = async () => {
      await Promise.all([
        fetchSystemSpecs(),
        fetchLocalModels(),
        fetchAvailableModels(),
        checkLocalStatus(),
        fetchWhisperModels(),
        fetchWhisperRecommendations(),
        fetchWhisperStatus(),
      ]);
    };

    initializeData();
  }, [
    fetchSystemSpecs,
    fetchLocalModels,
    fetchAvailableModels,
    checkLocalStatus,
    fetchWhisperModels,
    fetchWhisperRecommendations,
    fetchWhisperStatus,
  ]);

  // Refresh all data
  const refreshData = useCallback(async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchLocalModels(),
        fetchAvailableModels(),
        checkLocalStatus(),
        fetchWhisperModels(),
        fetchWhisperStatus(),
      ]);
    } finally {
      setLoading(false);
    }
  }, [
    fetchLocalModels,
    fetchAvailableModels,
    checkLocalStatus,
    fetchWhisperModels,
    fetchWhisperStatus,
  ]);

  return {
    // State
    models,
    availableModels,
    loading,
    localStatus,
    systemSpecs,
    modelRecommendations: availableModels,
    downloadProgress,
    isDownloading,
    downloadingModelId,

    // Whisper state
    whisperModels,
    whisperRecommendations,
    whisperStatus,

    // Actions
    downloadLlmModel,
    deleteLlmModel,
    refreshData,

    // Whisper actions
    downloadWhisperModel,
    deleteWhisperModel,
    restartWhisperServer: () => localModelApi.restartWhisperServer(),
  };
};

