import { useEffect, useRef } from "react";
import { toaster } from "@/components/ui/toaster";
import {
    useTemplateSelection,
    useTemplate,
} from "../templates/templateContext";
import { useToastMessage } from "./UseToastMessage";

export const usePatientTemplate = ({
    patient,
    setPatient,
    isNewPatient,
    isSearchedPatient,
    initialPatient,
    isSearchLoading,
}) => {
    const { showWarningToast } = useToastMessage();
    const hasDefaultTemplateBeenSet = useRef(false);

    const {
        currentTemplate,
        isTemplateChanging,
        defaultTemplate,
        templates,
        status: templateStatus,
        error: templateError,
        selectTemplate,
    } = useTemplateSelection();

    const { refreshTemplates } = useTemplate();

    // Handle template errors
    useEffect(() => {
        if (templateError) {
            toaster.create({
                title: "Template Error",
                description: templateError,
                type: "error",
                duration: 5000,
            });
        }
    }, [templateError]);

    // Handle template consistency for already saved (historical) encounters
    useEffect(() => {
        if (!currentTemplate || !patient || isTemplateChanging) return;

        const shouldLockTemplate = !isNewPatient && !patient.isNewEncounter;

        if (
            shouldLockTemplate &&
            currentTemplate.template_key !== patient.template_key
        ) {
            selectTemplate(
                patient.template_key,
                "Maintaining historical template",
            );
        }
    }, [
        currentTemplate,
        patient,
        isNewPatient,
        selectTemplate,
        isTemplateChanging,
    ]);

    // Set default template for new patients
    useEffect(() => {
        const initializeNewPatient = async () => {
            if (isNewPatient && defaultTemplate && !patient?.template_key) {
                if (
                    !hasDefaultTemplateBeenSet.current &&
                    !patient?.template_key
                ) {
                    hasDefaultTemplateBeenSet.current = true;
                    try {
                        await selectTemplate(defaultTemplate.template_key);
                        setPatient((prev) => ({
                            ...prev,
                            template_key: defaultTemplate.template_key,
                        }));
                    } catch (error) {
                        console.error("Failed to set default template:", error);
                        toaster.create({
                            title: "Error",
                            description: "Failed to set default template",
                            type: "error",
                            duration: 3000,
                        });
                    }
                }
            }
        };
        initializeNewPatient();
    }, [
        isNewPatient,
        defaultTemplate,
        patient,
        selectTemplate,
        setPatient,
    ]);

    // Handle template data for historical patients
    useEffect(() => {
        if (
            !isNewPatient &&
            initialPatient &&
            currentTemplate &&
            !isSearchLoading
        ) {
            const newTemplateData = {};
            currentTemplate.fields.forEach((field) => {
                newTemplateData[field.field_key] =
                    initialPatient.template_data?.[field.field_key] || "";
            });

            setPatient((prev) => ({
                ...prev,
                template_data: newTemplateData,
                isHistorical: true,
            }));
        }
    }, [
        isNewPatient,
        initialPatient,
        currentTemplate,
        setPatient,
        isSearchLoading,
    ]);

    useEffect(() => {
        const handleHistoricalTemplate = async () => {
            if (!isNewPatient && !isSearchedPatient) {
                console.log(
                    "Viewing historical encounter - keeping original template",
                );
                return;
            }

            if (
                patient?.template_key &&
                defaultTemplate?.template_key &&
                patient?.template_key !== defaultTemplate?.template_key &&
                templates?.length > 0 &&
                (isNewPatient || isSearchedPatient)
            ) {
                const activeTemplate = templates.find(
                    (t) => t.template_key === patient.template_key,
                );

                if (!activeTemplate) {
                    console.warn(
                        "Pre-fill template is not active. Finding fallback...",
                    );
                    const baseKey = patient.template_key.split("_")[0];
                    const latestVersion = templates
                        .filter((t) => t.template_key.startsWith(baseKey))
                        .sort((a, b) =>
                            b.template_key.localeCompare(a.template_key),
                        )[0];

                    const fallback =
                        latestVersion || defaultTemplate || templates[0];

                    if (fallback) {
                        if (fallback.template_key === patient.template_key)
                            return;

                        console.log(
                            `Upgrading pre-fill template to: ${fallback.template_key}`,
                        );

                        setPatient((prev) => ({
                            ...prev,
                            template_key: fallback.template_key,
                            template_data: {
                                ...prev.template_data,
                            },
                        }));

                        await selectTemplate(fallback.template_key);

                        if (
                            fallback.template_key !== patient.template_key &&
                            isSearchedPatient
                        ) {
                            showWarningToast(
                                `Using ${fallback.template_name} template for this new encounter.`,
                            );
                        }
                    }
                }
            }
        };

        handleHistoricalTemplate();
    }, [
        isNewPatient,
        isSearchedPatient,
        patient?.template_key,
        defaultTemplate?.template_key,
        templates,
        defaultTemplate,
        selectTemplate,
        setPatient,
        showWarningToast,
    ]);

    return {
        currentTemplate,
        isTemplateChanging,
        defaultTemplate,
        templates,
        templateStatus,
        templateError,
        selectTemplate,
        refreshTemplates,
    };
};

// Hook for managing PDF form templates, fields, and auto-detection.
import { useState, useEffect } from "react";
import { toaster } from "@/components/ui/toaster";
import { pdfFormsApi } from "../api/pdfFormsApi";
import { chatApi } from "../api/chatApi";
import { loadPdfDocument } from "../helpers/pdfVisionHelpers";
import { renderRulerOverlay } from "../pdf/renderGridOverlay";

const VALID_FIELD_TYPES = ["text", "checkbox", "date", "number"];

export const usePdfForms = () => {
  const [templates, setTemplates] = useState([]);
  const [templatesLoading, setTemplatesLoading] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [fields, setFields] = useState([]);
  const [selectedFieldId, setSelectedFieldId] = useState(null);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [showReplaceModal, setShowReplaceModal] = useState(false);
  const [showFillModal, setShowFillModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [isDrawingMode, setIsDrawingMode] = useState(false);
  const [activeFieldType, setActiveFieldType] = useState("text");
  const [visionCapable, setVisionCapable] = useState(false);
  const [detecting, setDetecting] = useState(false);


  const selectedField = fields.find((f) => f.id === selectedFieldId);

  useEffect(() => {
    const fetchTemplates = async () => {
      setTemplatesLoading(true);
      try {
        const data = await pdfFormsApi.fetchTemplates();
        setTemplates(data);
      } catch (error) {
        toaster.create({
          title: "Error",
          description: error.message,
          type: "error",
          duration: 3000,
        });
      } finally {
        setTemplatesLoading(false);
      }
    };
    fetchTemplates();
  }, []);

  // Check vision model capability on mount
  useEffect(() => {
    chatApi
      .getCurrentVisionCapability()
      .then((result) => setVisionCapable(Boolean(result?.vision_capable)))
      .catch(() => setVisionCapable(false));
  }, []);

  const handleTemplateCreated = (template) => {
    setTemplates((prev) => [template, ...prev]);
    setSelectedTemplate(template);
    setFields([]);
  };

  const handleTemplateSelected = async (id) => {
    try {
      const template = await pdfFormsApi.fetchTemplate(id);
      setSelectedTemplate(template);
      setFields(template.fields || []);
      setSelectedFieldId(null);
    } catch (error) {
      toaster.create({
        title: "Error",
        description: error.message,
        type: "error",
        duration: 3000,
      });
    }
  };

  const handleTemplateDeleted = (id) => {
    setTemplates((prev) => prev.filter((t) => t.id !== id));
    if (selectedTemplate?.id === id) {
      setSelectedTemplate(null);
      setFields([]);
    }
  };

  const handlePdfReplaced = (updated) => {
    setTemplates((prev) =>
      prev.map((t) => (t.id === updated.id ? { ...t, ...updated } : t)),
    );
    setSelectedTemplate(updated);
    setFields(updated.fields || []);
  };

  const handleOpenReplace = (tmpl) => {
    setSelectedTemplate(tmpl);
    setShowReplaceModal(true);
  };

  const handleSaveFields = async () => {
    if (!selectedTemplate) return;
    setSaving(true);
    try {
      await pdfFormsApi.saveFields(selectedTemplate.id, fields);
      toaster.create({
        title: "Saved",
        description: "Field definitions saved",
        type: "success",
        duration: 2000,
      });
    } catch (error) {
      toaster.create({
        title: "Error",
        description: error.message,
        type: "error",
        duration: 3000,
      });
    } finally {
      setSaving(false);
    }
  };

  const handleUpdateField = (updatedField) => {
    setFields((prev) =>
      prev.map((f) => (f.id === updatedField.id ? updatedField : f))
    );
  };

  const handleDeleteField = (fieldId) => {
    setFields((prev) => prev.filter((f) => f.id !== fieldId));
    if (selectedFieldId === fieldId) setSelectedFieldId(null);
  };

  const handleAutoDetectFields = async () => {
    if (!selectedTemplate) return;
    setDetecting(true);
    try {
      // 1. Fetch the PDF
      const pdfData = await pdfFormsApi.fetchTemplatePdf(selectedTemplate.id);

      // 2. Render pages to canvases with ruler overlay
      const doc = await loadPdfDocument({ data: pdfData });

      const rulerPages = [];
      for (let i = 1; i <= Math.min(doc.numPages, 6); i++) {
        const page = await doc.getPage(i);
        const viewport = page.getViewport({ scale: 1.75 });

        const canvas = document.createElement("canvas");
        canvas.width = viewport.width;
        canvas.height = viewport.height;
        const ctx = canvas.getContext("2d");

        await page.render({ canvasContext: ctx, viewport }).promise;
        const rulerDataUrl = renderRulerOverlay(canvas, { pageNumber: i });
        rulerPages.push({ page_number: i, data_url: rulerDataUrl });

        // Release memory
        canvas.width = 1;
        canvas.height = 1;
      }

      // 3. Send to server for VLM detection
      const result = await pdfFormsApi.detectFields(
        selectedTemplate.id,
        rulerPages
      );

      // 4. Convert percentages to PDF coordinates
      const pageHeights = selectedTemplate.page_heights || [];
      const detectedFields = (result.fields || []).map((f) => {
        const pageNum = Math.max(1, f.page_number || 1);
        const ph = pageHeights[pageNum - 1] || 792;
        const pw = ph * (8.5 / 11);

        // Sanitize field_type
        let fieldType = (f.field_type || "text").toLowerCase().trim();
        if (!VALID_FIELD_TYPES.includes(fieldType)) fieldType = "text";

        // Convert percentages to PDF points
        const x = ((f.x_pct || 0) / 100) * pw;
        const y = ph - (((f.y_pct || 0) + (f.height_pct || 5)) / 100) * ph; // PDF y is bottom-up
        const width = Math.max(1, ((f.width_pct || 10) / 100) * pw);
        const height = Math.max(1, ((f.height_pct || 5) / 100) * ph);

        return {
          id: `field_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
          name: f.name || "",
          description: "",
          field_type: fieldType,
          required: false,
          page_number: pageNum,
          x,
          y,
          width,
          height,
          font_size: 12,
        };
      });

      // 5. Set fields
      setFields(detectedFields);
      if (detectedFields.length > 0) {
        setSelectedFieldId(detectedFields[0].id);
      }

      // 6. Auto-save (strip id — storage generates its own)
      const savePayload = detectedFields.map(({ _id, ...rest }) => rest);
      await pdfFormsApi.saveFields(selectedTemplate.id, savePayload);
      toaster.create({
        title: "Fields detected",
        description: `Found ${detectedFields.length} fields`,
        type: "success",
        duration: 3000,
      });
    } catch (error) {
      toaster.create({
        title: "Detection failed",
        description: error.message,
        type: "error",
        duration: 4000,
      });
    } finally {
      setDetecting(false);
    }
  };

  return {
    templates,
    templatesLoading,
    selectedTemplate,
    fields,
    selectedField,
    selectedFieldId,
    saving,
    isDrawingMode,
    activeFieldType,
    visionCapable,
    detecting,
    showUploadModal,
    showReplaceModal,
    showFillModal,
    setShowUploadModal,
    setShowReplaceModal,
    setShowFillModal,
    setSelectedFieldId,
    setIsDrawingMode,
    setActiveFieldType,
    setFields,
    handleTemplateCreated,
    handleTemplateSelected,
    handleTemplateDeleted,
    handlePdfReplaced,
    handleOpenReplace,
    handleSaveFields,
    handleUpdateField,
    handleDeleteField,
    handleAutoDetectFields,
  };
};

// Hook for managing RAG document collections state and operations.
import { useState, useEffect } from "react";
import { useCollapse } from "./useCollapse";
import { ragApi } from "../api/ragApi";
import { toaster } from "@/components/ui/toaster";

export const useRagDocuments = () => {
  const [collections, setCollections] = useState([]);
  const [loading, setLoading] = useState(true);
  const [itemToDelete, setItemToDelete] = useState(null);

  const collapseExplorer = useCollapse(false);
  const collapseUploader = useCollapse(false);


  useEffect(() => {
    const fetchCollections = async () => {
      setLoading(true);
      try {
        const data = await ragApi.fetchCollections();
        setCollections(
          data.files.map((name) => ({ name, files: [], loaded: false }))
        );
      } catch (error) {
        toaster.create({
          title: "Error",
          description: error.message,
          type: "error",
          duration: 3000,
        });
      } finally {
        setLoading(false);
      }
    };
    fetchCollections();
  }, []);

  const handleDelete = async () => {
    try {
      if (itemToDelete.type === "file") {
        await ragApi.deleteFile(itemToDelete.collection, itemToDelete.name);
      } else {
        await ragApi.deleteCollection(itemToDelete.name);
      }
      const updatedCollections = await ragApi.fetchCollections();
      setCollections(
        updatedCollections.files.map((name) => ({
          name,
          files: [],
          loaded: false,
        }))
      );
      toaster.create({
        title: "Success",
        description: `${
          itemToDelete.type === "file" ? "File" : "Collection"
        } deleted successfully`,
        type: "success",
        duration: 3000,
      });
    } catch {
      toaster.create({
        title: "Error",
        description: `Failed to delete ${
          itemToDelete.type === "file" ? "file" : "collection"
        }`,
        type: "error",
        duration: 3000,
      });
    } finally {
      setItemToDelete(null);
    }
  };

  return {
    collections,
    setCollections,
    loading,
    itemToDelete,
    setItemToDelete,
    handleDelete,
    collapseExplorer,
    collapseUploader,
  };
};

import { useState, useRef, useEffect, useCallback } from "react";
import { toaster } from "@/components/ui/toaster";
const toast = toaster.create;
import { patientApi } from "../api/patientApi";


export const useReasoning = (options = {}) => {
    const { noteId, initialReasoning, onReasoningGenerated } = options;

    const [isReasoningOpen, setIsReasoningOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [reasoning, setReasoning] = useState(initialReasoning ?? null);
    const [status, setStatus] = useState(null);
    const [tabIndex, setTabIndex] = useState("0");
    const [dimensions, setDimensions] = useState({
        width: 500,
        height: 420,
    });
    const resizerRef = useRef(null);

    // Update reasoning when initialReasoning changes
    useEffect(() => {
        if (initialReasoning !== undefined) {
            setReasoning(initialReasoning);
        }
    }, [noteId, initialReasoning]);

    // Only provide API handler if noteId is available
    const handleGenerateReasoning = useCallback(async () => {
        if (!noteId) return;

        setLoading(true);
        setStatus("Initializing reasoning engine...");
        try {
            const res = await patientApi.generateReasoningStream(
                noteId,
                (statusMessage) => setStatus(statusMessage),
                toast,
            );
            setReasoning(res);
            if (onReasoningGenerated) {
                onReasoningGenerated(res);
            }
            setStatus(null);
        } catch (error) {
            console.error("Error generating reasoning:", error);
            setStatus(null);
        } finally {
            setLoading(false);
        }
    }, [noteId, onReasoningGenerated]);

    const openReasoning = useCallback(() => {
        setIsReasoningOpen(true);
    }, []);

    const closeReasoning = useCallback(() => {
        setIsReasoningOpen(false);
    }, []);

    const toggleReasoning = useCallback(() => {
        setIsReasoningOpen((prev) => !prev);
    }, []);

    const updateDimensions = useCallback((newDimensions) => {
        setDimensions((prev) => ({
            ...prev,
            ...newDimensions,
        }));
    }, []);

    const resetReasoning = useCallback(() => {
        setReasoning(null);
        setLoading(false);
        setStatus(null);
    }, []);

    // Resize handlers for drag functionality
    const handleMouseMove = useCallback((e) => {
        setDimensions((prev) => ({
            width: Math.max(
                350,
                prev.width -
                    (e.clientX -
                        resizerRef.current.getBoundingClientRect().left),
            ),
            height: Math.max(
                300,
                prev.height +
                    (e.clientY -
                        resizerRef.current.getBoundingClientRect().top),
            ),
        }));
    }, []);

    const handleMouseUp = useCallback(() => {
        window.removeEventListener("mousemove", handleMouseMove);
        // eslint-disable-next-line react-hooks/immutability -- self-referencing one-shot listener; binding resolves at call time, not capture time
        window.removeEventListener("mouseup", handleMouseUp);
    }, [handleMouseMove]);

    const handleMouseDown = useCallback((e) => {
        e.preventDefault();
        window.addEventListener("mousemove", handleMouseMove);
        window.addEventListener("mouseup", handleMouseUp);
    }, [handleMouseMove, handleMouseUp]);

    return {
        // Panel state
        isReasoningOpen,
        setIsReasoningOpen,
        reasoning,
        setReasoning,
        loading,
        setLoading,
        status,
        tabIndex,
        setTabIndex,
        dimensions,
        resizerRef,

        // Actions
        openReasoning,
        closeReasoning,
        toggleReasoning,
        updateDimensions,
        resetReasoning,
        handleGenerateReasoning: noteId ? handleGenerateReasoning : undefined,
        handleMouseDown,
    };
};

import { useCallback } from "react";
import { useDisclosure } from "@chakra-ui/react";
import useSWR from "swr";
import { toaster } from "@/components/ui/toaster";
import { patientApi } from "../api/patientApi";
import { DEFAULT_TOAST_CONFIG } from "../constants";
import { KEYS } from "../cache/keys";

const EMPTY_CONSENT = {
    scribe_consent_at: null,
    scribe_consent_declined_at: null,
};

export const useScribeConsent = ({
    urNumber,
    isAmbient,
    requiresConsentConfig,
    requiredDemographicsMet,
    startRecording,
    onRequireDemographics,
}) => {
    const { data: scribeConsent = EMPTY_CONSENT, mutate: mutateConsent } =
        useSWR(
            urNumber ? KEYS.scribeConsent(urNumber) : null,
            () => patientApi.fetchScribeConsent(urNumber),
        );
    const {
        open: isConsentOpen,
        onOpen: onOpenConsent,
        onClose: onCloseConsent,
    } = useDisclosure();

    const hasConsented = Boolean(scribeConsent?.scribe_consent_at);
    const hasDeclined =
        Boolean(scribeConsent?.scribe_consent_declined_at) && !hasConsented;
    const requireConsent = isAmbient && requiresConsentConfig;
    const canRecord =
        requiredDemographicsMet && !(requireConsent && !hasConsented);

    const handleBlockedRecord = useCallback(() => {
        if (!requiredDemographicsMet) {
            onRequireDemographics?.();
            return;
        }
        onOpenConsent();
    }, [requiredDemographicsMet, onRequireDemographics, onOpenConsent]);

    const handleConsentGranted = useCallback(async () => {
        if (!urNumber) return;
        try {
            const data = await patientApi.saveScribeConsent(urNumber, true);
            mutateConsent(data, { revalidate: false });
            onCloseConsent();
            await startRecording();
        } catch (error) {
            toaster.create({
                title: "Could not record consent",
                description: error.message,
                type: "error",
                ...DEFAULT_TOAST_CONFIG,
            });
        }
    }, [urNumber, onCloseConsent, startRecording, mutateConsent]);

    const handleConsentDeclined = useCallback(async () => {
        if (!urNumber) return;
        try {
            const data = await patientApi.saveScribeConsent(urNumber, false);
            mutateConsent(data, { revalidate: false });
            onCloseConsent();
        } catch (error) {
            toaster.create({
                title: "Could not record decision",
                description: error.message,
                type: "error",
                ...DEFAULT_TOAST_CONFIG,
            });
        }
    }, [urNumber, onCloseConsent, mutateConsent]);

    return {
        consent: scribeConsent,
        hasConsented,
        hasDeclined,
        canRecord,
        isConsentOpen,
        onCloseConsent,
        handleBlockedRecord,
        handleConsentGranted,
        handleConsentDeclined,
    };
};

import { useState, useEffect, useCallback } from "react";
import { findPatients } from "../patient/patientLoaders";

export const useSearchFlow = ({
    isNewPatient,
    viaModal,
    cameFromSearch,
    pathname,
    summarySetIsCollapsed,
}) => {
    const [isSearchLoading, setIsSearchLoading] = useState(false);
    const [isSearchedPatient, setIsSearchedPatient] = useState(
        Boolean(cameFromSearch),
    );
    const [searchResult, setSearchResult] = useState(null);
    const [startCardDismissed, setStartCardDismissed] = useState(
        Boolean(viaModal),
    );

    const showStartCard =
        isNewPatient && !isSearchedPatient && !startCardDismissed;

    // Mount-only: expand summary when arriving from search
    useEffect(() => {
        if (cameFromSearch) summarySetIsCollapsed?.(false);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Reset on route change (unless we got here via the modal shortcut)
    useEffect(() => {
        if (viaModal) return;
        if (!isNewPatient) {
            // eslint-disable-next-line react-hooks/set-state-in-effect -- legitimate route-change reset; remounting PatientDetails would lose chat/document state
            setIsSearchedPatient(false);
        }
        // eslint-disable-next-line react-hooks/set-state-in-effect -- legitimate route-change reset; see above
        setStartCardDismissed(false);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [pathname]);

    const handleSearch = useCallback(async (query) => {
        setIsSearchLoading(true);
        try {
            return await findPatients(query);
        } finally {
            setIsSearchLoading(false);
        }
    }, []);

    const handleConfirmCandidate = useCallback(
        async (candidate, selectedDate, loadCandidate) => {
            const loaded = await loadCandidate(candidate, selectedDate);
            setSearchResult(loaded);
            setIsSearchedPatient(true);
            summarySetIsCollapsed?.(false);
        },
        [summarySetIsCollapsed],
    );

    const dismissStartCard = useCallback(() => {
        setStartCardDismissed(true);
    }, []);

    const clearSearchResult = useCallback(() => setSearchResult(null), []);

    const reset = useCallback(() => {
        setIsSearchedPatient(false);
        setStartCardDismissed(false);
    }, []);

    return {
        isSearchLoading,
        isSearchedPatient,
        searchResult,
        startCardDismissed,
        showStartCard,
        handleSearch,
        handleConfirmCandidate,
        dismissStartCard,
        clearSearchResult,
        reset,
    };
};

import { useEffect, useCallback } from "react";
import { useBreakpointValue } from "@chakra-ui/react";
import { useCollapse } from "./useCollapse";

export const useSidebarState = () => {
    // True for base/sm breakpoints, false for larger screens
    const defaultCollapsed = useBreakpointValue({
        base: true,
        sm: true,
        md: false,
    });

    const { isCollapsed, setIsCollapsed } = useCollapse(defaultCollapsed);

    const isSmallScreen = useBreakpointValue({ base: true, md: false });

    // Update sidebar state whenever the breakpoint changes
    useEffect(() => {
        if (defaultCollapsed !== undefined) {
            setIsCollapsed(defaultCollapsed);
        }
    }, [defaultCollapsed, setIsCollapsed]);

    const toggleSidebar = useCallback(() => {
        setIsCollapsed((prev) => !prev);
    }, [setIsCollapsed]);

    return {
        isSidebarCollapsed: isCollapsed,
        setIsSidebarCollapsed: setIsCollapsed,
        toggleSidebar,
        isSmallScreen,
    };
};

import { useState, useCallback, useMemo } from "react";
import useSWR from "swr";
import { toolsApi } from "../api/toolsApi";
import { settingsApi } from "../api/settingsApi";
import { toastApiError, toastApiSuccess } from "../helpers/errorHandlers";
import { KEYS } from "../cache/keys";

const DEFAULT_DISABLED_TOOLS = ["pubmed_search", "wiki_search"];

export const useToolServers = () => {
    const [isLoading, setIsLoading] = useState(false);
    const [testingServerId, setTestingServerId] = useState(null);

    const {
        data: toolServers = [],
        mutate: mutateServers,
    } = useSWR(KEYS.TOOL_SERVERS, async () => {
        const data = await toolsApi.fetchToolServers();
        return data.servers || [];
    });

    const {
        data: userSettings = {},
        mutate: mutateUserSettings,
    } = useSWR(KEYS.USER_SETTINGS, () => settingsApi.fetchUserSettings());

    const disabledTools = useMemo(
        () => userSettings.disabled_tools || DEFAULT_DISABLED_TOOLS,
        [userSettings],
    );

    const refreshServers = useCallback(async () => {
        await mutateServers();
    }, [mutateServers]);

    const addServer = useCallback(
        async (serverData) => {
            setIsLoading(true);
            try {
                await toolsApi.addToolServer(serverData);
                await toolsApi.refreshTools();
                toastApiSuccess("Tool server added successfully");
                await mutateServers();
                return true;
            } catch (error) {
                console.error("Error adding tool server:", error);
                toastApiError("Failed to add tool server");
                return false;
            } finally {
                setIsLoading(false);
            }
        },
        [mutateServers],
    );

    const deleteServer = useCallback(
        async (serverId) => {
            setIsLoading(true);
            try {
                await toolsApi.deleteToolServer(serverId);
                await toolsApi.refreshTools();
                toastApiSuccess("Tool server deleted");
                await mutateServers();
                return true;
            } catch (error) {
                console.error("Error deleting tool server:", error);
                toastApiError("Failed to delete tool server");
                return false;
            } finally {
                setIsLoading(false);
            }
        },
        [mutateServers],
    );

    const toggleServer = useCallback(
        async (serverId, enabled) => {
            setIsLoading(true);
            try {
                await toolsApi.toggleToolServer(serverId, enabled);
                await toolsApi.refreshTools();
                toastApiSuccess(`Tool server ${enabled ? "enabled" : "disabled"}`);
                await mutateServers();
                return true;
            } catch (error) {
                console.error("Error toggling tool server:", error);
                toastApiError("Failed to toggle tool server");
                return false;
            } finally {
                setIsLoading(false);
            }
        },
        [mutateServers],
    );

    const toggleSensitiveData = useCallback(
        async (serverId, allowSensitive) => {
            setIsLoading(true);
            try {
                await toolsApi.updateToolServer(serverId, {
                    allow_sensitive_data: allowSensitive,
                });
                await toolsApi.refreshTools();
                toastApiSuccess(
                    `Sensitive data ${allowSensitive ? "allowed" : "sanitized"}`,
                );
                await mutateServers();
                return true;
            } catch (error) {
                console.error("Error toggling sensitive data:", error);
                toastApiError("Failed to update sensitive data setting");
                return false;
            } finally {
                setIsLoading(false);
            }
        },
        [mutateServers],
    );

    const testServer = useCallback(async (serverId) => {
        setTestingServerId(serverId);
        try {
            const result = await toolsApi.testToolServer(serverId);
            if (result.success) {
                const toolCount = result.tools?.length || 0;
                const serverName = result.server_info?.name || "";
                const serverVersion = result.server_info?.version || "";
                const description = serverName
                    ? `${serverName}${serverVersion ? ` v${serverVersion}` : ""} - ${toolCount} tools`
                    : `Found ${toolCount} tools`;
                toastApiSuccess(description, "Connection Successful");
                return true;
            }
            toastApiError(
                result.message || "Failed to connect to server",
                "Connection Failed",
            );
            return false;
        } catch (error) {
            console.error("Error testing tool server:", error);
            toastApiError("Failed to test tool server");
            return false;
        } finally {
            setTestingServerId(null);
        }
    }, []);

    const toggleBuiltInTool = useCallback(
        async (toolName, enabled) => {
            const newDisabledTools = enabled
                ? disabledTools.filter((t) => t !== toolName)
                : [...disabledTools, toolName];

            try {
                await settingsApi.saveUserSettings({
                    ...userSettings,
                    disabled_tools: newDisabledTools,
                });
                // Optimistic local update; full revalidate via mutate
                mutateUserSettings(
                    (prev) => ({ ...prev, disabled_tools: newDisabledTools }),
                    { revalidate: false },
                );
                toastApiSuccess(`${toolName} ${enabled ? "enabled" : "disabled"}`);
                return true;
            } catch (error) {
                console.error("Error saving tool settings:", error);
                toastApiError("Failed to save tool settings");
                return false;
            }
        },
        [disabledTools, userSettings, mutateUserSettings],
    );

    const isToolEnabled = useCallback(
        (toolName) => !disabledTools.includes(toolName),
        [disabledTools],
    );

    return {
        toolServers,
        isLoading,
        testingServerId,
        userSettings,
        disabledTools,
        addServer,
        deleteServer,
        toggleServer,
        toggleSensitiveData,
        testServer,
        toggleBuiltInTool,
        isToolEnabled,
        refreshServers,
    };
};

import { useState } from "react";
import { transcriptionApi } from "../api/transcriptionApi";
import { extractFromFile } from "../helpers/documentExtraction";

export const useTranscription = (onTranscriptionComplete, setLoading) => {
    const [isTranscribing, setIsTranscribing] = useState(false);
    const [transcriptionError, setTranscriptionError] = useState(null);

    const transcribeAudio = async (audioBlob, metadata, isAmbient = true) => {
        setIsTranscribing(true);
        setTranscriptionError(null);
        if (setLoading) setLoading(true);

        try {
            const formData = new FormData();
            formData.append("file", audioBlob, "recording.wav");

            // Add metadata if provided
            if (metadata.name) formData.append("name", metadata.name);
            if (metadata.gender) formData.append("gender", metadata.gender);
            if (metadata.dob) formData.append("dob", metadata.dob);
            if (metadata.templateKey)
                formData.append("templateKey", metadata.templateKey);
            if (metadata.noteId) formData.append("noteId", metadata.noteId);
            formData.append("isAmbient", isAmbient);

            const data = await transcriptionApi.transcribeAudio(formData);

            if (onTranscriptionComplete) {
                onTranscriptionComplete(data, true);
            }

            return data;
        } catch (error) {
            setTranscriptionError(error.message);
            if (onTranscriptionComplete) {
                onTranscriptionComplete({ error: error.message });
            }
            throw error;
        } finally {
            setIsTranscribing(false);
            if (setLoading) setLoading(false);
        }
    };

    const reprocessTranscription = async (
        transcriptText,
        metadata,
        originalTranscriptionDuration,
        isAmbient = true,
    ) => {
        setIsTranscribing(true);
        setTranscriptionError(null);
        if (setLoading) setLoading(true);

        try {
            const formData = new FormData();
            formData.append("transcript_text", transcriptText);

            // Add metadata if provided
            if (metadata.name) formData.append("name", metadata.name);
            if (metadata.gender) formData.append("gender", metadata.gender);
            if (metadata.dob) formData.append("dob", metadata.dob);
            if (metadata.templateKey)
                formData.append("templateKey", metadata.templateKey);
            if (metadata.noteId) formData.append("noteId", metadata.noteId);
            formData.append("isAmbient", isAmbient);

            formData.append(
                "original_transcription_duration",
                originalTranscriptionDuration || 0,
            );

            const data =
                await transcriptionApi.reprocessTranscription(formData);

            if (onTranscriptionComplete) {
                onTranscriptionComplete(data, true);
            }

            return data;
        } catch (error) {
            setTranscriptionError(error.message);
            if (onTranscriptionComplete) {
                onTranscriptionComplete({ error: error.message });
            }
            throw error;
        } finally {
            setIsTranscribing(false);
            if (setLoading) setLoading(false);
        }
    };

    const processDocument = async (file, metadata, options = {}) => {
        setIsTranscribing(true);
        setTranscriptionError(null);
        if (setLoading) setLoading(true);

        try {
            const data = await extractFromFile(
                file,
                {
                    fromText: transcriptionApi.processDocumentFromText,
                    visual: transcriptionApi.processDocumentVisual,
                    legacyFile: (formData) =>
                        transcriptionApi.processDocument(formData),
                },
                metadata,
            );

            if (options.handleComplete) {
                options.handleComplete(data);
            }

            return data;
        } catch (error) {
            setTranscriptionError(error.message);
            if (options.handleError) {
                options.handleError(error);
            }
            throw error;
        } finally {
            setIsTranscribing(false);
            if (setLoading) setLoading(false);
        }
    };

    return {
        transcribeAudio,
        processDocument,
        reprocessTranscription,
        isTranscribing,
        transcriptionError,
    };
};

import { useState, useCallback } from "react";

export const useTranscriptionCapture = () => {
    const [hasTranscriptionOccurred, setHasTranscriptionOccurred] =
        useState(false);
    const [initialTranscriptionContent, setInitialTranscriptionContent] =
        useState({});

    const capture = useCallback((content) => {
