import { useState, useEffect, useCallback, useMemo } from "react";
import useSWR from "swr";
import { toaster } from "@/components/ui/toaster";
import { SPLASH_STEPS } from "../../../components/common/splash/constants";
import { validateTranscriptionStep } from "../../../utils/splash/validators";
import { settingsService } from "../../../utils/settings/settingsUtils";
import { localModelApi } from "../../api/localModelApi";
import { downloadWhisperModel as downloadWhisperService } from "../../services/localModelService";
import { useDebounce } from "../useDebounce";
import { KEYS } from "../../cache/keys";

export const useTranscriptionStep = (currentStep, inferenceMode = "remote", language = "en") => {

    // Remote mode state
    const [whisperBaseUrl, setWhisperBaseUrl] = useState(
        import.meta.env.VITE_WHISPER_BASE_URL || "http://localhost:8080",
    );
    const [whisperModel, setWhisperModel] = useState("");

    const debouncedWhisperBaseUrl = useDebounce(whisperBaseUrl, 500);

    const shouldFetchRemote =
        currentStep === SPLASH_STEPS.AI_MODELS &&
        inferenceMode === "remote" &&
        !!debouncedWhisperBaseUrl;

    const {
        data: whisperData,
        isValidating: isFetchingWhisperModels,
        mutate: mutateWhisperModels,
        error: whisperError,
    } = useSWR(
        shouldFetchRemote
            ? KEYS.whisperModels(inferenceMode, debouncedWhisperBaseUrl)
            : null,
        () =>
            new Promise((resolve) => {
                let models = [];
                let listAvailable = false;
                settingsService
                    .fetchWhisperModels(
                        debouncedWhisperBaseUrl,
                        (fetchedModels) => {
                            models = fetchedModels;
                        },
                        (isListAvailable) => {
                            listAvailable = isListAvailable;
                        },
                    )
                    .then(() => resolve({ models, listAvailable }))
                    .catch(() => resolve({ models: [], listAvailable: false }));
            }),
    );

    const availableWhisperModels = useMemo(
        () => whisperData?.models || [],
        [whisperData],
    );
    const whisperModelListAvailable = whisperData?.listAvailable || false;

    // Manual refetch hook for consumers
    const fetchWhisperModels = useCallback(() => {
        mutateWhisperModels();
    }, [mutateWhisperModels]);

    useEffect(() => {
        if (whisperError) {
            toaster.create({
                title: "Error fetching Whisper models",
                description:
                    whisperError.message ||
                    "Could not connect or provider returned an error.",
                type: "error",
                duration: 3000,
            });
        }
    }, [whisperError]);

    // Local mode state
    // For English, prefer Omi Med STT unless Parakeet is
    // already downloaded — then keep it to avoid a wasteful re-download.
    const recommendedLocalWhisperModel =
        language === "en" &&
        !downloadedWhisperModels.some((m) => m.id === "tdt-0.6b-v3-q8_0")
            ? "omi-med-stt-v1-q8_0"
            : "tdt-0.6b-v3-q8_0";
    const [localWhisperModels, setLocalWhisperModels] = useState([]);
    const [downloadedWhisperModels, setDownloadedWhisperModels] = useState([]);
    const [localWhisperModel, setLocalWhisperModel] = useState(
        recommendedLocalWhisperModel,
    );
    const [isDownloadingWhisper, setIsDownloadingWhisper] = useState(false);
    const [downloadingWhisperModelId, setDownloadingWhisperModelId] =
        useState(null);
    const [whisperDownloadProgress, setWhisperDownloadProgress] = useState(0);

    // Fetch local Whisper models
    const fetchLocalWhisperModels = useCallback(async () => {
        // Only fetch local models if in local mode
        if (inferenceMode === "remote") return;

        try {
            // Fetch available Whisper models
            const availableResponse =
                await localModelApi.fetchAvailableWhisperModels();
            setLocalWhisperModels(availableResponse.models || []);

            // Fetch downloaded Whisper models
            const downloadedResponse =
                await localModelApi.fetchDownloadedWhisperModels();
            setDownloadedWhisperModels(downloadedResponse.models || []);
        } catch (error) {
            console.error("Error fetching local Whisper models:", error);
            toaster.create({
                title: "Error fetching local Whisper models",
                description:
                    error.message ||
                    "Could not retrieve local Whisper model list.",
                type: "error",
                duration: 3000,
            });
        }
    }, [inferenceMode]);

    // Download local Whisper model
    const downloadWhisperModel = useCallback(
        async (modelId) => {
            setIsDownloadingWhisper(true);
            setDownloadingWhisperModelId(modelId);
            setWhisperDownloadProgress(0);

            try {
                await downloadWhisperService(modelId, {
                    onProgress: (progress) => {
                        if (progress.percentage !== undefined) {
                            setWhisperDownloadProgress(progress.percentage);
                        }
                    },
                });

                // Refresh downloaded models after completion
                await fetchLocalWhisperModels();
            } finally {
                setIsDownloadingWhisper(false);
                setDownloadingWhisperModelId(null);
                setWhisperDownloadProgress(0);
            }
        },
        [fetchLocalWhisperModels],
    );

    // Check if a Whisper model is downloaded
    const isWhisperModelDownloaded = useCallback(
        (modelId) => {
            return downloadedWhisperModels.some(
                (m) => m.id === modelId || m.name === modelId,
            );
        },
        [downloadedWhisperModels],
    );

    // Validate based on current mode
    const validate = useCallback(() => {
        if (inferenceMode === "local") {
            // Hard gate: the STT model must be downloaded before proceeding.
            return isWhisperModelDownloaded(localWhisperModel);
        } else {
            // For remote mode, use existing validation
            return validateTranscriptionStep(
                whisperBaseUrl,
                whisperModelListAvailable,
                availableWhisperModels,
                whisperModel,
            );
        }
    }, [
        inferenceMode,
        localWhisperModel,
        isWhisperModelDownloaded,
        whisperBaseUrl,
        whisperModelListAvailable,
        availableWhisperModels,
        whisperModel,
    ]);

    // Get data based on current mode
    const getData = useCallback(() => {
        if (inferenceMode === "local") {
            return {
                whisperBaseUrl: "", // Empty for local
                whisperModel: localWhisperModel,
            };
        } else {
            return {
                whisperBaseUrl,
                whisperModel,
            };
        }
    }, [inferenceMode, localWhisperModel, whisperBaseUrl, whisperModel]);

    // Local-mode fetch on step/mode change (remote is handled by useSWR)
    useEffect(() => {
        if (
            currentStep === SPLASH_STEPS.AI_MODELS &&
            inferenceMode === "local"
        ) {
            fetchLocalWhisperModels();
        }
    }, [fetchLocalWhisperModels, currentStep, inferenceMode]);

    // Keep the selected local STT model in sync with the preferred language.
    useEffect(() => {
        setLocalWhisperModel(recommendedLocalWhisperModel);
    }, [recommendedLocalWhisperModel]);

    return {
        // Remote mode
        whisperBaseUrl,
        setWhisperBaseUrl,
        whisperModel,
        setWhisperModel,
        availableWhisperModels,
        whisperModelListAvailable,
        isFetchingWhisperModels,
        fetchWhisperModels,

        // Local mode
        localWhisperModels,
        downloadedWhisperModels,
        localWhisperModel,
        setLocalWhisperModel,
        isDownloadingWhisper,
        downloadingWhisperModelId,
        whisperDownloadProgress,
        downloadWhisperModel,
        isWhisperModelDownloaded,

        // Shared
        validate,
        getData,
    };
};

import { useContext } from "react";
import { TemplateContext } from "../../templates/templateContext";

export const useTemplate = () => {
  const context = useContext(TemplateContext);
  if (!context) {
    throw new Error("useTemplate must be used within a TemplateProvider");
  }
  return {
    ...context,
    deleteTemplate: context.deleteTemplate,
  };
};

import { useContext, useCallback } from "react";
import { TemplateContext } from "../../templates/templateContext";

export const useTemplateSelection = () => {
  const context = useContext(TemplateContext);
  if (!context) {
    throw new Error(
      "useTemplateSelection must be used within a TemplateProvider",
    );
  }

  const {
    currentTemplate,
    templates,
    defaultTemplate,
    status,
    error,
    setActiveTemplate,
  } = context;

  const selectTemplate = useCallback(
    async (templateKey) => {
      if (!templateKey) {
        return null;
      }


      try {
        const template = await setActiveTemplate(templateKey);

        return template;
      } catch (error) {
        console.error(
          `Error selecting template with key "${templateKey}":`,
          error,
        );
        throw error;
      }
    },
    [setActiveTemplate],
  );

  return {
    currentTemplate,
    defaultTemplate,
    templates,
    status,
    error,
    selectTemplate,
  };
};

/**
 * Boot-time language storage.
 *
 * The user's preferred language lives in the encrypted database (user_settings),
 * which isn't open during the splash/encryption screens. We mirror it into
 * localStorage so the UI can render in the correct language from the very first
 * paint, then sync back to i18n once the app boots and settings are fetched.
 */

const STORAGE_KEY = "preferred_language";

/**
 * Get the language stored at boot, before the encrypted DB is available.
 * Falls back to "en".
 */
export const getStoredLanguage = () => {
    try {
        return localStorage.getItem(STORAGE_KEY) || "en";
    } catch {
        return "en";
    }
};

/**
 * Persist the preferred language to localStorage and apply it to i18n.
 * Called when user settings are loaded/saved.
 */
export const setStoredLanguage = (language) => {
    const lang = language || "en";
    try {
        localStorage.setItem(STORAGE_KEY, lang);
    } catch {
        // ignore storage failures
    }
};

/**
 * Language option lists.
 *
 *  - UI_LANGUAGES: locales that have a translation catalog in
 *    `src/locales/<code>/`. This is the only list selectable in the UI; a
 *    language appears here only once it is fully localised. See src/i18n.js
 *    for the steps to add a locale.
 */

// Locales with a UI translation catalog.
export const UI_LANGUAGES = [{ code: "en", name: "English", native: "English" }];

export const getLanguageName = (code) =>
    UI_LANGUAGES.find((l) => l.code === code)?.name || code;

// Functionality for specific patient actions such as saving, searching, and letter generation.
import { toaster } from "@/components/ui/toaster";
import { patientApi } from "../api/patientApi";
import { letterApi } from "../api/letterApi";

export const handleSavePatient = async (
    patient,
    toast,
    refreshSidebar,
    navigate,
) => {
    if (
        !patient ||
        !patient.name ||
        !patient.dob ||
        !patient.ur_number ||
        !patient.gender
    ) {
        toaster.create({
            title: "Missing Fields",
            description:
                "Name, Date of Birth, UR Number, and Gender must be filled in.",
            type: "error",
            duration: 3000,
        });
        return;
    }

    try {
        const savedPatient = await patientApi.savePatientData(
            patient,
            toast,
            refreshSidebar,
        );
        if (savedPatient && !patient.id) {
            navigate(`/note/${savedPatient.id}`);
        }
        return savedPatient;
    } catch (error) {
        console.error("Error saving patient:", error);
        throw error;
    }
};

export const handleLoadPatientDetails = async (noteId, setters) => {
    try {
        const patientData = await patientApi.fetchPatientDetails(
            noteId,
            setters,
        );
        return patientData;
    } catch (error) {
