import { PDFDocument, rgb, StandardFonts } from "pdf-lib";

/**
 * Fill a PDF form template with the provided values and return the completed PDF bytes.
 *
 * @param {Uint8Array} templatePdfBytes - Original PDF bytes
 * @param {Object} template - Template object with a `fields` array
 * @param {Object} values - Map of field name → string value
 * @returns {Promise<Uint8Array>} Modified PDF bytes
 */
export async function fillPdf(templatePdfBytes, template, values) {
    const pdfDoc = await PDFDocument.load(templatePdfBytes, {
        ignoreEncryption: true,
    });
    const font = await pdfDoc.embedFont(StandardFonts.Helvetica);

    for (const field of template.fields) {
        const value = values[field.name];
        if (
            value === undefined ||
            value === null ||
            String(value).trim() === ""
        )
            continue;

        const page = pdfDoc.getPage(field.page_number - 1); // 0-indexed

        switch (field.field_type) {
            case "text":
            case "date":
            case "number": {
                drawTextInField(page, field, String(value), font);
                break;
            }
            case "checkbox": {
                const v = String(value).toLowerCase();
                if (v === "true" || v === "1" || v === "yes") {
                    drawCheckmark(page, field, font);
                }
                break;
            }
        }
    }

    return pdfDoc.save();
}

/**
 * Draw text inside a field rectangle, with word-wrap for long text.
 */
function drawTextInField(page, field, value, font) {
    const fontSize = field.font_size || 12;
    const maxWidth = field.width - 4; // small padding

    const textWidth = font.widthOfTextAtSize(value, fontSize);

    if (textWidth <= maxWidth) {
        // Single line, vertically centered
        const yOffset = field.y + (field.height - fontSize) / 2;
        page.drawText(value, {
            x: field.x + 2,
            y: yOffset,
            size: fontSize,
            font,
            color: rgb(0, 0, 0),
        });
    } else {
        // Multi-line: word-wrap within the field
        const lines = wrapText(value, font, fontSize, maxWidth);
        const lineHeight = fontSize * 1.2;
        for (let i = 0; i < lines.length; i++) {
            const yPos = field.y + field.height - fontSize - i * lineHeight - 2;
            if (yPos < field.y) break; // don't overflow below field
            page.drawText(lines[i], {
                x: field.x + 2,
                y: yPos,
                size: fontSize,
                font,
                color: rgb(0, 0, 0),
            });
        }
    }
}

/**
 * Draw a centered checkmark in a checkbox field.
 */
function drawCheckmark(page, field, font) {
    const size = Math.min(field.font_size || 12, field.height * 0.8);
    // Use "x" — WinAnsi fonts (Helvetica) cannot encode "✓" (U+2713).
    const mark = "x";
    const xCenter =
        field.x + (field.width - font.widthOfTextAtSize(mark, size)) / 2;
    const yCenter = field.y + (field.height - size) / 2;
    page.drawText(mark, {
        x: xCenter,
        y: yCenter,
        size,
        font,
        color: rgb(0, 0, 0),
    });
}

/**
 * Word-wrap text to fit within maxWidth using font metrics.
 */
function wrapText(text, font, fontSize, maxWidth) {
    const words = text.split(/\s+/);
    const lines = [];
    let currentLine = "";

    for (const word of words) {
        const testLine = currentLine ? `${currentLine} ${word}` : word;
        const testWidth = font.widthOfTextAtSize(testLine, fontSize);
        if (testWidth > maxWidth && currentLine) {
            lines.push(currentLine);
            currentLine = word;
        } else {
            currentLine = testLine;
        }
    }
    if (currentLine) lines.push(currentLine);
    return lines;
}

/**
 * Ruler overlay renderer for PDF pages.
 *
 * Used for VLM-based auto field detection. The model reads
 * the ruler labels and returns percentage-based positions.
 *
 * @param {HTMLCanvasElement} pdfCanvas
 * @param {Object} options
 * @param {number} options.step - Percentage step between marks (default 10)
 * @param {string} options.color
 * @param {string} options.tickColor
 * @param {string} options.textColor
 * @param {number} options.pageNumber
 * @returns {string} Base64 data URL of the composite image
 */
export function renderRulerOverlay(pdfCanvas, options: Record<string, any> = {}) {
    const {
        step = 10,
        color = "rgba(0, 0, 255, 0.08)",
        tickColor = "rgba(0, 0, 255, 0.35)",
        textColor = "rgba(0, 0, 255, 0.55)",
        pageNumber,
    } = options;

    const { width, height } = pdfCanvas;

    // Composite canvas
    const composite = document.createElement("canvas");
    composite.width = width;
    composite.height = height;
    const ctx = composite.getContext("2d");

    // Draw the original PDF
    ctx.drawImage(pdfCanvas, 0, 0);

    // Faint full-width/height guide lines at each step
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    for (let pct = step; pct < 100; pct += step) {
        const x = Math.round((pct / 100) * width);
        const y = Math.round((pct / 100) * height);

        // Vertical guide
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();

        // Horizontal guide
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
    }

    // Tick marks and labels along top edge (horizontal ruler)
    ctx.strokeStyle = tickColor;
    ctx.lineWidth = 1.5;
    ctx.fillStyle = textColor;
    ctx.font = "bold 11px sans-serif";
    ctx.textAlign = "center";

    for (let pct = 0; pct <= 100; pct += step) {
        const x = Math.round((pct / 100) * width);

        // Tick mark
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, pct % (step * 2) === 0 ? 14 : 9);
        ctx.stroke();

        // Label (only at major marks)
        if (pct % (step * 2) === 0 || pct === 100) {
            ctx.fillText(`${pct}%`, x, 24);
        }
    }

    // Tick marks and labels along left edge (vertical ruler)
    ctx.textAlign = "left";

    for (let pct = 0; pct <= 100; pct += step) {
        const y = Math.round((pct / 100) * height);

        // Tick mark
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(pct % (step * 2) === 0 ? 14 : 9, y);
        ctx.stroke();

        // Label
        if (pct % (step * 2) === 0 || pct === 100) {
            ctx.fillText(`${pct}%`, 3, y - 3);
        }
    }

    // Page number label in top-right corner
    if (pageNumber) {
        const label = `PAGE ${pageNumber}`;
        ctx.font = "bold 13px sans-serif";
        ctx.textAlign = "right";
        ctx.fillStyle = "rgba(0, 0, 255, 0.7)";
        ctx.fillText(label, width - 4, 16);
    }

    return composite.toDataURL("image/png");
}

import { localModelApi } from "../api/localModelApi";
import { toaster } from "@/components/ui/toaster";

/**
 * Downloads an LLM model and restarts the llama server
 * @param {string} modelId - The model ID to download
 * @param {Object} options - Configuration options
 * @param {Function} options.onProgress - Callback for progress updates: (progress) => void
 * @param {Function} options.onStart - Callback when download starts: () => void
 * @returns {Promise<void>} - Resolves when complete, rejects on error
 */
export async function downloadLlmModel(modelId, { onProgress, onStart }) {
  try {
    for await (const event of localModelApi.streamDownloadLlmModel(modelId)) {
      if (event.type === "start") {
        onStart?.();
      } else if (event.type === "progress") {
        onProgress?.(event);
      } else if (event.type === "complete") {
        // Restart llama server to use the new model
        try {
          await localModelApi.restartLlamaServer();
          toaster.create({
            title: "Success",
            description: "Model downloaded and server restarted",
            type: "success",
            duration: 3000,
          });
        } catch (restartError) {
          // Model downloaded but restart failed - still notify user of success
          console.error("Error restarting llama server:", restartError);
          toaster.create({
            title: "Model Downloaded",
            description: "Model downloaded. Please restart the app to use it.",
            type: "info",
            duration: 5000,
          });
        }
      } else if (event.type === "error") {
        throw new Error(event.message);
      }
    }
  } catch (error) {
    console.error("Error downloading model:", error);
    toaster.create({
      title: "Error",
      description: `Failed to download model: ${error.message}`,
      type: "error",
      duration: 5000,
    });
    throw error;
  }
}

